COLLDATA("asabahur","ur",[[3094,"§۳۱۰۰ ۔ سخبرہ بن عبیدہ الاسدی\nاز بنی اسد بن خزیمہ۔ ابن اسحاق(1) نے ان کا ذکر کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم کے دو دان کے ان لوگوں میں سے ہیں جنہوں نے بہت پہلے اسلام قبول کیا اور ہجرت کی تھی۔","",{"fn":"(1) السیرۃ النبویۃ (۸۸/۲)"}],[3095,"§۳۱۰۱ ۔ سخرور\nبروزن عصفور یہی ابن مالک الحضری ہیں۔ ابن یونس نے اپنی تاریخ میں ان کا ذکر کرتے ہوئے لکھا ہے: انہیں شرف صحابیت حاصل ہے۔ مصر رہائش رکھتے تھے اور اس کی فتح میں شریک تھے ان کا ایک خطبہ بھی ہے جو انہوں نے وہاں کھڑے ہو کر دیا تھا جس میں نبی صلی اللہ علیہ وسلم کی ایک حدیث کا حوالہ دیا ہے۔ ابو عمر الکندی نے وہ خطبہ بطریق ولید بن سلیمان نقل کیا ہے کہ انہوں نے عائد بن جابر بن ربیعہ الحضرمی کو فرماتے سنا کہ جب مروان مصر کی طرف روانہ ہوا تو تمام اہل مصر اس کی ممانعت کے لیے اکٹھے ہو گئے۔ صرف ان کے معزز لوگوں کی ایک جماعت اس سے باز رہی۔ ہر جماعت میں ان کا خطیب کھڑے ہو کر انہیں ابن زبیر رضی اللہ عنہ کی پیروی کی ترغیب دینے لگا۔ سخرور بن مالک الحضرمی جنہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا تھا اور آپ سے بیعت کی تھی۔ حضرموت میں کھڑے ہو کر خطاب کرنے لگے۔ فرمایا: جس نے اطاعت سے ہاتھ کھینچا تو وہ اسلام سے نکل گیا۔ پھر اس خطبہ کا ذکر کیا۔ فرماتے ہیں: جب اہل مصر نے مروان سے مصر میں داخل ہونے پر صلح کر لی اور وہ اس میں آگیا تو سخرور نے یہ دعا کی: ”اے اللہ! نہ میں اسے دیکھوں اور نہ وہ مجھے دیکھے، میری عمر کافی ہو گئی ہے مجھے اپنی طرف لے لے“۔ چنانچہ مروان کے مصر میں داخل ہونے کے بعد نو راتوں کے اندر اندر فوت ہو گئے۔"],[3096,"§۳۱۰۲ ۔ سراج بن قرۃ(1)\nبن ربیع ابن زرعہ بن لکاع بن عمرو بن عوف بن ابی ربیعہ بن الصموت بن عبد اللہ بن کلاب مشہور جاہلی شاعر ہیں۔ ادھر ابوالحسین بن سراج اندلسی جو عیاض کے شیخ ہیں ان کا گمان ہے یہ ان کے دادا ہیں اور نبی صلی اللہ علیہ وسلم کے پاس آئے۔ وہ کہتے ہیں: یہ ابن قرۃ ہیں جبکہ شاعر کے بارے میں مشہور ہے وہ ابن قوۃ ہے۔ عیاض لکھتے ہیں: میں نے کسی کو نہیں دیکھا کہ اس نے ہمارے شیخ کی متابعت کی ہو کہ سراج کو بارگاہ نبوی میں آنے کی سعادت حاصل ہے۔ اندلس کے مؤرخ ابومروان بن جناح کا بیان ہے: عبد الملک بن مروان بن سراج، عبد الرحمن بن معاویہ الداخل کے مولا ہیں۔ قاضی سراج بن عبد الملک ان کی ولایت کی صراحت کرتے اور اپنے جدا کبر سراج کی آزادی کے تحریر نامہ پر فخر کرتے تھے۔ ابوالولید بن طریف الکاتب نے ”اخبار عبد الملک بن سراج“ میں لکھا ہے کہ ان کے آباء و اجداد و قید ہو گئے۔ اس لیے انہیں موالی بنی امیہ میں شامل کر دیا۔ عیاض فرماتے ہیں: ہمارے شیخ کا دعویٰ تسلیم شدہ ہے کیونکہ انہیں علم حدیث، امامت اور معتبر ہونے میں سبقت و پیش قدمی حاصل ہے۔ میں کہتا ہوں: مجمع الاشعار میں مرزبان کا بیان ہے، سراج بن قرۃ العامری جو بنی الصموت بن عبد اللہ بن کلاب کے ایک فرد ہیں۔ جاہلی دور کے ہیں اور ایام جاہلیت کے دن کا ان کا ایک شعر نقل کیا۔","",{"fn":"(1) اسد الغابہ (۱۹۴۶) تجرید (۲۰۹/۱)"}],[3097,"§۳۱۰۳ ۔ سراج بن مجاعہ\nبن مرارہ بن سکی الیمامی اکنھی۔ ان کے والد صحابی ہیں۔ رہے یہ تو ان کے متعلق ابن حبان(1) پہلے لکھتے ہیں کہ صحابی ہیں پھر انہیں تابعین میں ذکر کر دیا۔ اسی طرح امام بخاری(2) اور ابو حاتم(3) نے بھی تابعین میں ان کا ذکر کیا ہے جبکہ باوردی ابن اسکن ابن قانع اور باقی سب نے صحابہ میں ان کا ذکر کیا ہے اور کبھی ہے بطریق عقبہ بن عبد الواحد قرشی یہ روایت نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے سجاہ کو یمامہ میں زمین عطا کی۔ (حدیث)(4) ابوداؤد بطریق ہلال بن سراج وہ اپنے والد سراج سے وہ بحوالہ اپنے والد سجاہ سے ایک حدیث نقل کرتے ہیں۔","",{"fn":"(1) الثقات (۲۴۶/۴)\n(2) التاریخ الکبیر (۲۰۵/۲)\n(3) الجرح والتعدیل (۳۱۶/۴)\n(4) جامع المسانید (۶۷/۴)"}],[3098,"§۳۱۰۴ ۔ سراج التمیمی(1)(3)\nتمیم الداری کے غلام۔ کنیت ابوالجاد تھی۔ ابن مندہ اور خطیب نے ”الموتلف“ میں ان کا ذکر کیا ہے۔ ابن مندہ کا قول ہے کہ علی بن مجاہد، سراج سے نقل کرتے ہیں: ان کا نام فتح تھا۔ فرمایا: رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے تو ہم پانچ افراد تمیم کے غلام تھے، ہماری تجارت شراب تھی۔ نبی صلی اللہ علیہ وسلم نے مجھے حکم دیا تو میں نے اسے توڑ دیا (شراب کا مٹکا)۔ خطیب لکھتے ہیں: میں نے انہی کے قلم سے نقل کیا ہے جس میں دو مرتبہ ”عن ابیہ عن جدہ عن ابیہ عن جدہ“ ہے۔ علی بن مجاہد اپنے دادا مجاہد سے وہ اپنے والد سراج خادم بیت المقدس روایت کرتے ہیں جن کا نام فتح تھا۔ ان کے قلم سے ایسا ہی تا سے فتح لکھا ہے، فرمایا: ہم لوگ تمیم الداری کے ساتھ ان کے پانچ غلام تھے۔ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، ہماری تجارت شراب پینے تھی جب شراب کی حرمت نازل ہوئی، آپ نے مجھے اس کا مٹکا توڑنے کا حکم دیا تو میں نے اسے توڑ دیا تو نبی صلی اللہ علیہ وسلم نے تمیم سے فرمایا: ”اپنے غلام میرے ہاتھ میں دو تاکہ میں انہیں آزاد کر دوں“۔ تو تمیم نے عرض کی: اللہ کے رسول! میں نے انہیں آزاد کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم کی مسجد میں کھجور کی شاخ جلا کر روشنی کی جاتی تھی تو ہم لوگ فانوس، تیل اور رسیاں لے کر آئے۔ میں نے مسجد میں چراغ جلائے، نبی صلی اللہ علیہ وسلم نے روشنی دیکھ کر فرمایا: مسجد میں کس نے چراغ جلایا ہے؟ تو تمیم الداری نے فرمایا: میرے اس غلام نے، آپ نے فرمایا: اس کا کیا نام ہے؟ انہوں نے فرمایا: فتح۔ آپ نے فرمایا: نہیں اس کا نام سراج (چراغ) ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے(2) میرا نام سراج رکھا، پھر ان کے آنے اور مٹکا توڑنے کا ذکر کیا۔ میں کہتا ہوں: ابن مندہ وغیرہ فتح حرف فاء میں ان کا ذکر فاء میں کرنا بھول گئے۔ اور نہ ابو موسیٰ نے استدراک میں ان کا ذکر کیا ہے بلکہ وہاں ایک نبی تابع کا ذکر کیا ہے جو ایک صحابی سے روایت کرتے ہیں جن کا نام نین لیا ان کی حدیث مسند احمد میں ہے اور ابو عمر بن ابی علی وغیرہ کی تحریر کی طرح کی اس کی نسبت کی ہے جعفر منتظری نے یہ نام فتاح لکھا ہے۔ یہ فارسی نام ہے۔ ہو سکتا ہے کہ تمیم کے غلام کا یہ نام ہو، لیکن جیسے پہلے گزر چکا ہے کہ خطیب کے قلم سے یہ نام فتح ہی لکھا دیکھا ہے ایسا ہی استیعاب کے ایک نسخہ میں ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۴۷) استیعاب (۱۱۳۶) تجرید (۲۰۹/۱)\n(2) الدر المنثور (۲۱۷/۲)\n(3) تفسیر القرطبی (۷۵۷/۱۲)"}],[3099,"§۳۱۰۵ ۔ سرّار بن ربیع\nابن اسحاق نے اور ابن الامین نے ”ذیل علی الاستعیاب“ میں محمد بن اسمعیل الصائغ کی حدیث سے ان کا ذکر کیا ہے، لہذا اسے لکھ لیا جائے۔"],[3100,"§۳۱۰۶ ۔ سراقہ بن جعشم(1)\nوہی ابن مالک ہیں تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۴۸) استیعاب (۹۱۶)"}],[3101,"§۳۱۰۷ ۔ سراقہ بن حارث(1)\nصحابی(2) ہیں۔ بقول طبری ان کی ایک روایت ہے ان کا نسب معلوم نہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۴۹) استیعاب (۹۱۷)\n(2) اسد الغابہ (۲۷۹/۲)"}],[3102,"§۳۱۰۸ ۔ سراقہ بن الحارث\nبعد والے میں ان کا ذکر ہوگا۔"],[3103,"§۳۱۰۹ ۔ سراقہ بن الحباب\nبن عدی الانصاری ثم الجعلی موسیٰ بن عقبہ نے شہداء میں ایسا ہی ابن اسحاق(1) نے ان کا ذکر کیا ہے لیکن ان کے والد کا نام حارث بتایا ہے۔ اسی طرح ابن ہشام کی ”تہذیب السیرۃ“ میں ہے۔ لیکن یونس بن بکیر نے بحوالہ ابن اسحاق مغازئ میں ان کے والد کا نام حباب درست نقل کیا ہے۔ ادھر ابن عبد البر(2) کو وہم ہو گیا انہوں نے سراقہ بن حارث اور سراقہ بن حباب میں فرق کیا ہے۔ یہ بات ابن الاثیر نے نقل کی ہے۔ فرماتے ہیں: درست بات یہ ہے کہ دونوں ایک ہیں اسی طرح ابن فتحون نے اس سے آگاہ کیا ہے۔","",{"fn":"(1) السیرۃ النبویۃ (۷۹/۴)\n(2) استیعاب (۱۴۷/۲)"}],[3104,"§۳۱۱۰ ۔ سراقہ بن سراقہ(1)\nابن مندہ کی بطریق یعقوب بن عقبہ عبد الواحد بن عوف سے بحوالہ سراقہ بن سراقہ روایت ہے کہ سنان بن سلمہ نے خیبر کے روز تلوار سے اپنے آپ کو قتل کر دیا تو رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے کوئی دیت مقرر نہیں فرمائی۔(2)","",{"fn":"(1) اسد الغابہ (۱۹۵۰)\n(2) جامع المسانید (۲۹/۴) اسد الغابہ (۲۷۹/۲)"}],[3105,"§۳۱۱۱ ۔ سراقہ بن عمرو بن زید(1)\nبن عبد مناۃ بن عامر بن عدی بن کعب بن الخزرج بن الحارث بن الخزرج انصاری۔ عدوی کا بیان ہے غزوہ احد اور بعد کے معرکوں میں شریک رہے اور جنگ قادسیہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۹۵۱) استیعاب (۹۱۸)"}],[3106,"§۳۱۱۲ ۔ سراقہ بن عمرو بن عطیہ(1)\nبن خضام بن مبدول بن عمرو بن غنم بن مالک بن النجار انصاری خزرجی۔ ابو حاتم کا قول ہے: بدری صحابی ہیں لیکن ان کی کوئی روایت نہیں۔ ابن سعد لکھتے ہیں: ان کی والدہ قیلہ بنت قیس بن زعوراء، بن حرام بن نجاری ہیں۔ بدر، احد اور خندق وغیرہ جنگوں میں شریک ہوئے اور غزوہ موتہ میں شہادت پائی۔ ابن اسحاق(2) اور واقدی کا قول ہے: بدر میں شرکت کی اور غزوہ موتہ میں شہید ہوئے۔ ایسا ہی ابوالاسود نے بحوالہ عروہ نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۵۲) استیعاب (۹۱۹)\n(2) السیرۃ النبویۃ (۲۵/۴)"}],[3107,"§۳۱۱۳ ۔ سراقہ بن عمرو(1)\nان کا لقب ذوالنور تھا۔ بقول ابو عمر(2): مؤرخین نے صحابہ میں ان کا ذکر کیا ہے، نسب کسی نے نہیں بیان کیا۔ فتوحات میں امیر مقرر تھے اور پہلے بار بار بیان ہو چکا ہے کہ صحابی امیر بنائے جاتے تھے۔ سیف نے ”الفتوح“ میں لکھا ہے کہ سیدنا عمر رضی اللہ عنہ نے سراقہ بن عمرو کو دروازے کی طرف واپس کر دیا اور سرخیل لشکر پر عبد الرحمن بن ربیعہ باہلی کو مقرر کر دیا۔ سراقہ ہی نے ارمینیا کے باشندوں سے صلح کی تھی اور وہیں ان کی وفات ہوئی۔ سیدنا عبد الرحمن کو اپنا نائب بنایا تھا بعد میں سیدنا عمر رضی اللہ عنہ نے انہیں اسی عہدہ پر برقرار رکھا سراقہ عبد الرحمن ذوالنور بھی کہلاتے تھے۔","",{"fn":"(1) اسد الغابہ (۱۹۵۳)\n(2) استیعاب (۱۴۷/۲)"}],[3108,"§۳۱۱۴ ۔ سراقہ بن عمیر(1)\nرونے والوں میں سے ایک۔ طبرانی نے بطریق عبد الغنی بن سعید جو ایک ضعیف راوی ہے۔ اپنی تفسیر میں بطریق عطاء اور ضحاک بحوالہ ابن عباس رضی اللہ عنہما اللہ تعالیٰ کے اس ارشاد ”اور نہ ان لوگوں پر کوئی حرج ہے جو آپ کے پاس آئے تاکہ آپ انہیں سواری عطا کریں“۔(2) ان میں سے سراقہ بن عمیر(3) بھی تھے۔ یہی قصہ سالم بن عمیر کے حوالہ سے گزر چکا ہے لہذا احتمال ہے کہ دونوں بھائی ہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۵۳)\n(2) سورۃ التوبۃ (۹۲)\n(3) اسد الغابہ (۲۸۰/۲)"}],[3109,"§۳۱۱۵ ۔ سراقہ بن کعب(1)\nبن عمرو بن عبدالعزیز بن غزیہ۔ بقول بعض: عروہ بن عمرو بن عبدالعوف بن غنم بن مالک بن نجار۔ ابن اسحاق اور ابو معشر وغیرہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ابن کلبی کا قول ہے: جنگ یمامہ میں شہید ہوئے۔ البتہ ابو عمر(2) لکھتے ہیں: خلافت معاویہ تک حیات رہے۔","",{"fn":"(1) اسد الغابہ (۱۹۵۴) استیعاب (۹۲۰)\n(2) اسد الغابہ (۱۴۸/۲)"}],[3110,"§۳۱۱۶ ۔ سراقہ بن مالک(1)\nبن جعشم بن مالک بن عمرو بن تیم بن مدلح بن مرہ بن عبد مناۃ بن کنانہ الکانی المدلجی۔ اپنے دادا کی نسبت سے بھی پکارے جاتے ہیں۔ ابوسفیان کنیت تھی۔ قدید فروکش ہوئے تھے۔ امام بخاری رحمہ اللہ(2) نے ان کا وہ واقعہ نقل کیا ہے جس میں انہیں نے ہجرت مدینہ کے دوران نبی صلی اللہ علیہ وسلم سے ملاقات کی تھی اور نبی صلی اللہ علیہ وسلم نے انہیں بد دعا دی تھی تو ان کے گھوڑے کے قدم زمین میں دھنس گئے۔ تو انہوں نے خلاصی کی درخواست کی اور یہ وعدہ کیا کہ کسی کو نہیں بتائیں گے۔ چنانچہ آپ نے معاف کر دیا اور انہیں امان لکھ دی۔ فتح مکہ کے موقع پر اسلام لائے۔ اسی قصہ کو بطریق براء بن عازب بحوالہ سیدنا ابو بکر الصدیق رضی اللہ عنہ نقل کیا ہے۔ اپنے اس واقعہ میں سراقہ ابو جہل کو مخاطب کر کے کہتے ہیں: ابو حکم! کاش تم وہ منظر دیکھتے جب میرے گھوڑے کے پاؤں دھنس گئے۔“ تو ہمیں معلوم ہو جاتا کہ محمد واضح دلیل کے ساتھ سچے رسول ہیں، تو کون ان کا مقابلہ کر سکتا ہے۔ ابن عیینہ بواسطہ اسرائیل ابی موسیٰ، بحوالہ حسن روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سراقہ بن مالک سے فرمایا: ”اس وقت تمہاری کیا کیفیت ہو گی جب تم کسریٰ کے کنگن پہنو گے“۔ فرماتے ہیں(3): جب سیدنا عمر رضی اللہ عنہ کے پاس کسریٰ کے کنگن اور ازار بند لائے گئے جن میں تاج بھی تھا تو آپ نے سراقہ کو بلایا اور کنگن انہیں پہنائے۔(5) وہ چہرے اور کانوں پر زیادہ بالوں والے تھے اسی طرح ان کے دونوں بازوؤں پر بھی بہت بال تھے۔ سیدنا عمر رضی اللہ عنہ نے ان سے فرمایا: اپنے ہاتھ بلند کرو اور کہو: ”تمام تعریفیں اللہ کے لیے جس نے کسریٰ بن ہرمز سے چھین کر سراقہ اعرابی کو پہنائے“۔ یہی روایت ان سے ان کا بھتیجا عبد الرحمن بن مالک بن جعشم کا بیٹا روایت کرتا ہے ان سے ابن عباس، جابر، سعید بن المسیب اور طاؤس نے روایت لی ہے۔ ابو عمر لکھتے ہیں:(4) چوتیس (۳۴ھ) میں خلافت عثمانی میں سیدنا عثمان رضی اللہ عنہ کے بعد فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۹۵۵) استیعاب (۹۲۱) تجرید (۳۱۰/۱)\n(2) بخاری کتاب المناقب باب علامات النبوۃ فی الاسلام (۳۶۱۵، ۳۶۵۲)\n(3) اتحاف السادۃ المتقین (۱۸/۷)\n(4) استیعاب (۱۴۸/۲)\n(5) منطقہ سے مراد ہر وہ پٹی ہے جس سے کمر کسی جائے۔"}],[3111,"§۳۱۱۷ ۔ سراقہ بن مالک انصاری\nکعب بن مالک کے بھائی۔(1) حاتم نے ان کا ذکر کیا اور بطریق ابن اسحاق روایت کی ہے کہ سراقہ بن مالک نے رسول اللہ صلی اللہ علیہ وسلم سے ان کے حوض پر آنے والے گشہ اور نفع کے بارے میں پوچھا کیا (اسے پانی پلانے میں) ان کے لیے اجر ہے؟ (حدیث) اس کی سند میں ضعف ہے کیونکہ اس میں ابن ابی حجر ہے۔ میں نے نہیں دیکھا کہ ان سراقہ کا کسی نے صحابہ میں ذکر کیا ہو البتہ سہیل بن مالک کے حالات میں طحاوی کی روایت آتی ہے جو بطریق عبد الرحمن بن کعب بن مالک بحوالہ ان کے چچا منقول ہے۔ جس میں ان کا نام نہیں لیا ہے لہذا احتمال ہے کہ وہ یہ ہوں۔","",{"fn":"(1) المستدرک (۶۱۹/۲)"}],[3112,"§۳۱۱۸ ۔ سراقہ بن مرداس السلمی\nعباس کے بھائی۔ میں نے کسی کو نہیں دیکھا کہ اس نے صحابہ میں ان کا ذکر کیا ہو، البتہ ابو الفرج اصبہانی کی نقل کردہ ایک روایت ملی ہے جس سے ان کا صحابی ہونا معلوم ہوتا ہے کہ عباس بن مرداس کی کنیت ابو الہیثم تھی جس کے متعلق ان کے بھائی سراقہ کا شعر ہے کہتے ہیں: ”اے! آکھ! کیا میں ابو الہیثم پر آنسو نہ بہاؤں۔ دیکھا تھا نہیں بلکہ لگا تار آنسو بہا! دلیل یہ ہے کہ وہ اتنا عرصہ زندہ رہے کہ ان کا بھائی عباس فوت ہوا، باوجود یکہ ان کے والد کا انتقال اسلام سے پہلے ہوا۔ جس سے معلوم ہوتا ہے انہوں نے دور نبوت پایا ہے۔ فتح مکہ کے روز عباس بنی سلیم کی ہزاروں کی نفری میں تھے تو ان کے بھائی یقیناً نبی میں ہوں گے۔ عباس کا انتقال خلافت فاروقی یا عثمانی میں ہوا، ان حالات میں آتا ہے کہ وہ مصر فروکش ہوئے اور جنگل میں مقیم رہے۔ ایک قول ہے کہ دمشق آئے اور وہاں اپنی حویلی بنائی۔"],[3113,"§۳۱۱۹ ۔ سراقہ بن المعتمر(1)\nبن انس ابن اذاۃ بن ریاح بن عبد اللہ بن قرظ بن طاہر بن زراج بن عدی بن کعب قرشی عدوی سیدنا عمر رضی اللہ عنہ کے خاندان سے ہیں۔ ابن کلبی کا گمان ہے: بدر میں شریک ہوئے جس میں کسی نے ان کی متابعت نہیں کی، البتہ اگر شرکت سے ان کی مراد کفر کی حالت میں شرکت تھی تو وجہ ہے۔ بعد میں اسلام لے آئے۔ یہی عمرو بن سراقہ کے والد ہیں۔ پھر مجھے بحوالہ ابو سعید ابن کلبی جیسی روایت مل گئی جبکہ وہ بھی انبی کا چہرہ (یہ چھپے چلنے والا) ہے۔ ابتدا میں سراقہ مسلمانوں کے بڑے مخالف تھے اس وقت نبی صلی اللہ علیہ وسلم نے فرمایا: سب سے سخت عذاب پر ظالم، ڈھینک مارنے والے، بک بک کرنے والے اور بازاروں میں سراقہ بن معتمر کی طرح شور مچانے والے کو ہوگا۔“ اسے بلاذری نے نقل کیا ہے۔ ابن الاثیر کی کتاب میں ان کے نسب سے انس نام رہ گیا ہے، جبکہ ”ابن الامین“ نے انس تک پہنچایا ہے اور ذکر کیا ہے کہ وہ بدر میں شریک ہوئے۔ جس کی وضاحت ان کے والد عمرو بن سراقہ کے حالات میں ہوگی۔","",{"fn":"(1) اسد الغابہ (۱۹۵۶)"}],[3114,"§۳۱۲۰ ۔ سرحان\nمولا ابو الراشد، عبد الرحمن بن عبید اللہ زری۔ ان کا ذکر ان کے مولا عبد الرحمن کے سوانح میں ایک حدیث میں ہوگا جسے الدولابی نے الکنیٰ میں نقل کیا ہے۔"],[3115,"§۳۱۲۱ ۔ سرغ\nیحییٰ بن مندہ نے ان کا ذکر بحوالہ عبد اللہ بن اشکاب کیا ہے کہ انہوں نے ”الافراد“ میں ان کا ذکر کیا ہے۔"],[3116,"§۳۱۲۲ ۔ سُرقوخہ (بے نسبت)\nان کے نام کو قلمبند کرنے کا مجھے موقع نہیں ملا۔ ان کی حدیث جامع ابن عیینہ میں ان کی روایت سے بواسطہ عبید اللہ بن ابی یزید بحوالہ عبد بن عمیر مروی ہے۔ آپ صلی اللہ علیہ وسلم کے پاس شرخونہ نامی شخص قتل کیے جانے کے لیے لایا گیا، آپ نے پوچھا: ”کیا یہ نماز پڑھتا ہے؟“ لوگوں نے بتایا: جب لوگ اسے دیکھتے ہیں، آپ نے فرمایا: مجھے نمازیوں کے قتل سے منع کیا گیا ہے۔"],[3117,"§۳۱۲۳ ۔ سُرق(1)\nعسکری نے یہ نام بغیر تشدید کے قلمبند کیا ہے جو عذر اور عمر کے وزن پر ہے۔ اور محمد شین پر را کو مشدد پر را کو مشدد پر را کو مشدد پر را کو مشدد لکھنے پر فکیر ہیں۔ بقول بعض: ان کے والد کا نام اسد ہے۔ صحابی ہیں، مصر فروکش ہوئے۔ بقول بعض: ان کا نام حجاب تھا، جسے نبی صلی اللہ علیہ وسلم نے تبدیل کر دیا تھا۔ نہما جہنی بقول بعض: وہ کبھی ایک قول کے مطابق انصاری ہیں۔ ابن یونس اور ازدی لکھتے ہیں: انہیں شرف صحابیت حاصل ہے۔ فتح مصر میں شریک تھے اور انہیں وہاں خطہ ارضی بھی ملا۔ ابن مندہ کی روایت ہے کہ زید بن اسلم نے فرمایا: میں نے اسکندریہ میں ایک بزرگ شخص دیکھا ”سرق“ کہا جاتا تھا، میں نے کہا: یہ بھی کوئی نام ہے؟ انہوں نے بتایا: میرا نام رسول اللہ صلی اللہ علیہ وسلم نے رکھا ہے۔ اسی طرح ابو موسیٰ اور حسن بن سفیان بطریق مسلم بن خالد بحوالہ عبد الرحمن بن سلیمانی (سلیمانی) روایت کرتے ہیں، فرمایا: میں مصر میں تھا مجھ سے ایک شخص کہنے لگا: کیا تمہیں ایک صحابی کا پتہ نہ بتاؤں؟ میں نے کہا: کیوں نہیں، ضرور! پھر مجھے حدیث ذکر کی، جس میں ان کے اس نام کی وجہ بیان ہوئی ہے۔ کتبوں میں عبادہ کے ذیل میں بیان ہوگا کہ عبد الرحمن التفتنی نے مذکورہ سرق کا واقعہ بیان کیا ہے، ان کا انتقال خلافت عثمانی میں ہوا۔ ابن ماجہ نے ان کی ایک حدیث لی ہے جو ایک مصری کے طریق سے بحوالہ ان کے قسم اور گواہ کے بارے میں ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۵۹) استیعاب (۱۱۳۷) تجرید (۲۱۰/۱)"}],[3118,"§۳۱۲۴ ۔ سرق (دوسرے)(1)\nایمان لانے والے جنوں میں سے ہیں۔ ”دلائل“(2) میں بیہقی کی روایت ہے کہ ابو عمر انصاری کا قول ہے: ایک دفعہ عمر بن عبد العزیز ایک بیان میں جا رہے تھے، آپ کا مدد کا ارادہ تھا۔ اچانک انہیں ایک مردہ سانپ نظر آیا، آپ نے فرمایا: کدال لاؤ۔ چنانچہ آپ نے گڑھا کھود کر اسے ایک کپڑے میں لپیٹ کر دفن کر دیا۔ ایک نیک آواز آئی: سرق تم پر اللہ کی رحمت ہو، میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”سرق! تم ایک بیان میں موت سے دو چار ہو گے اور تمہیں میری امت کا بہترین شخص دفن کرے گا“۔ حضرت عمر بن عبد العزیز نے فرمایا: ”تم کون ہو؟“ اس نے کہا: میں جن ہوں اور سیرق ہے۔ نبی صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں سے میرے اور اس کے علاوہ کوئی نہ بچا تھا۔ ہم نے عباس ترقفی (برقفی) کی حدیث میں اسی سے ملتا جلتا واقعہ نقل کیا ہے۔ خواتین کے حصہ میں حرف خاء میں ان شاء اللہ تعالیٰ ان کا تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۶۱) تجرید (۲۱۱/۱)\n(2) دلائل النبوۃ (۴۹۴/۶)"}],[3119,"§۳۱۲۵ ۔ سریع بن الحکم السعدی(1)\nاز بنی تمیم۔ بقول ابن اسکن: بصرہ میں شمار ہوتے ہیں۔ یعقوب بن سفیان نے اپنی تاریخ میں سہل بن وقاص بن سرح سے بحوالہ سریع بن حکم روایت کی ہے کہ میں بنی تمیم کے وفد میں روانہ ہوا، یہاں تک کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس جا پہنچے۔ ہم نے آپ کی خدمت میں اپنے اموال کی زکوٰۃ پیش کیں۔(2) پھر مجھے حدیث ذکر کی۔ ابن مندہ فرماتے ہیں: یہ حدیث غریب ہے، جس میں سہل منفرد ہے۔ اسی کو باوردی اور ابن اسکن نے بطریق سہل بن وقاص بن سرح روایت کیا ہے۔ باوردی کا بیان ہے کہ خالد بن ولید جب یمامہ سے کابل کرنے جانے لگے تو انہوں نے رہنمائی کی اس بارے میں ان کی اچھی خدمات ہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۶۲) استیعاب (۹۲۲) تجرید (۲۱۱/۱)\n(2) جامع المسانید (۸۲/۵)"}],[3120,"§۳۱۲۶ ۔ سعد بن الاخرم الطائی\nعبد اللہ بن احمد ”زیادات مسند“ میں ابن ابی عمر اور ابن ابی شیبہ بطریق اعمش بواسطہ عمرو بن مرہ، مغیرہ بن سعد الاحرم وہ اپنے والد یا چچا کے حوالہ سے روایت کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس عرفہ میں آیا، آپ کی اونٹنی کی مہار پکڑ لی، لوگوں نے مجھے ہٹانا چاہا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے چھوڑ دو“۔ پھر وہ حدیث ذکر کی جس میں انہوں نے آپ علیہ السلام سے پوچھا تھا کہ جہنم سے دور کرنے والے کیا امور ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ کی عبادت کرتے رہو اور کسی کو اس کے ساتھ شریک نہ کرو“۔(1) (حدیث) حسن بن سفیان نے یہ حدیث اسی سند سے نقل کی اور اس میں والد یا چچا کے بارے میں اعمش کے شک کا اضافہ نقل کیا ہے۔ بغوی کا قول ہے: اس کو اعمش سے نقل کرنے میں یحییٰ بن عیسیٰ منفرد ہے۔ عبد اللہ بن احمد کی روایت میں عیسیٰ بن یونس نے بحوالہ اعمش ان کی متابعت کی ہے۔ میں کہتا ہوں: سعد کی ابن مسعود سے ترمذی وغیرہ میں ایک روایت ہے۔ امام بخاری(2) اور ابو حاتم(3) نے انہیں تابعین میں شمار کیا ہے۔ ان کے چچا کا نام ”عبد اللہ“ ہے۔ ابو احمد العسکری کا قول ہے: امام بخاری فرماتے ہیں: یہ حدیث تو مغیرہ بن عبد اللہ یشکری سے منقول ہے اور عثمان بن ابی شیبہ بواسطہ جریر بحوالہ اعمش نقل کیا ہے جس میں ہے: مغیرہ بن عبد اللہ الشکری بحوالہ اپنے والد نقل کرتے ہیں۔ واللہ اعلم بالصواب۔","",{"fn":"(1) مسند احمد (۴۷۷/۳) جامع المسانید (۸۴/۵) اسد الغابہ (۲۸۳/۲)\n(2) التاریخ الکبیر (۵۴/۲)\n(3) الجرح والتعدیل (۸۰/۴)"}],[3121,"§۳۱۲۷ ۔ سعد بن اسحاق(1)\nمجھے معلوم نہیں یہ کون ہیں؟ صرف ابن حزم نے ان کا ذکر کیا ہے کہ مسند بقی بن مخلد میں ان کی دو حدیثیں ہیں۔ ذہبی نے تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے۔ میرے خیال میں یہ ”سعد بن اسحاق بن کعب بن عجرہ“ ہیں۔ اگر یہ وہی ہیں تو پھر نبی صلی اللہ علیہ وسلم کے حوالہ سے ان کی حدیث مرسل ہے یا معضل۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۱۹۶۳)"}],[3122,"§۳۱۲۸ ۔ سعد بن اسعد(1)\nبن خالد انصاری۔ سہل بن سعد بن سعد کے والد۔ یہی سعد بن مالک ہیں، تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۶۶) استیعاب (۹۲۳)"}],[3123,"§۳۱۲۹ ۔ سعد بن الاطول (دراز قد)\nبن عبد اللہ بن خالد بن واہب بن غیاث بن عبد اللہ بن سعید بن عدی بن عوف بن عطفان بن قیس بن جہینہ النجھنی۔ ظلیفہ بن خیاط نے ان کا نسب بیان کیا ہے۔ ان کی کنیت ابو طفر ہے، ابن ماجہ میں ان کی ایک حدیث ہے ان کے بھائی یار بن الاطول کے حالات میں ان کا تذکرہ ہونا ہے۔ تاریخ بخاری اور مجمع بغوی میں نبی صلی اللہ علیہ وسلم سے ان کے ساتھ کی صراحت موجود ہے۔"],[3124,"§۳۱۳۰ ۔ سعد بن ایاس(1)\nالبدری الانصاری۔ ابو موسیٰ کی بطریق الاحوص بن یوسف بحوالہ سعد بن ایاس انصاری بدری روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سیدنا عباس رضی اللہ عنہ سے فرماتے سنا: ”بچا جان! اکل جب ہو تو آپ اور آپ کے بیٹے اپنے گھر میں نہ ٹھہریں“۔ (حدیث) اس کی سند ضعیف ہے۔ ابن ماجہ(2) میں اس کا دوسرا طریق بھی ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۶۸) تجرید (۲۱۱/۱)\n(2) ابن ماجہ کتاب الادب باب الرجل یقال لہ کیف اصبحت (۳۷۱۱)"}],[3125,"§۳۱۳۱ ۔ سعد بن بجیر(1)\nبن معاویہ بن ثعلبہ بن حارث بن ثعلبہ بن سدوس الکبلی۔ انصار کے حلیف۔ یہی سعد بن خدیجہ ہیں جو ان کی والدہ کا نام ہے۔ اسی سے ان کی شہرت ہوئی۔ ابن سعد(2) لکھتے ہیں: یہ قاضی ابو یوسف کے دادا ہیں۔ بغوی کا قول ہے۔ ابو یوسف بحوالہ ایوب بن نعمان روایت کرتے ہیں کہ میں سعد بن حبہ کے جنازہ میں شریک تھا۔ زید بن ارقم نے ان کے جنازہ میں پانچ تکبیریں کہیں۔ ابن کلبی حدیث ابی قتادہ سے روایت کرتے ہیں، فرمایا: احد کے روز میں رسول اللہ صلی اللہ علیہ وسلم کی تلاش میں نکلا تو مجھے سعد وہاں مل گیا میں نے اسے ایک ضرب لگائی اتنے میں سعد ابن حبہ آگئے، انہوں نے بھی اسے ضرب لگائی تو وہ بے ہوش ہو کر گر گیا۔","",{"fn":"(1) اسد الغابہ (۱۹۷۰)\n(2) الطبقات (۲۴/۶)"}],[3126,"§۳۱۳۲ ۔ سعد بن تمیم السکونی(1)\nیحییٰ بن معین، امام بخاری اور ابو حاتم(2) کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ بغوی لکھتے ہیں: دمشق رہائش پذیر تھے۔ ابو زرعہ مشقی بطریق عثمان بن مسلم روایت کرتے ہیں کہ انہوں نے بلال بن سعد سے سامع کیا ہے اور انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے۔ بقول بعض: آپ نے ان کے سر پر ہاتھ پھیرا اور ان کے لیے دعا کی تھی۔ ابو زرعہ لکھتے ہیں: وہ سعد بن تمیم ہیں۔ انہیں القاری بھی کہا جاتا ہے۔ السکون کے رہنے والے تھے۔ ”جماعت کے روز“ دمشق میں تھے۔ شام میں ان سے مروی دو حدیثیں ہیں جن کی سند حسن ہے۔ ابراہیم بن جنید کا قول ہے: کسی نے ابن معین سے پوچھا: کیا بلال بن سعد کے والد صحابی ہیں؟ انہوں نے فرمایا: ہاں۔ ابن عساکر فرماتے ہیں: صحابی ہیں۔ اور حاکم کا قول ہے: ان سے ان کے بیٹے کے علاوہ کسی نے روایت نہیں کی۔ ابن ابی خثیمہ بطریق ابن ابی جید روایت کرتے ہیں کہ سعد بن بلال کے والد رمضان میں تین راتوں تک پڑھتے، جب رات کی آخری گھڑی ہوتی تو وہ آتے بلکہ اپنے گھر میں قیام فرماتے۔ بلال بن سعد بحوالہ اپنے والد ایک حدیث ہے جسے ابن جوصا نے بطریق عبد اللہ بن العلاء بن زید نقل کیا ہے کہ میں نے بلال بن سعد بحوالہ اپنے والد روایت کرتے سنا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی: آپ کے بعد خلیفہ کے لیے کتنی فرمانبرداری ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جب تک وہ فیصلہ میں انصاف کرتا رہے اس کی اتنی ہی فرمانبرداری ہے جتنی میری ہے“۔(3) (حدیث) ابن ابی داود بطریق ابن جابر بحوالہ بلال بن سعد روایت کرتے ہیں کہ جب ان کے والد کی وفات کا وقت ہوا تو فرمانے لگے: بیٹا! تمہارے یہ بیٹے کہاں ہیں؟ تو میں نے اپنے گھر والوں کو کہہ دیا کہ انہیں سفیر قیصیں پہناؤ پھر انہیں ان کے پاس لے آیا۔ آپ نے فرمایا: ”اللہ! میں انہیں کفر، عمل کی گمراہی، غلامی اور لوگوں کی محتاجی سے آپ کی پناہ میں دیتا ہوں“۔ ابن المبارک نے کتاب الزہد میں اسی طرح روایت کی ہے۔ طبرانی(4) نے دوسری سند سے جو ابن جابر تک ہے جسے انہوں نے مرفوعاً نقل کیا ہے کہ بلال بن سعد سے بحوالہ ان کے والد مروی ہے کہ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: تمہارے بیٹے کہاں ہیں؟ عرض کی: یہ ہیں میں نے فرمایا: ”انہیں میرے پاس لے آؤ“۔ پھر اس کا ذکر کیا، لگا کہ اس کا مرفوع ہونا وہم پر مبنی ہے۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۱۹۷۲) استیعاب (۹۲۵) تجرید (۲۱۲/۱)\n(2) الجرح والتعدیل (۸۱/۴)\n(3) جامع المسانید (۸۹/۵)\n(4) المعجم الکبیر (۳۴۶۱)"}],[3127,"§۳۱۳۳ ۔ سعد بن جنادہ العوفی(1)\nعطیہ عوفی کے والد۔ ابن اسکن اور باوردی نے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ کی بطریق یونس بن نفیع انجوی بحوالہ سعد بن جنادہ روایت ہے کہ اہل طائف میں سے سب سے پہلے میں نبی صلی اللہ علیہ وسلم کے پاس آیا اور اسلام قبول کیا۔(2) (حدیث) ابو نعیم کی روایت ہے کہ یونس بحوالہ سعد بن جنادہ وہ دس احادیث نقل کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۷۴) تجرید (۲۱۲/۱)\n(2) المعجم الکبیر (۵۴۸۲/۶) اسد الغابہ (۲۸۸/۲)"}],[3128,"§۳۱۳۴ ۔ سعد بن جاریہ\nبقول بعض: حارث بن لوزان بن عبد ودد بن زید بن ثعلبہ بن خرزج انصاری ساعدی بقول ابن اسحاق: جنگ یمامہ میں شہید ہوئے، انہوں نے بنی سالم بن عوف سے شمار کیا ہے۔"],[3129,"§۳۱۳۵ ۔ سعد بن حبتہ\nوہی ابن بجیر، پہلے تذکرہ ہو چکا ہے۔"],[3130,"§۳۱۳۶ ۔ سعد بن ابی جندب\nبن زید بن ابی کبیر، حکم بن عمرو کے مولا۔ بقول طبری: انہیں شرف صحابیت حاصل ہے۔"],[3131,"§۳۱۳۷ ۔ سعد بن حارث(1)\nبن الصمہ انصاری، جہم کے بھائی۔ بقول ابن شاہین: انہیں شرف صحابیت حاصل ہے۔ صفین میں سیدنا علی رضی اللہ عنہ کا ساتھ دیا۔ طبری لکھتے ہیں: صحابی رسول صلی اللہ علیہ وسلم ہیں۔ صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ تھے اور اسی روز شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۹۷۶) استیعاب (۹۲۶)"}],[3132,"§۳۱۳۸ ۔ سعد بن حبان(1)\nبن مقد بن عمرو المازنی، ان کی والدہ ہند بنت ربیعہ بن حارث بن عبد المطلب ہیں۔ بقول عدوی: بیعت رضوان میں شریک تھے اور فتح مکہ میں شہادت پائی۔","",{"fn":"(1) اسد الغابہ (۱۹۷۹)"}],[3133,"§۳۱۳۹ ۔ سعد بن حبتہ\nطبرانی(1) نے بطریق واحدی، ایوب بن نعمان کی بواسطہ ان کے والد بحوالہ ان کے دادا روایت نقل کی ہے کہ میں نے احد میں نبی صلی اللہ علیہ وسلم کے بدن پر دو زخم دیکھے (جو بھر پور جنگی تیاری اور بہادری کی علامت ہے)۔ ابن حبان(2) نے ایک روایت نقل کی ہے جس سے پتہ چلتا ہے کہ نعمان کے والد کا نام سعد بن حبتہ ہے۔ چنانچہ ثقات التابعین میں قطراز ہیں: نعمان بن سعد ابن حدیث۔ سیدنا علی، زید بن ارقم سے روایت کرتے اور ان سے ان کا بیٹا نعمان بن سعد ان سے کا بیٹا۔ ایسا ہی ابن ابی حاتم(3) نے لکھا ہے۔ اسی طرح نعمان کو عبداللہ بن کعب بن مالک انصاری سے بھی روایت حاصل ہے۔","",{"fn":"(1) المعجم الکبیر (۹۳۸)\n(2) الثقات (۴۷۲/۵)\n(3) الجرح والتعدیل (۴۴۶/۸)"}],[3134,"§۳۱۴۰ ۔ سعد بن جمّاز(1)\nبن مالک انصاری، ثم البلوی۔ حلیف بنی ساعدہ۔ والد کے نام میں اختلاف ہے۔ بقول بعض: حمار جو ایک جانور کا نام ہے ایک قول ہے: حتمان۔ یہ الامیر کا قول ہے، پہلے قول پر طبری نے اعتماد کیا ہے ابن لہیعہ بحوالہ ابوالاسود عروہ سے روایت کرتے ہیں، یہ سعد بن حبان ہیں یعنی میم کے بجائے باء ہے۔ واللہ اعلم۔ موسیٰ بن عقبہ نے شہداء یمامہ میں ان کا ذکر کیا ہے۔ ابن شاہین لکھتے ہیں: احد اور بعد کے معرکوں میں شریک رہے۔","",{"fn":"(1) اسد الغابہ (۱۹۷۲) استیعاب (۹۲۹)"}],[3135,"§۳۱۴۱ ۔ سعد بن حرّہ(1)\nعسکری نے صحابہ میں ان کا تذکرہ کیا ہے اور ابو موسیٰ نے بطریق علی بن سعید العسکری پھر بطریق سعید بن ابی ایوب، ابن عجلان سے، سعید المقبری سے بحوالہ سعد بن حرہ روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی وضو کر کے مسجد کے ارادہ سے نکلتا ہے تو وہ ہرگز دونوں ہاتھوں کی انگلیوں کو آپس میں نہ ملائے کیونکہ وہ نماز میں ہے۔“(2) میں کہتا ہوں: اس اسناد کے راوی ثقات ہیں۔ لیکن مجھے اس میں لفظی غلطی معلوم ہوتی ہے اور کچھ چھوٹ گیا ہے۔ یہ متن ابن ماجہ اور دارمی نے دو طریقوں سے بواسطہ مقبری بحوالہ سعد بن حرہ نقل کیا ہے۔ ایسا ہی ایک جماعت نے ابن عجلان سے نقل کیا ہے۔ لیکن ابن جریج فرماتے ہیں: ان سے بواسطہ مقبری، کعب کے کسی بیٹے سے بحوالہ کعب مروی ہے۔ یہی حدیث قطان نے ابن عجلان سے انہوں نے بواسطہ اپنے والد بحوالہ ابو ہریرہ رضی اللہ عنہ روایت کی ہے۔ ابن خزیمہ اسے نقل کرنے کے بعد لکھتے ہیں: اس میں ابن عجلان سے غلط ہو گیا ہے۔ لکھتے ہیں: ”ان سے خالد بن حبان نے روایت کی اور مصیبت لاکھڑی کی کہ ابن عجلان سے بواسطہ سعید بن المسیب بحوالہ ابوسعید مروی ہے“۔ البتہ ابن ابی ذئب کی اسناد عمدہ ہے۔ میرے نزدیک جو شخص بنی سالم سے ہے وہ سعد بن اسحاق بن کعب بن عجرہ ہیں۔ میں کہتا ہوں: میرا غالب گمان یہ ہے کہ عسکری کی روایت میں جو سعد بن مجرہ ہے وہی سعد بن اسحاق ہیں جن کا نسب بعض دفعہ ان کے والد کے دادا کی طرف بیان کر دیا جاتا ہے، پھر اس میں لفظی غلطی ہوگئی۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۱۹۸۰)\n(2) مسند احمد حدیث (۲۴۱/۴) السنن الکبرٰ (۲۳۰/۳) المعجم الکبیر (۳۳۲/۱۹)"}],[3136,"§۳۱۴۲ ۔ سعد بن حنظلہ بن یسار\nحنظلہ کے سوانح میں تذکرہ ہوا ہے۔"],[3137,"§۳۱۴۳ ۔ سعد بن الحنظلیہ\nوہی ابن الربیع ہیں، تذکرہ ہوتا ہے۔"],[3138,"§۳۱۴۴ ۔ سعد بن خارجہ(1)\nبن ابی زہیر، زید کے بھائی۔ یہ اور ان کے والد احد میں شہید ہوئے۔ ابن مندہ کی بطریق داؤد بن ابی ہند بحوالہ نعمان بن بشیر روایت ہے کہ انصار کے سرداروں اور اچھے جوانوں میں سے ایک جوان زید بن خارجہ تھا۔ اس کے والد اور بھائی سعد بن خارجہ احد میں شہید ہوئے تھے، انہوں نے ہی موت کے بعد گفتگو کی تھی۔ پھر وہ واقعہ ذکر کیا۔ ابونعیم نے اسے طویل ذکر کیا ہے۔ اسی میں ہے، انہوں نے فرمایا: عبد اللہ بن خولہ! کیا تم نے خارجہ اور سعد سے اچھا برتاؤ کیا؟ ایسا ہی ہم نے جزء ثانی میں محمد بن نصر بن احمد بن محمد بن مکرم کی حدیث سے نقل کیا ہے اور امالی المحاملی اصبہانیہ کے گیارھویں حصہ میں۔","",{"fn":"(1) اسد الغابہ (۱۹۸۱)"}],[3139,"§۳۱۴۵ ۔ سعد بن خلیفہ(1)\nبن اشرف بن ابی خزیمہ بن ثعلبہ بن ظریف بن خزرج بن ساعدہ ساعدی انصاری۔ ابن شاہین، طبری اور عدوی کا بیان ہے: احد میں شریک ہوئے اور عدوی نے مزید لکھا ہے کہ قادسیہ میں شہادت پائی۔","",{"fn":"(1) اسد الغابہ (۱۹۸۲)"}],[3140,"§۳۱۴۶ ۔ سعد بن خولہ(1)\nقرشی عامری از بنی مالک بن حسل بن عامر بن لوی۔ بقول بعض: ان کے حلیف ہیں ایک قول ہے: ان کے مولا ہیں۔ ابن ہشام کا قول ہے: یمن کے فارسی ہیں، جنہوں نے بنی عامر سے حلف کا عہد کیا۔ موسیٰ بن عقبہ اور ابن اسحاق وغیرہ نے بدر میں ان کا ذکر کیا ہے۔(2) صحیحین میں حدیث سعد بن ابی وقاص سے جب وہ مکہ میں بیمار ہو گئے ان کا ذکر آتا ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا تھا: ”لیکن مصیبت زدہ تو سعد بن خولہ ہے۔“(3) نبی صلی اللہ علیہ وسلم ان کے بارے افسوس کر رہے تھے کہ وہ مکہ میں فوت ہو گئے (اور ہجرت نہ کر سکے)۔ حدیث سبیعہ بنت الحارث میں صحیحین میں ان کا ذکر ہے کہ وہ سعد بن خولہ کے نکاح میں تھیں حجتہ الوداع کے موقع پر وہ فوت ہو گئے تو یہ امید سے تھیں۔ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں۔","",{"fn":"(1) اسد الغابہ (۱۹۸۳) استیعاب (۹۳۲) تجرید (۲۱۳/۱)\n(2) السیرۃ النبویۃ (۲۴۷/۲)\n(3) بخاری کتاب الوصایا باب ان یترک ورثتۃ اغنیاء (۲۷۴۲) مسلم کتاب الوصیۃ باب الوصیۃ بالثلث"}],[3141,"§۳۱۴۷ ۔ سعد بن خولی الکلبی\nمولا حاطب بن ابی بلتعہ۔ بقول ابن حبان: انہیں شرف صحابیت حاصل ہے۔(1) ابن کلبی ان کا نسب یوں بیان کرتے ہیں: سعد بن خولی بن سبرہ بن دریم بن قیس بن مالک بن عمیرہ بن عامر قضائی۔ بنی اسد بن عبد العزیٰ میں شمار ہوتے ہیں۔ کیونکہ حاطب ان کے حلیف ہیں۔ ان کے حلیف ہیں۔ بقول بعض: ان کے والد خولی بن القوسار بن حارث بن مالک بن عمیرہ، مذحج سے تھے۔ سیدنا عمر رضی اللہ عنہ نے انصار میں ان کے بیٹے عبداللہ کے لیے وظیفہ مقرر کیا تھا۔(2) ابوعمر کا لکھتے ہیں: اس میں کسی کا اختلاف نہیں کہ وہ احد میں اپنے مولا کے ساتھ تھے اور وہیں شہید ہوئے۔(3) کلبی اور بلاذری کا قول ہے اور معشر اکیلے کا قول ہے: یہ سعد بن خولہ عامری ہیں جو ان کی غلطی ہے، سعد مولا عتبہ بن غزوان کے سوانح میں ان شاء اللہ تعالیٰ ان کا ذکر ہوگا۔","",{"fn":"(1) الثقات (۱۵۱/۳)\n(2) استیعاب (۱۵۳/۲)\n(3) المعجم الکبیر (۵۵۰۴، ۵۵۰۵)"}],[3142,"§۳۱۴۸ ۔ سعد بن خولی (دوسرے)\nابن مندہ نے ان میں اور سعد بن خولہ، جن کا تذکرہ ہو چکا ہے، فرق کیا ہے۔ ابونعیم لکھتے ہیں: دونوں ایک ہیں۔ ابن عائذ نے مغازی میں حدیث ابن عباس رضی اللہ عنہما سے نقل کیا ہے: حبشہ سیدنا جعفر کے ساتھ دوسری ہجرت کرنے والوں میں سعد بن خولی بھی تھے۔ عبدالغنی بن سعید ثقفی جو ایک ضعیف راوی ہے اپنی تفسیر میں بحوالہ ابن عباس رضی اللہ عنہما روایت کرتے ہیں کہ ان کے متعلق یہ آیت “ان لوگوں کو اپنی مجلس سے نہ نکالنا جو صبح و شام اپنے رب کو پکارتے رہتے ہیں”۔(1) ابن اسحاق مغازی میں ابراہیم بن سعد کی بحوالہ ان شرکاء بدر میں تذکرہ کرتے ہیں: سعد بن خولی از بنی عامر بن لوئی، جو ان کے حلیف ہیں یمن کے رہنے والے تھے۔ میں کہتا ہوں: اس سے ابونعیم کی بات کو تقویت ملتی ہے۔","",{"fn":"(1) سورۃ الانعام آیت ۵۲"}],[3143,"§۳۱۴۹ ۔ سعد بن خیثمہ(1)\nبن حارث بن مالک بن کعب بن شحاط ابن کعب بن حارثہ بن غنم بن السلم بن امرئ القیس بن مالک بن اوس انصاری اوسی۔ ابوخیثمہ کنیت تھی عقبہ میں ایک نقیب یہ بھی تھے۔ ابن اسحاق(2) وغیرہ نے ان کا ذکر کیا اور اپنی مسند سے بحوالہ کعب بن مالک روایت کی ہے کہ: جب عقبہ کی رات تو رسول اللہ صلی اللہ علیہ وسلم نے منی میں بیعت کا وعدہ لیا تو ہم لوگ عقبہ میں جمع ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس آئے، عباس (جو ابھی تک مسلمان نہیں ہوئے تھے) اکیلے رسول اللہ صلی اللہ علیہ وسلم کے پیچھے آئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اپنے بارہ(۱۲) نقیب ذمہ دار میرے سامنے پیش کرو۔”(3) پھر ان کا ذکر کیا۔ اسی میں ہے کہ: بنی عمرو بن عوف کے نقیب سعد بن خیثمہ تھے۔ امام بخاری(4) تاریخ میں بطریق رباح بن ابی معروف روایت کرتے ہیں کہ میں نے مغیرہ بن حکیم سے سنا: میں نے عبداللہ بن سعد بن خیثمہ سے پوچھا: کیا آپ بدر میں شریک تھے۔ فرمایا: ہاں، عقبہ میں بھی۔ میں اپنے والد کے ساتھ سوار تھا وہ نقیب تھے۔ ابن اسحاق(5) کا قول ہے: نبی صلی اللہ علیہ وسلم قباء میں کلثوم بن الہدم کے ہاں فروکش ہوئے، تو آپ جب وہاں سے باہر تشریف لاتے تو لوگوں کے لیے سعد بن خیثمہ کے گھر میں بیٹھتے۔ اسے “بیت الغراب” کہا جاتا تھا۔(6) ابن اسحاق(7) کا قول ہے: سعد بن خیثمہ بدر میں شہید ہوئے۔ موسیٰ بن عقبہ کا قول ہے کہ ابن ہشام نے فرمایا: سعد بن خیثمہ اور ان کے بیٹے سعد نے قرعہ اندازی کی تو سعد کا قرعہ نکلا تو ان کے والد کہنے لگے: بیٹا! آج مجھے ترجیح دے دو تو سعد نے ان سے کہا: ابا جان! اگر جنت کے علاوہ کوئی چیز ہوتی میں ایسا کر دیتا۔ چنانچہ سعد بدر میں شریک ہوئے اور شہادت سے سرفراز ہوئے۔ جبکہ ان کے والد خیثمہ اُحد میں شہید ہوئے، ابن المبارک، سلیمان بن ابان تک اپنی سند سے اس مفہوم کا واقعہ نقل کرتے ہیں۔ اس کا کہنے والا کون ہے؟ اس میں اختلاف ہے۔ بقول بعض: طعیمہ بن عدی، ایک قول ہے: عمرو بن عبدود۔ ابونعیم کا گمان ہے: یہ سعد بن خیثمہ وہی ابوخیثمہ ہیں جو تبوک میں پیچھے رہ گئے تھے، بعد میں آملے۔ اور ان کے سوانح میں بطریق ابراہیم بن عبداللہ بن خیثمہ بحوالہ اپنے والد اپنے دادا سے روایت کرتے ہیں کہ میں غزوہ تبوک میں پیچھے رہ گیا، پھر وہ واقعہ نقل کیا۔ حق بات یہ ہے کہ وہ اور ہیں۔ کیونکہ اہل سیر کا اس پر اتفاق ہے کہ اس عنوان والے بدر میں شہید ہوئے۔ انہی کے سوانح میں ابن مندہ اور ابونعیم نے ایک اور حدیث اسی طرح بطریق ابراہیم نقل کی ہے جو وہم ہے۔ ابو جعفر بن حبیب، سیدنا حسان بن ثابت رضی اللہ عنہ کے قول: مجھے ایسی (سعود) برکت دکھاؤ جیسی برکت مکہ میں عمرو بن عامر کی اولاد میں پروان چڑھی ہے انہوں نے دین کے ستون کو اتنا مضبوط کیا کہ اس کی بنیادیں (زمین سے) پیوست ہو گئیں۔ ان کی یہ ساری محنت کوشش باریک اور شمشیر بر ان کا نتیجہ ہے۔ لکھتے ہیں: سعود سے مراد سات(۷) افراد ہیں۔ چار اوس سے اور تین خزرج سے۔ خزرج کے(۱) سعد بن عبادہ،(۲) سعد بن الربیع،(۳) سعد بن عثمان۔ ابو عبادہ اور اوس کے چار افراد یہ ہیں:(۱) سعد بن معاذ،(۲) سعد بن خیثمہ،(۳) سعد بن عبید،(۴) سعد بن زید۔","",{"fn":"(1) اسد الغابہ (۱۹۸۶) استیعاب (۹۳۴) تجرید (۲۱۳/۱)\n(2) السیرۃ النبویۃ (۶۵/۲)\n(3) المستدرک (۲۵۲/۳)\n(4) التاریخ الکبیر (۴۹/۲)\n(5) السیرۃ النبویۃ (۹۳/۲)\n(6) المعجم الکبیر (۵۴۱۴) مجمع الزوائد (۹۹۲۲)\n(7) السیرۃ النبویۃ (۹۰/۲)"}],[3144,"§۳۱۵۰ ۔ سعد بن خیثمہ السالمی\nوہ ابوخیثمہ جو تبوک میں رہ گئے تھے۔ سابقہ شخصیت میں ان کا تذکرہ ہوا ہے، کنیتوں میں بیان ہوگا۔ یہ کنیت سے ہی زیادہ مشہور ہیں۔ بقول بعض: ان کا نام مالک بن قیس ہے یہ خزرجی ہیں، جبکہ پہلے والی شخصیت اوسی ہے۔"],[3145,"§۳۱۵۱ ۔ سعد بن ابی ذباب الدوسی(1)\nبقول ابن حبان(2): صحابی ہیں۔ امام احمد اور ابن ابی شیبہ کی بحوالہ سعد بن ابی ذباب روایت ہے کہ میں جب رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور میں نے اسلام قبول کر لیا تو آپ نے مجھے اپنی قوم پر مقرر کر دیا اور جو مال ان کے پاس تھے اسلام لانے کے بعد انہیں اسی ملکیت پر برقرار رکھا۔ (حدیث)(3) اسی میں سیدنا عمر رضی اللہ عنہ کے ساتھ ان کا ایک واقعہ ہے جو شہد کی زکوۃ کے متعلق ہے۔ بغوی لکھتے ہیں: مجھے اس کے علاوہ ان کی دوسری روایت معلوم نہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۸۶) استیعاب (۹۳۴) تجرید (۲۱۳/۱)\n(2) الثقات (۱۵۳/۳)\n(3) مسند احمد (۷۹/۶) المعجم الکبیر (۵۴۵۸) المصنف لابن ابی شیبۃ (۱۴۱/۳)، (۱۴۲/۳) مجمع الزوائد (۲۸/۱) کتاب الاموال (۱۴۸۷)"}],[3146,"§۳۱۵۲ ۔ سعد بن ذؤیب(1)\nابوداؤد، نسائی، ابن ابی شیبہ، دارقطنی اور حاکم نے بطریق سدی جو حدیث روایت کی ہے اس میں ان کا ذکر آتا ہے کہ فتح مکہ کے موقع پر آپ صلی اللہ علیہ وسلم نے سوائے چار افراد کے عام لوگوں کو امان دے دی۔ عکرمہ بن ابی جہل، عبد اللہ بن خطل، مقیس بن صبابہ، عبد اللہ بن سعد بن ابی سرح، ابن خطل تو کعبہ کے پردوں کو تھامے ہی قتل ہو گیا۔ سعد بن ذؤیب اور عمار بن یاسر اس کی طرف بڑھے۔ سعد بن ذؤیب جوان تھے، اس لیے قتل کرنے میں سبقت لے گئے۔(2) (حدیث) بعض روایات میں جو ابن ابی شیبہ اور بیہقی(3) وغیرہ میں ہے: سعد بن ذؤیب کے بجائے سعید بن حریث لکھا ہے۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۱۹۹۰) تجرید (۲۱۳/۱)\n(2) ابوداؤد کتاب الجہاد (۲۶۸۳) نسائی کتاب التحریم (۴۰۷۸) المصنف لابن ابی شیبۃ (۵۳۴/۸) المستدرک (۴۵/۳) جامع المسانید (۹۳/۵)\n(3) دلائل النبوۃ (۶۰/۵)"}],[3147,"§۳۱۵۳ ۔ سعد بن ابی رافع(1)\nابن حبان(2) نے صحابہ میں ان کا ذکر کیا ہے اور طبرانی نے بطریق ابن ابی نجیح بحوالہ مجاہد روایت کی ہے کہ سعد بن ابی رافع نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم میرے پاس عیادت کے لیے تشریف لائے میرے سینہ پر ہاتھ رکھا جس کی ٹھنڈک مجھے اپنے دل میں محسوس ہوئی پھر آپ نے فرمایا: تمہیں دل کی تکلیف ہے حارث بن کلدہ (طبیب) سے علاج کراؤ۔(3) ......حدیث...... سعد بن ابی رافع کہنے میں یونس بن الحجاج، بواسطہ ابن عیینہ بحوالہ ابن ابی نجیح، متفرد ہیں۔ یہی روایت حسن بن سفیان نے قتیبہ سے بحوالہ ابن عیینہ نقل کی تو اس میں فرمایا: “سعد نے کہا” اور ان کا نسب نہیں بیان کیا۔ ایسا ہی ابوداؤد، تمام بن مندہ(4) نے بروایت ابن عیینہ نقل کیا ہے۔ ابن اسحاق نے اسماعیل بن محمد بن سعد بن ابی وقاص سے بحوالہ اپنے والد اپنے دادا سے ایسا ہی نقل کیا ہے یا تو یونس بن الحجاج کو ابن ابی رافع کی بات میں وہم ہوا ہے یا دو واقعات ہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۹۱) تجرید (۵۱۳/۱)\n(2) الثقات (۱۴۶/۳)\n(3) المعجم الکبیر (۵۴۷۹/۶) مجمع الزوائد (۸۸/۵) جامع المسانید (۹۴/۵) اسد الغابہ (۲۹۳/۲)\n(4) ابوداؤد کتاب الطب باب فی ثمرۃ العجوۃ (۳۸۷۵)"}],[3148,"§۳۱۵۴ ۔ سعد بن الربیع(1)\nبن عمرو بن ابی زہیر بن مالک بن امرئ القیس بن مالک الاغر بن ثعلبہ بن کعب بن الخزرج انصاری خزرجی انصار کے نقیبوں میں سے ایک۔ سعد بن خیثمہ کے حالات میں ان کا ذکر ہوا ہے۔ امام بخاری کی روایت ہے کہ عبد الرحمن بن عوف رضی اللہ عنہ نے فرمایا: ہم جب مدینہ آئے تو نبی صلی اللہ علیہ وسلم نے میرے اور سعد بن ربیع کے درمیان بھائی چارہ قائم فرمایا، تو سعد کہنے لگے: سارے انصار میں سے میں زیادہ مالدار ہوں میں اپنا آدھا مال تمہیں دیتا ہوں۔ حدیث صحیحین میں حدیث انس سے اسی کا مفہوم مروی ہے۔ موطا(2) میں امام مالک فرماتے ہیں۔ کہ یحیی بن سعید نے فرمایا: احد کے روز جب جنگ سرد پڑی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میرے پاس سعد بن ربیع کی خبر کون لائے گا؟ تو ایک شخص بولا: میں لاتا ہوں اللہ کے رسول صلی اللہ علیہ وسلم چنانچہ وہ مقتولین کے درمیان گھومنے لگا تو اس سے ان کی ملاقات ہو گئی تو وہ آخری سانسوں میں تھے، کہنے لگے: رسول اللہ صلی اللہ علیہ وسلم سے میرا سلام کہنا اور بتانا کہ مجھے نیزے کے بارہ(۱۲) زخم لگے ہیں اب میرا بچنا مشکل ہے اور اپنی قوم کو بتانا: اگر تم میں سے ایک شخص بھی زندہ رہا اور رسول اللہ صلی اللہ علیہ وسلم پر کسی نے قاتلانہ حملہ کر دیا تو اللہ کے ہاں تمہارا کوئی عذر نہیں چلے گا۔ “التمہید” میں ابوعمر لکھتے ہیں: مجھے یہ روایت مسنداً معلوم نہیں، جبکہ اہل سیر کے ہاں محفوظ ہے۔ ابن اسحاق نے محمد بن عبد اللہ بن عبد الرحمن بن ابی صعصعہ المازنی کے حوالہ سے ان کا ذکر کیا ہے۔ میں کہتا ہوں: صحیح میں حدیث انس میں اس کا کچھ شاہد موجود ہے۔ ابن الاثیر(3) لکھتے ہیں: ان کی طرف جو شخص گیا تھا وہ ابی بن کعب تھے۔ طبرانی(4) کی روایت ہے: کہ ام سعد بنت سعد بن ربیع سیدنا ابوبکر الصدیق رضی اللہ عنہ کے ہاں آئیں تو آپ نے ان کے لیے اپنی چادر بچھا دی جس پر وہ بیٹھیں اتنے میں سیدنا عمر رضی اللہ عنہ آ گئے۔ پوچھا یہ کون ہے، سیدنا ابوبکر رضی اللہ عنہ نے فرمایا: یہ اس شخص کی بیٹی ہے جو مجھ سے اور تم سے بہتر ہے۔ انہوں نے پوچھا: خلیفہ رسول اللہ صلی اللہ علیہ وسلم وہ کون ہے؟ فرمایا: وہ شخص جو عہد رسول اللہ صلی اللہ علیہ وسلم میں فوت ہوا اور جنت میں اپنا ٹھکانہ بنالیا جبکہ میں اور تم رہ گئے۔ “احکام القرآن” میں قاضی اسماعیل کی روایت ہے کہ عمرہ بنت حزم سعد بن ربیع کے نکاح میں تھیں، وہ احد میں شہید ہو گئے جن سے ان کی ایک بیٹی تھی تو نبی صلی اللہ علیہ وسلم سے اپنی بیٹی کی میراث طلب کرنے آئیں۔ جس کے متعلق یہ آیت نازل ہوئی: “لوگ آپ سے عورتوں کے بارے میں شریعت کا حکم پوچھتے ہیں”۔ مؤرخین کا اس پر اتفاق ہے کہ وہ احد میں شہید ہوئے(5) مقاتل نے اپنی تفسیر میں لکھا ہے کہ یہ آیت ان کے بارے میں نازل ہوئی: “مرد عورتوں کے نگران ہیں”۔ اور ان کے متعلق لکھا ہے(6) کہ وہ انصار کے نقیبوں میں سے تھے۔ ایسا ہی اسماعیل بن احمد الضریر (نابینا) نے اپنی تفسیر میں لکھا ہے لیکن ان کا نام اسعد بتایا اور الف میں ان کا تذکرہ کیا ہے جو لفظی غلطی ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۹۳) استیعاب (۹۳۶) تجرید (۲۱۴/۱)\n(2) موطا امام مالک کتاب الجہاد باب الترغیب فی الجہاد (۱۰۳۵)\n(3) اسد الغابہ (۲۹۴/۲)\n(4) المعجم الکبیر (۵۴۰۱)\n(5) سورۃ النساء (۱۲۷)\n(6) اسد الغابہ (۳۴)"}],[3149,"§۳۱۵۵ ۔ سعد بن الربیع(1)\nبن عمرو بن عدی انصاری یا حارث، سعد ابن حنظلیہ سے مشہور ہیں۔ یہی سہل بن حنظلیہ کے بھائی ہیں۔ حنظلیہ ان کی والدہ ہیں۔ بقول بعض: دادی ہیں۔ ابوعمر(2) بن عبد البر لکھتے ہیں: ان کے والد کا نام عقیب تھا۔ میں کہتا ہوں: یہی ابن سعد کا قول ہے۔ ابوحاتم(3) رقمطراز ہیں: احد میں شہید ہوئے، جس میں تامل ہے۔ شاید ان کی مراد پہلی شخصیت ہے۔ رہے یہ تو ابن سعد کا بیان ہے: غزوہ خندق میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۱۹۹۴) استیعاب (۹۳۶)\n(2) استیعاب (۱۵۷/۲)\n(3) الجرح والتعدیل (۸۲/۴)"}],[3150,"§۳۱۵۶ ۔ سعد بن زرارہ انصاری(1)\nاسعد بن زرارہ کے بھائی۔ انہی کے سوانح میں نسب بیان ہو چکا ہے۔ ابوحاتم(2) نے صحابہ میں ان کا تذکرہ کیا ہے ایسا ہی باوردی اور ابن شاہین نے لکھا ہے، ہم نے تیسری میں حدیث ابی روق ہمدانی سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم یہ دعا کیا کرتے تھے: “اے اللہ! جو مجھ سے زیادتی کرے اس کے مقابلہ میں میری مدد فرما۔” (حدیث)(3) طبرانی نے مسند شامیین میں یونس بن راشد کے سوانح میں روایت نقل کی ہے کہ جب آیت “جو باتیں تمہارے دلوں میں ہیں خواہ تم ان کو ظاہر کرو یا چھپاؤ”(4) تو سیدنا صدیق اکبر، عمر، معاذ بن جبل اور سعد بن زرارہ رضی اللہ عنہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگے: ہم پر اس سے سخت (حکم والی) آیت نہیں نازل ہوئی۔ (حدیث) ابن مندہ نے ان کے حالات میں روایت نقل کی ہے کہ ایک روز رسول اللہ صلی اللہ علیہ وسلم اپنے رب کی بات سنانے لگے: “اللہ تعالیٰ اپنے بندے کی نعمتوں کے تذکرہ سے زیادہ اس بات کو پسند فرماتا ہے کہ میں اس ایمان کی ہدایت کا ذکر کروں جو اس نے اسے عطا کی ہے۔” (حدیث)(5) ابونعیم نے اسی سند سے نقل کی تو ہے لیکن وہ دوسری سند سے لکھی ہوئی جو ان کے دادا اسعد سے مروی ہے اسعد اور سعد دونوں محمد کے دادا اور نانا ہیں۔ اور مذکورہ حدیث اسعد کی ہے بنا پر ابونعیم نے ابن مندہ کا اس میں وہم بیان کر دیا ہے، لیکن دوسروں نے صحابہ میں ان کا ذکر کر دیا ہے۔ ابن عبد البر(6) لکھتے ہیں: اس میں تامل ہے۔ مجھے خدشہ ہے کہ اسلام کا دور بھی انہوں نے نہیں پایا۔ کیونکہ اکثریت نے ان کا تذکرہ نہیں کیا۔ واقدی اور عدوی کا بیان ہے۔ نفاق کی تہمت ان کی طرف منسوب تھی شاید تائب ہو گئے ہوں۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۱۹۹۶) استیعاب (۹۳۷) تجرید (۲۱۴/۱)\n(2) الجرح والتعدیل (۱۳/۴)\n(3) کنز العمال (۳۷۷۴)\n(4) سورۃ البقرۃ (۲۸۴)\n(5) اسد الغابہ (۲۹۵/۲)\n(6) استیعاب (۱۵۷/۲)"}],[3151,"§۳۱۵۷ ۔ سعد بن زید(1)\nبن سعد اشہلی۔ بقول ابوحاتم(2): انہیں شرف صحابیت حاصل ہے۔ امام بخاری تاریخ میں، الحاکم اور ابن مندہ نے بطریق ابراہیم بن جعفر بن محمد بن مسلمہ کی اولاد سے ہیں۔ بحوالہ سعد اشہلی روایت کی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں تلوار کا بہدیہ بھیجا”۔ (حدیث) البغوی فرماتے ہیں: مجھے اس کے علاوہ ان کی کوئی روایت معلوم نہیں۔ ابن مندہ اور طبرانی(3) نے اوسط میں دوسری سند سے نقل کیا ہے جس میں “سعید” یا کے اضافہ سے ہے، پہلی روایت زیادہ راجح ہے۔","",{"fn":"(1) اسد الغابہ (۱۹۹۷) استیعاب (۹۴۰)\n(2) الجرح والتعدیل (۸۳/۴)\n(3) المعجم الاوسط (۵۴۲۴/۶)"}],[3152,"§۳۱۵۸ ۔ سعد بن زید بن الفاکہ\nاسعد میں ذکر ہوا ہے۔"],[3153,"§۳۱۵۹ ۔ سعد بن زید(1)\nبن مالک بن عبد بن کعب بن عبد الاشہل انصاری اشہلی۔ موسیٰ بن عقبہ اور ابن اسحاق وغیرہ نے ان کا ذکر کیا ہے کہ بدر میں شریک ہوئے۔ واقدی کا بیان ہے عقبہ میں شریک ہوئے۔ ابوعمر کا گمان ہے۔ نیز العسکری اور ابونعیم نے لکھا ہے کہ سابقہ حالات میں جو حدیث ہے وہ انہوں نے روایت کی ہے۔ سیرت میں ان کا ذکر آتا ہے۔ انہوں نے ہی مشلل میں بنا مینار ڈھایا تھا۔ نبی صلی اللہ علیہ وسلم نے انہی کے ہاتھ بنی قریظہ کے قیدی بھیجے تھے جس سے انہوں نے گھوڑے اور ہتھیار خریدے تھے۔ دیوان حسان بن ثابت رضی اللہ عنہ میں ہے کہ جب عیینہ بن حصن نے مدینہ کی چراگاہ پر حملہ کیا تھا تو سیدنا حسان نے یہ اشعار کہے: “کیا لقیط کی اولاد اس بات سے خوش ہوئی کہ مقدار کے گھوڑ سواروں کی صبح ہم سلامتی سے تھے”۔ تو سعد بن زید اشہلی نے انہیں ڈانٹا کہ اس دن گھوڑ سواروں کو مقدار کی جانب کیوں منسوب کیا میری طرف کیوں منسوب نہیں کیا، کیونکہ یہی گھوڑ سواروں کے سردار تھے۔ چنانچہ سیدنا حسان نے معذرت چاہی۔ لقیط سے مراد حصن بن حذیفہ کی والدہ ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۰۰)"}],[3154,"§۳۱۶۰ ۔ سعد بن زید انصاری(1)\nبغوی نے ان میں اور سابقہ شخصیت میں فرق کیا ہے اور بطریق یزید بن ابی زیاد یہ روایت نقل کی ہے کہ سعد بن زید انصاری نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے سیدنا حسن کو اٹھا کر فرمایا: “اے اللہ! میں اس سے محبت کرتا ہوں آپ بھی اس سے محبت رکھیے”۔(2) دوبار فرمایا، بغوی لکھتے ہیں: یزید بن ابی زیاد سے آگے راویوں میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۰۱) استیعاب (۹۴۱)\n(2) المعجم الکبیر (۲۵۸۱/۶)"}],[3155,"§۳۱۶۱ ۔ سعد بن زید\nالطائی یا انصاری۔ زید بن کعب کے حالات میں تذکرہ ہوا ہے۔"],[3156,"§۳۱۶۲ ۔ سعد بن سعد الساعدی(1)\nسہل بن سعد کے بھائی۔ طبرانی(2) کی روایت ہے کہ نبی صلی اللہ علیہ وسلم نے بدر میں سعد بن سعد کے لیے ایک حصہ(3) مقرر فرمایا، مشہور یہ ہے کہ یہ حصہ سعد جو سہل کے والد ہیں ان کے لیے مقرر ہوا تھا۔ جیسا کہ ان کے حالات میں بیان ہوگا۔ بقول بعض: وہ سعد بن سعد ہیں۔ اگر یہی بات ہے تو یہ عنوان ختم ہو جاتا ہے لیکن مشہور یہ ہے کہ یہ حصہ سعد بن مالک کا تھا جیسا کہ بیان ہوگا۔","",{"fn":"(1) اسد الغابہ (۲۰۰۳)\n(2) المعجم الکبیر (۵۷۱۸/۶)\n(3) اسد الغابہ (۲۹۷/۲)"}],[3157,"§۳۱۶۳ ۔ سعد بن ابی سعد(1)\nبن سعد انصاری۔ بنی نوفل کے حلیف۔ بقول طبری وغیرہ احد میں شریک ہوئے۔ ابوموسیٰ نے اپنے استدراک میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۰۴) استیعاب (۹۴۲)"}],[3158,"§۳۱۶۴ ۔ سعد بن سعید\nجہیم کے خاوند، ان شاء اللہ تعالیٰ خواتین کے حصہ میں باب ہند میں تذکرہ ہوگا۔"],[3159,"§۳۱۶۵ ۔ سعد بن سفیان بن مالک\nبن حبیب بن مالک بن خفاف سلمی۔ بقول رشاطی: شجرہ بغدادیہ کے نسب میں ان کا تذکرہ ملتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے تھے۔"],[3160,"§۳۱۶۶ ۔ سعد بن سلامہ(1)\nبن قوش اشہلی۔ بقول ابن کلبی: جسر کے روز سیدنا ابوعبید کے ساتھ شہید ہوئے۔ بقول بعض: یہ ابونا ملکہ کا نام ہے۔ ابن کلبی نے دونوں میں فرق کیا ہے۔ درست یہی ہے کہ ابونا ملکہ کا نام ملکان ہے۔ کنیتوں میں تذکرہ ہونا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۰۵) استیعاب (۹۴۳)"}],[3161,"§۳۱۶۷ ۔ سعد بن سوید(1)\nبن قیس یا عبید بن الابجر بن خدرہ بن عوف بن حارث بن خزرج انصاری خزرجی۔ موسیٰ بن عقبہ اور ابن اسحاق نے شرکاء بدر میں اور ابن شہاب نے شہداء احد میں ذکر کیا ہے انہوں نے ان کے دادا کا نام عبید بتایا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۰۶) استیعاب (۹۴۵)"}],[3162,"§۳۱۶۸ ۔ سعد بن سہل(1)\nبن مالک بن کعب بن عبد الاشہل بن حارثہ بن دینار ابن النجار انصاری خزرجی۔ ابن عقبہ اور ابن اسحاق(2) نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ابوالاسود نے بحوالہ عروہ ان کے والد کا نام تصغیر سے سہیل بتایا ہے جس کی بنا پر ابن مندہ نے دو عنوان قائم کر دیے۔ ابومعشر اور واقدی کا بیان ہے: سعید بن سہیل۔ تو ابوموسیٰ نے اسے تیسری شخصیت بنا لیا۔ ابن ابی حاتم بحوالہ اپنے والد سعید نامی لوگوں میں ان کا تذکرہ کرتے ہیں۔ یوں ابن عبد البر نے انہیں دوسری شخصیت سمجھ لیا۔ اور یہ گمان کیا کہ ابن اسحاق ان کے بیان سے غافل رہے حالانکہ ایسا نہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۰۷)\n(2) السیرۃ النبویۃ (۲۶۳/۲)"}],[3163,"§۳۱۶۹ ۔ سعد بن ضمیرہ(1)\nبن سعد بن سفیان بن مالک بن حبیب بن زغب بن مالک بن خفاف بن امرئ القیس بن بہثہ بن سلیم سلمی۔ بقول بعض: اسلمی، انہیں ضمیری اور حجازی بھی کہا گیا ہے۔ حنین میں شریک ہوئے۔ ابن قانع نے ان کا نسب بیان کیا ہے۔ محلم بن جثامہ کے واقعہ میں ابوداؤد میں ان کی حسن سند سے ایک حدیث مروی ہے۔ ان شاء اللہ تعالیٰ مکحیل (مکمل) کے حالات میں ان کا تذکرہ ہوگا۔","",{"fn":"(1) اسد الغابہ (۲۰۰۹) استیعاب (۹۴۷) تجرید (۲۱۵/۱)"}],[3164,"§۳۱۷۰ ۔ سعد بن طریف\nالمتفق میں خطیب نے ان کا ذکر کیا ہے کہ بقول بعض: یہ صحابی ہیں جبکہ سند میں کئی ایک مجہول راوی ہیں۔ پھر بطریق سہیل بن عبدالواسطی روایت کی ہے کہ سعد بن طریف نے فرمایا: ایک دفعہ میں نبی صلی اللہ علیہ وسلم کے ساتھ مدینہ کی کسی جگہ چل رہا تھا گدھے پر سوار ایک عورت جا رہی تھی جسے ایک حبشی لے جا رہا تھا اچانک گدھے کا پاؤں پھسلا اور وہ گر گیا۔ عورت بھی گر پڑی۔ آپ صلی اللہ علیہ وسلم نے فوراً چہرہ پھیر لیا۔ میں نے عرض کی اللہ کے رسول! اس نے شلوار پہن رکھی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اللہ تعالیٰ شلوار پہننے والوں پر رحم کرے”۔ خطیب(1) فرماتے ہیں: میں نے اسی سند سے یہ حدیث لکھی ہے جبکہ اس کی سند میں کئی ایک مجہول راوی ہیں۔ ابن الجوزی کا قول ہے۔ احتمال ہے کہ یہ سعد بن طریف الاسکاف ہوں۔ یوں ان کے اور ان کے شیخ کے شیخ کا تذکرہ رہ گیا۔","",{"fn":"(1) المصنف لعبد الرزاق (۵۰۴۳)"}],[3165,"§۳۱۷۱ ۔ سعد بن عامر\nبن مالک انصاری۔ یہ اور ان کے بھائی حمزہ احد میں شریک ہوئے یہ ابن سعد عبدوی اور طبری کا قول ہے۔"],[3166,"§۳۱۷۲ ۔ سعد بن عائذ(1)\nالمؤذن مولا عمار بن یاسر۔ بقول بعض: مولا انصار، ایک قول ہے: ان کے والد کا نام عبد الرحمن ہے جو سلم کے بتوں کی تجارت کرتے تھے۔ یوں انہیں سعد القرظ کہا جانے لگا۔ بغوی کی روایت ہے کہ سعد نے رسول اللہ صلی اللہ علیہ وسلم سے تنگدستی کی شکایت کی تو آپ نے انہیں تجارت کا حکم دیا۔ چنانچہ وہ بازار گئے سلم کے پتے خرید کر بیچے جس میں انہیں منافع ہوا۔ نبی صلی اللہ علیہ وسلم سے اس کا ذکر کیا۔ آپ نے فرمایا: بس یہی کیا کرو۔ نبی صلی اللہ علیہ وسلم سے روایت کی ہے اور آپ کی زندگی میں مسجد میں اذان دی۔ ان سے ان کے بیٹے عمار اور عمر روایت کرتے ہیں، بعد میں سیدنا ابوبکر نے انہیں مسجد قباء سے مسجد نبوی منتقل کر دیا جہاں انہوں نے سیدنا بلال کے بعد اذانیں دیں اور ان کے بیٹوں نے ان سے اذان کی میراث پائی۔ خلیفہ کا قول ہے: سیدنا سعد نے سیدنا ابوبکر اور ان کے بعد سیدنا عمر رضی اللہ عنہ کے دور میں اذان دی۔ زہری کی روایت ہے کہ قباء سے منتقل کرنے والے سیدنا عمر تھے۔ ابواحمد العسکری کا قول ہے: سعد القرظ حجاج کے زمانہ تک زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۲۰۱۲) استیعاب (۹۴۸) تجرید (۲۱۵/۱)"}],[3167,"§۳۱۷۳ ۔ سعد بن عباد\nابن حزم کا بیان ہے کہ مسند بقی میں ان کی ایک حدیث ہے۔ ذہبی نے تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے کہ مجھے اس کی اسناد کا علم نہیں۔ تاریخ البخاری میں ہے: سعد بن عباد زرقی سیدنا عمر رضی اللہ عنہ سے اور ان سے ان کا بیٹا عمر روایت کرتا ہے، لہذا احتمال ہے یہ وہی ہوں۔"],[3168,"§۳۱۷۴ ۔ سعد بن عبادہ(1)\nبن دلیم بن حارثہ بن حرام بن خزیمہ بن ثعلبہ بن طریف بن الخزرج بن ساعدہ بن کعب بن الخزرج انصاری خزرج کے سردار کنیت ابوثابت اور ابوقیس تھی۔ والدہ کا نام عمرہ بنت مسعود تھا جو صحابیہ ہیں۔ اور عہد نبوی میں ہی ۵ھ میں فوت ہو گئی تھیں۔ سیدنا سعد عقبہ میں شریک تھے اور ایک نقیب تھے۔ بدر میں ان کی شرکت کے متعلق اختلاف ہے۔ امام بخاری(2) نے اسے ثابت کیا ہے۔ ابن سعد(3) کی روایت ہے کہ وہ نکلنے کی تیاریوں میں تھے کہ کتے نے آ کاٹا اس لیے باز رہے۔ نبی صلی اللہ علیہ وسلم کو معلوم ہوا تو فرمایا: انہیں اس کی بڑی حرص تھی۔ ابن سعد(4) ہی کی روایت ہے کہ وہ عربی لکھنا جانتے تھے اور تیراکی اور تیر اندازی میں خوب مہارت رکھتے تھے جس کی وجہ سے انہیں “کامل” کہا جاتا تھا۔ جود و سخا میں خود، والد، دادا اور ان کا بیٹا مشہور تھا۔ ان کے قلعہ پر روزانہ اعلان کیا جاتا تھا، جسے روغن اور گوشت کی خواہش ہو وہ دلیم بن حارثہ کے قلعہ میں آ جائے۔ جعفرت کے گھر کا برتن نبی صلی اللہ علیہ وسلم کے ساتھ آپ کی ازواج کے گھروں میں گردش کرتا تھا۔ مقسم بحوالہ ابن عباس رضی اللہ عنہما روایت کرتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کے تمام مقامات پر دو جھنڈے ہوتے، ایک سیدنا علی رضی اللہ عنہ کے پاس مہاجرین کا جھنڈا اور سعد بن عبادہ کے ساتھ انصار کا پرچم۔ امام احمد رحمہ اللہ نے ان کی روایت نقل کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے گھر ہم سے ملنے تشریف لائے، آپ نے فرمایا: “السلام علیکم ورحمۃ اللہ”۔ (حدیث) اسی میں ہے پھر آپ نے ہاتھ اٹھا کر یہ دعا کی: “اے اللہ! اپنی رحمتیں اور برکتیں سعد بن عبادہ کے خاندان پر قائم رکھ”۔ ابویعلیٰ(5) حدیث جابر سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اللہ تعالیٰ انصار کو خصوصاً عبداللہ بن عمرو بن حرام اور سعد بن عبادہ کو جزائے خیر عطا فرمائے”۔ ابن ابی الدنیا بطریق ابن سیرین روایت کرتے ہیں: اہل صفہ کو کھانے کے لیے کوئی شخص ایک دو کوئی دو کوئی ایک ٹولی کو لے جاتا جبکہ سعد رضی اللہ عنہ اسی(۸۰) اصحاب صفہ کو اپنے ہاں کھانے کے لیے لے جاتے تھے۔ دارقطنی “کتاب الاسخیاء” میں بطریق ہشام بن عروہ وہ بحوالہ اپنے والد روایت کرتے ہیں کہ سعد کے قلعہ پر اعلان ہوتا تھا، اور سعد فرماتے: اے اللہ! مجھے سخاوت نصیب فرما جس کا مدار سخاوت کرنے پر ہے اور وہ مال پر موقوف ہے۔ اے اللہ! تھوڑا مال نہ میرے لیے مناسب اور نہ میں اس کی صلاحیت رکھتا ہوں۔ محمد بن سیرین کی روایت ہے کہ سعد کے ہاں اسی اصحاب صفہ کا کھانا ہوتا تھا۔ بیعت ابی بکر رضی اللہ عنہ سے تاخیر کا قصہ مشہور ہے۔ بعد میں شام چلے گئے جہاں حوران میں پندرہ (۱۵ھ) بقول بعض سولہ (۱۶ھ) میں وفات پائی۔ ان سے ان کے بیٹے قیس، سعید اور اسحاق اور پوتا شرحبیل بن سعید روایت کرتے ہیں جبکہ دیگر صحابہ میں سے ابن عباس، ابوامامہ بن سہل روایت لیتے ہیں حسن بصری اور عیسیٰ بن فائد ان سے مرسل روایت کرتے ہیں۔ ابوداؤد(6) کی حدیث قیس بن سعد سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “اللھم اجعل صلواتک و رحمتک علی آل سعد بن عبادہ”۔ بقول بعض: ان کی قبر دمشق کی نشیبی زمین میں واقع منیجہ گاؤں میں ہے۔ سعید بن عبد العزیز سے مروی ہے: ان کا انتقال بصریٰ میں ہوا یہ شام کا پہلا شہر ہے جو فتح ہوا تھا۔","",{"fn":"(1) اسد الغابہ (۲۰۱۲) استیعاب (۹۴۹)\n(2) التاریخ الکبیر (۵۹/۲)\n(3) الطبقات (۱۴۲/۳)\n(4) طبقات الکبریٰ (۱۴۲/۳)\n(5) مسند ابی یعلیٰ (۲۰۷۹/۴)\n(6) ابوداؤد، کتاب الادب کم مرۃ یسلم الرجل فی الاستئذان (۵۱۸۵)"}],[3169,"§۳۱۷۵ ۔ سعد بن عبداللہ(1)\nابن مردویہ نے تفسیر میں بطریق یعلیٰ بن الاشدق، بحوالہ سعد بن عبداللہ روایت کی ہے کہ کسی نے نبی صلی اللہ علیہ وسلم سے اللہ تعالیٰ کے اس ارشاد “اے نبی! جو لوگ تمہیں حجروں کے باہر سے پکارتے ہیں ان میں سے اکثر عقل سے عاری ہیں”(2)، کے متعلق دریافت کیا۔ آپ نے فرمایا: “یہ بنی تمیم کے سخت مزاج لوگ تھے، اگر یہ لوگ کانے دجال سے جنگ میں سب سے زیادہ سخت نہ ہوتے تو میں ان کی ہلاکت کی دعا کر دیتا”۔ ابن مندہ(3) فرماتے ہیں: یہ روایت غریب ہے، ہمیں صرف اسی سند سے معلوم ہوئی۔ میں کہتا ہوں: یعلیٰ متروک الحدیث راوی ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۱۳) تجرید (۲۱۶/۱)\n(2) سورۃ الحجرات (۶)\n(3) الدر المنثور (۸۷/۶) اسد الغابہ (۳۰۱/۲)"}],[3170,"§۳۱۷۶ ۔ سعد بن عبد قیس\nسعید میں تذکرہ ہوا ہے۔"],[3171,"§۳۱۷۷ ۔ سعد بن عبید(1)\nبن نعمان بن قیس بن عمرو بن زید بن امیہ بن زید انصاری اوسی۔ موسیٰ بن عقبہ وغیرہ نے شرکاء بدر میں ان کا تذکرہ کیا ہے۔ ابن نمیر اپنی تاریخ میں لکھتے ہیں: سعد بن عبید القاری سولہ (۱۶ھ) میں قادسیہ میں شہید ہوئے۔ جامع القرآن سیدنا زید رضی اللہ عنہ کے والد تھے۔ “اخبار مدینہ” میں زبیر بن بکار کی روایت ہے کہ سعد بن عبید دور نبوی میں مسجد قباء میں امامت کرتے تھے، صدیقی اور فاروقی دور میں بھی اسی پر مامور تھے۔ پھر آپ ہی کے دور حکومت میں فوت ہوئے تو سیدنا عمر رضی اللہ عنہ نے مجمع بن جاریہ کو امامت کا حکم تفویض کیا۔ تاریخ بخاری میں ہے: سعد بن عبید جنگ قادسیہ میں لوگوں سے خطاب کرتے ہوئے فرمانے لگے: “ہم کل شہید ہو جائیں گے ہمیں ہمارے انہیں کپڑوں میں کفنانا جن میں ہماری شہادت ہوگی”۔(2) ابن جریر بطریق قیس بن مسلم بحوالہ عبد الرحمن بن ابی لیلیٰ روایت کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے سیدنا سعد بن عبید سے فرمایا: اور اس دن شکست کھا گئے تھے جس روز ابوعبید رضی اللہ عنہ نے (جو ان کے امیر تھے) شہید ہو گئے تھے، انہیں (سعد بن عبید) کو قاری کہا جاتا تھا، ان کے علاوہ کسی کا نام قاری نہ تھا۔ پھر وہ واقعہ ذکر کیا۔ میں کہتا ہوں: جن زید نے عہد نبوی میں قرآن جمع کیا تھا ان کے والد کے نام میں اختلاف ہے۔ بقول بعض یہی ان کا نام ہے۔ ایک قول ہے: نہیں ان کا نام سعید تھا، کسی نے کچھ اور بھی کہا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۱۷) استیعاب (۹۵۱) تجرید (۲۶۱/۱)\n(2) بخاری کتاب التوحید (۷۴۱۶) مسلم کتاب اللعان (۳۷۴۲)"}],[3172,"§۳۱۷۸ ۔ سعد بن عثمان(1)\nبن خلدہ بن مخلد بن عامر بن زریق انصاری زرقی، ابوعبادہ۔ موسیٰ بن عقبہ وغیرہ نے بدری صحابہ میں ان کا ذکر کیا ہے “اخبار مدینہ” میں ہے کہ نبی صلی اللہ علیہ وسلم حمرہ چاہ اہاب پر تشریف لائے جو ان دنوں سعد بن عثمان کی ملکیت تھا جہاں وہ اپنے بیٹے عبادہ کو چھوڑ گئے تھے۔ تاکہ لوگوں کو پانی پلائیں۔ عبادہ نبی صلی اللہ علیہ وسلم کو نہ پہچان پائے، بعد میں سعد آئے انہوں نے آنے والی شخصیت کا حلیہ بیان کیا۔ سعد بولے: بیٹا! یہی تو رسول اللہ صلی اللہ علیہ وسلم ہیں جن کے پاس حق ہے۔ چنانچہ یہ بھاگتے ہوئے جا ملے آپ نے سر پر ہاتھ پھیرا اور دعا دی۔ بقول بعض: وہ اسی سال کے باوجود جوانی میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۰۱۹) استیعاب (۹۵۲)"}],[3173,"§۳۱۷۹ ۔ سعد بن عدی\nبنی عبد الاشہل کے حلیف اموی نے شہداء یمامہ میں ان کا تذکرہ کیا ہے۔ ابن فتحون نے اپنے استدراک میں ذکر کیا ہے۔"],[3174,"§۳۱۸۰ ۔ سعد بن عقیب\nسعد بن ربیع کے حالات میں ذکر ہوا ہے۔"],[3175,"§۳۱۸۱ ۔ سعد بن عمارہ الثعلبی(1)\nبقول عمرو بن شبہ، ابونعیم نے بحوالہ ابوبکر بن عیاش روایت کی ہے کہ بنی ثعلبہ بن سعد کا سعد بن عمارہ نامی ایک شخص آ کر کہنے لگا: اللہ کے رسول صلی اللہ علیہ وسلم! میں نے ہمیشہ ناپ تول کر بات کی ہے۔ سیف نے الفتوح میں لکھا ہے کہ سیدنا خالد بن ولید نے سعد بن عمارہ کو غطفان پر تیر انداز صحابہ کے ساتھ مقرر فرمایا۔ طبرانی کی بطریق ابن اسحاق، بحوالہ سعد بن عمارہ روایت ہے: جو بنی سعد بن بکر کے ایک صحابی ہیں ان سے کسی نے کہا: مجھے نصیحت کریں! فرمایا: “جب نماز پڑھنے کھڑے ہو تو ایسے پڑھو جیسے آخری نماز ہے۔ جس بات اور کام سے بعد میں معذرت کرنی پڑے اسے چھوڑ دو۔”(2) امام بخاری(3) رحمہ اللہ نے یہی روایت اپنی تاریخ میں ابن اسحاق تک کے دو طریق سے نقل کی ہے جن میں سے ایک میں سعد اور دوسری میں سعید ہے اور اسے راجح قرار دیا کہ یہ سعد ہیں۔ ایسا ہی امام احمد(4) نے کتاب الایمان میں اور طبرانی نے نقل کیا ہے اس کے رجال ثقہ ہیں۔ اور ابونعیم نے بطریق اسماعیل بن محمد بن سعد انصاری بحوالہ اپنے والد اپنے دادا سے مرفوع روایت کی ہے۔ لیکن انہوں نے عنوان علیحدہ قائم کیا ہے اور لکھا ہے “سعد ابو محمد” اور پھر یہی حدیث ذکر کی۔ مجھے لگتا ہے یہ وہی ہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۲۴)\n(2) المعجم الکبیر (۵۴۵۹/۶) مجمع الزوائد (۲۳۶/۱۰) جامع المسانید (۱۱۵/۵)\n(3) التاریخ الکبیر (۶۱/۲)\n(4) مسند احمد (۴۱۳/۵)"}],[3176,"§۳۱۸۲ ۔ سعد بن عمارہ\nبقول بعض: عمارہ بن سعد۔ ایک قول ہے: یہ ابوسعید زرقی کا نام ہے، کنیتوں میں تذکرہ ہو رہا ہے۔"],[3177,"§۳۱۸۳ ۔ سعد بن عمارہ\nبن خنساء بن مبذول انصاری۔ ان کے بھائی حمزہ کے حالات میں ان کا تذکرہ ہو رہا ہے۔"],[3178,"§۳۱۸۴ ۔ سعد بن عمرو(1)\nبن ثقیف بن مالک بن مبذول بن النجار انصاری۔ اہل سیر نے شرکاء احد میں ان کا ذکر کیا ہے۔ یہ ان کا بیٹا طفیل اور بھتیجا سہل بن عامر بن عمرو بن ثقیف واقعہ بئر معونہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۰۲۶) استیعاب (۹۵۵)"}],[3179,"§۳۱۸۵ ۔ سعد بن عمرو بن حرام\nان کا تذکرہ اور نسب ان کے بھائی حارث کے حالات میں بیان ہو چکا ہے۔ ان دونوں کے والد، جابر بن عبداللہ کے دادا نہیں ہیں۔ صرف ناموں میں اتفاق ہے جبکہ نسب مختلف ہے۔ ابو اسماعیل ازدی نے فتوح الشام میں لکھا ہے کہ سیدنا خالد بن ولید نے جب عراق سے شام کو حج کیا تو انبار میں انہیں اپنا نائب مقرر کر کے گئے۔ قسم ثالث میں سوید ابن قطبہ کے حالات میں ان کا ذکر ہوگا۔"],[3180,"§۳۱۸۶ ۔ سعد بن عمرو بن عبید(1)\nبن حارث بن کعب بن معاویہ بن عمرو بن مالک بن النجار انصاری عدوی کا بیان ہے: أحد میں شریک اور یمامہ میں شہید ہوئے۔ ابن دباغ اور ابن فتحون اور ابن کلبی نے حسب سابق ان دونوں کے اتباع میں اپنے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۲۸)"}],[3181,"§۳۱۸۷ ۔ سعد بن عمرو انصاری(1)\nحارث بن عمرو کے بھائی۔ بقول ابوعمر(2): جسے ابن کلبی نے نقل کیا ہے جیسا کہ حارث بن عمرو کے حالات میں بیان ہوا ہے، صحابہ میں سے صفین میں شرکت کرنے والوں میں سے ہیں۔ میں کہتا ہوں: شاید یہ پہلے والے ہیں، کیونکہ ابن فتحون نے اعتماد سے کہا ہے کہ دونوں ایک شخص ہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۲۵) استیعاب (۹۵۴)\n(2) استیعاب (۱۶۶/۲)"}],[3182,"§۳۱۸۸ ۔ سعد بن عمرو\nابو عفیفہ ثقفی۔ خلیفہ بن خیاط نے بصرہ فرودکش ہونے والے صحابہ میں ان کا ذکر کیا ہے۔"],[3183,"§۳۱۸۹ ۔ سعد بن عمیر(1)\nبقول ابن مندہ: ان کی حدیث عمرو بن قیس سے بواسطہ محمد بن مجاہد، ان کے والد سے بحوالہ ان کے مروی ہے، انہیں عمیر بن سعد بھی کسی نے لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۲۹)"}],[3184,"§۳۱۹۰ ۔ سعد بن الفاکہ(1)\nبن زید انصاری۔ بقول بعض: سعید بن زید بن الفاکہ، ایک قول ہے ان کے والد کا نام یزید ہے۔ ابونعیم لکھتے ہیں: ابن اسحاق(2) نے شرکاء بدر میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: الف میں اسعد بن الفاکہ میں تذکرہ ہوا۔ اگر یہ ان کے بھائی نہیں تو پھر اس میں لفظی غلطی ہے۔ ابن اسحاق کے مغازی کی عبارت یہ ہے: بدر میں بنی عامر بن زریق سے سعد بن الفاکہ بن زید بن خلدہ بن عامر شریک ہوئے، یہی معتبر ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۳۱)\n(2) السیرۃ النبویۃ (۲۵۹/۲)"}],[3185,"§۳۱۹۱ ۔ سعد بن قرحاء(1)\nبقول ابن ابی شیبہ: ایوب سے مروی ہے کہ سعد بن قرحاء صحابی ہیں۔ جنہوں نے ایک شخص کی (مطلقہ یا بیوہ) عورت اور اس شخص کی اس عورت سے پہلی بیوی کی بیٹی سے شادی کی تھی۔ اس طرح کا واقعہ جیم میں جبلہ کے حالات میں بیان ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۳۲) استیعاب (۹۵۷)"}],[3186,"§۳۱۹۲ ۔ سعد بن قیس العنزی(1)\nبقول بعض: العنسی۔ ابن مندہ کی روایت ہے کہ سعد بن قیس نبی صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم نے پوچھا: تمہارا کیا نام ہے: عرض کی: “سعد الخیل” فرمایا: نہیں تم سعد الخیر ہو۔ اور بطریق یحییٰ بن سعید انصاری بحوالہ عبداللہ بن ابی سلمہ مروی ہے کہ نبی صلی اللہ علیہ وسلم نے سعد بن مالک اور سعد الخیر کو مکہ بھیجا۔ ابن قانع اور ابن مندہ بطریق حسن بن فرقد حسن سے، بحوالہ سعد بن قیس نبی صلی اللہ علیہ وسلم کا ارشاد نقل کرتے ہیں: “اللہ تعالیٰ نے فرمایا: انسان! میرے لیے دن کے آغاز میں چار رکعتیں پڑھ لیا کر دن کے آخر تک میں تیرے لیے کافی ہوں”۔ ابن مندہ(2) نے پہلی سند اور دوسری سند والے شخص میں جن سے حسن روایت کرتے ہیں فرق کیا ہے باوجودیکہ وہ پہلے کے متعلق کہتے ہیں: ان سے ان کا بیٹا عبداللہ اور حسن روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۳۳)\n(2) مسند احمد (۲۸۶/۳) جامع المسانید (۱۱۷/۵) اسد الغابہ (۳۰۶/۲)"}],[3187,"§۳۱۹۳ ۔ سعد بن مالک\nبن الاقیصر بن مالک بن قریح بن ذہل بن الذئل بن سئل بن مالک ازدی، ابوالکنود۔ بقول ابن یونس: نبی صلی اللہ علیہ وسلم کے پاس آئے تو آپ نے ان کے لیے پھر یا بنایا جو سیاہ رنگ تھا، جس میں سفید چاند تھا اور انہیں ان کی قوم کا سردار بنایا۔ فتح مصر میں شریک ہوئے وہی ان کی اولاد ہے۔ ان سے ان کا بیٹا قاسم بن ابی الکنود روایت کرتا ہے اور سعید بن عفیر کی، بحوالہ عمرو بن زہیر بن اسمر بن ابی الکنود روایت ہے کہ ان کے والد ابوالکنود خدمت نبوی میں حاضر ہوئے، پھر اس کا ذکر کیا۔"],[3188,"§۳۱۹۴ ۔ سعد بن مالک العذری(1)\nابن ابی حاتم(2) بحوالہ اپنے والد روایت کرتے ہیں: بنی عذرہ کے وفد میں نبی صلی اللہ علیہ وسلم کے پاس آئے۔ واقدی کی روایت ہے کہ عمرو بن حریث عبدری کا قول ہے: میں نے اپنے آباء و اجداد کی تحریر میں لکھا پایا ہے کہ ہمارا وفد صفر نو (۹ھ) بارہ(۱۲) آدمیوں پر مشتمل نبی صلی اللہ علیہ وسلم کے پاس گیا جس میں جمرہ بن نعمان سعد اور سلیم، جو دونوں مالک کے بیٹے ہیں، شامل تھے۔","",{"fn":"(1) اسد الغابہ (۲۰۳۷) استیعاب (۹۶۰)\n(2) الجرح والتعدیل (۹۳/۴)"}],[3189,"§۳۱۹۵ ۔ سعد بن مالک بن اہیب(1)\nبقول بعض: ابن وہیب بن عبد مناف بن زہرہ بن کلاب قرشی زہری۔ ابو اسحاق بن ابی وقاص عشرہ مبشرہ میں سے اور ان میں سے سب سے آخر میں فوت ہونے والے بھی یہی ہیں۔ والدہ کا نام حمنہ بنت سفیان بن امیہ ہے جو ابو سفیان بن حرب بن امیہ کی چچا زاد بہن ہیں۔ نبی صلی اللہ علیہ وسلم سے کثرت سے احادیث روایت کی ہیں۔ ان سے ان کے بیٹے ابراہیم، عامر، مصعب، عمر، محمد اور عائشہ روایت کرتی ہیں۔ صحابہ میں سے سیدہ عائشہ، ابن عباس، ابن عمر، جابر بن سمرہ، جبکہ تابعین میں سے سعید بن المسیب، ابو عثمان نہدی، قیس بن ابی حازم، علقمہ، احنف وغیرہ روایت کرتے ہیں۔ اللہ کی راہ میں سب سے پہلا تیر انہوں نے ہی چلایا۔ نیز چھ اہل شوریٰ (مشورہ) میں سے ایک ہیں۔ سیدنا عمر رضی اللہ عنہ نے وصیت کی تھی کہ اگر امارت و حکومت انہیں مل جائے تو بہتر ورنہ حاکم ان سے صلاح مشورہ لے۔ فتح عراق کے سرداروں کے رئیس تھے۔ سیدنا عمر رضی اللہ عنہ کی طرف سے کوفہ کے والی بنے۔ انہوں نے ہی کوفہ آباد کیا تھا۔ پھر معزول ہو گئے۔ بعد میں سیدنا عثمان رضی اللہ عنہ کی طرف سے اس کے حاکم مقرر ہوئے۔ دعا قبول ہونے میں مشہور تھے۔ اکاون (۵۱ھ) بقول بعض چھپن (۵۶ھ) ستاون (۵۷ھ) یا اٹھاون (۵۸ھ) میں فوت ہوئے۔ دوسرا قول زیادہ مشہور ہے۔ ایک قول ہے: پچپن (۵۵ھ) یا پچون (۵۴ھ) میں فوت ہوئے۔ صحیح بخاری میں ان سے مروی ہے: میں نے سات دن گزارے کہ میں اسلام کا تیسرا جانثار تھا۔ ابراہیم بن المنذر کا قول ہے کہ سعد، طلحہ اور زبیر تینوں ہم عمر تھے۔ حدیث جابر(2) سے ترمذی کی روایت ہے سیدنا سعد آئے تو نبی صلی اللہ علیہ وسلم نے فرمایا: “یہ میرے ماموں ہیں کوئی شخص مجھے اپنا ماموں دکھائے”۔ مغازی میں ابن اسحاق(3) کا قول ہے: کہ مکہ میں اصحاب رسول اللہ صلی اللہ علیہ وسلم چھپ کر نمازیں پڑھتے تھے۔ ایک دفعہ سیدنا سعد بھی انہی صحابہ کے ساتھ مصروف عبادت تھے اچانک مشرکین آ پہنچے۔ انہوں نے ان کا مذاق اڑایا اور دین میں عیب نکالنے لگے یہاں تک کہ دست و گریباں ہو گئے۔ سیدنا سعد نے ایک مشرک کے سر پر اونٹ کی ہڈی اس زور سے ماری کہ سر پھٹ گیا، یہ پہلا خون تھا جو اسلام میں (کسی کافر کا) بہایا گیا۔ ترمذی(4) کی روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! جب سعد آپ سے دعا کیا کرے تو اس کی دعا قبول کرنا”۔ چنانچہ یہ جو دعا بھی مانگتے قبول ہوتی۔ ہم نے ابن ابی الدنیا کی کتاب “مجابی الدعوۃ” (جن کی دعا قبول ہوتی ہے) میں ایک روایت نقل کی ہے کہ ایک عورت تھی جس کا قد بچے جتنا تھا لوگوں نے بتایا یہ سیدنا سعد کی بیٹی ہے اس نے ان کے وضو میں ہاتھ مارا تھا تو آپ کی زبان سے نکل گیا: اللہ تیرا ہاتھ کاٹے! تو یہ اس کے بعد سے نہ بڑھی۔ جب سیدنا عثمان رضی اللہ عنہ شہید ہوئے تو فتنوں سے علیحدہ ہو کر گوشہ نشین ہو گئے۔ شیخین، ترمذی اور نسائی نے حدیث عائشہ سے روایت کی ہے کہ جب نبی صلی اللہ علیہ وسلم مدینہ آئے تو آپ کو دشمن کا خوف رہتا۔ آپ فرمانے لگے: “کاش! میرے صحابہ میں سے کوئی نیک شخص میرا پہرہ دیتا”۔ اچانک ہم نے ہتھیار(5) کی آواز سنی، آپ صلی اللہ علیہ وسلم نے فرمایا: “کون ہے؟” “میں سعد ہوں” جواب آیا۔ آپ کھڑے ہو گئے، ایک روایت میں ہے ان کے لیے دعا کی۔ سیدنا سعد رضی اللہ عنہ کا انتقال عقیق میں ہوا تو جنازہ مدینہ لایا گیا، مسجد میں جنازہ پڑھا گیا۔ واقدی فرماتے ہیں: ان کی وفات کے متعلق سب سے معتبر قول، پچپن (۵۵ھ) کا ہے۔ ابونعیم لکھتے ہیں: اٹھاون (۵۸ھ) میں فوت ہوئے۔ زبیر فرماتے ہیں: انہوں نے ہی کسریٰ کا دارالحکومت مدائن فتح کیا تھا۔ مستجاب الدعاء تھے، کوفہ کے والی بنے، فتنے کے دور میں گوشہ نشین رہے، ان کے پاس ان کا بھتیجا ہاشم بن عتبہ آ کر کہنے لگا: یہاں لاکھوں تلواریں ہیں لوگ آپ کو حکومت کا زیادہ حق دار سمجھتے ہیں۔ آپ نے فرمایا: مجھے ان میں سے صرف ایک تلوار چاہیے۔ اگر اس سے کسی مسلمان کو ماروں تو وہ اثر نہ کرے اور اگر کسی کافر کو ماروں تو اسے کاٹ کر رکھ دے۔ محمد بن عثمان بن ابی شیبہ نے اپنی تاریخ میں عمدہ سند سے، بحوالہ ابو اسحاق روایت کی ہے کہ چار اصحاب رسول صلی اللہ علیہ وسلم بہت سخت حملہ آور تھے: عمر، علی، زبیر اور سعد۔ مسند ابی یعلیٰ میں روایت ہے کہ سعد نے جب اصحاب رسول کا اختلاف و انتشار دیکھا تو ایک بنجر زمین خریدا اپنے اہل و عیال سمیت وہاں جا بسے۔ سیدنا سعد بڑے تیز نظر تھے، ایک دن دھول اڑتی دیکھی، فرمانے لگے: تم لوگوں کو کچھ نظر آ رہا ہے؟ وہ کہنے لگے: ہمیں پرندے جیسی کوئی چیز دکھائی دیتی ہے۔ فرمایا: مجھے اونٹ پر ایک شخص سوار دکھائی دے رہا ہے۔ تھوڑی دیر بعد سیدنا سعد کے پیچھا آ گئے جو بختی اونٹ پر سوار تھے۔ سیدنا سعد فرمانے لگے: “اے اللہ! یہ جو بری خبر لائے ہیں اس کے شر سے تیری پناہ!” سیدنا عمر رضی اللہ عنہ نے فرمایا تھا: سعد کو خلافت مل گئی تو بہتر ورنہ والی ان سے مشورہ لیتا رہے۔ میں نے انہیں کمزوری یا خیانت کی بنا پر معزول نہیں کیا تھا۔ سیدنا عمر رضی اللہ عنہ نے اکیس (۲۱ھ) میں انہیں کوفہ کا والی مقرر کیا تھا۔ جب سیدنا عثمان خلیفہ بنے تو پھر انہیں وہاں کا گورنر بنا دیا، بعد میں ولید بن عقبہ کی وجہ سے پچیس (۲۵ھ) میں معزول کر دیا۔ زبیر بن بکار کی روایت ہے کہ عامر بن سعد بحوالہ اپنے والد بیان کرتے تھے کہ غزوہ أحد میں ایک مشرک نے مسلمانوں کو تنگ کر رکھا تھا۔ میں نے تاک کر ایسا تیر مارا جو اس کی پیشانی میں پیوست ہو گیا۔ بدحواسی سے گرا تو اس کا ستر کھل گیا، تو رسول اللہ صلی اللہ علیہ وسلم ہنس پڑے۔ واقدی نے اپنی روایت میں ان کا نام حبان بن العرفہ لیا ہے اور یہ اضافہ نقل کیا ہے کہ انہوں نے تیر پھینکا تو وہ ام ایمن کے دامن میں جا اٹکا، وہ زخمیوں کو پانی پلا رہی تھیں۔ رسول اللہ صلی اللہ علیہ وسلم ہنس پڑے۔ رسول اللہ صلی اللہ علیہ وسلم نے تیر سیدنا سعد کو دیا، نمک سے تیر حبان کے حلق میں جا لگا تو وہ دھڑام سے پیچھے گر پڑا جس سے اس کی شرمگاہ کھل گئی تو رسول اللہ صلی اللہ علیہ وسلم ہنس پڑے۔ اور آپ صلی اللہ علیہ وسلم نے فرمایا: “سعد! اسے (ام ایمن کو) بچانا”۔ ابوالعباس سراج نے اپنی تاریخ میں، بحوالہ جریر روایت نقل کی ہے یہ سیدنا عمر رضی اللہ عنہ کے پاس سے گزرے آپ نے سعد بن ابی وقاص رضی اللہ عنہ کے بارے میں پوچھا: عرض کی: وہ اپنی ولایت و حکومت میں باوجود قدرت کے سب سے شریف انسان ہیں۔ سختی میں سب سے کم ہیں وہ تو ان کے لئے مہربان ماں جیسے ہیں، جو ان کے لیے ایسے جمع کرتے ہیں جیسے چیونٹی لڑائی فساد سے بہت دور رہتے اور قریش میں سے سب کے محبوب ہیں۔ زبیر کی روایت ہے سیدنا سعد عبیدہ بن حارث کے دستہ میں شامل تھے، جب رسول اللہ صلی اللہ علیہ وسلم نے انہیں رابغ کی طرف قریش کے قافلہ سے ملنے کے لیے روانہ کیا تھا تو انہوں نے ایک دوسرے پر تیر اندازی کی۔ سیدنا سعد پہلے شخص ہیں جنہوں نے اللہ کی راہ میں تیر چلایا، جس کے متعلق آپ نے اشعار کہے: “کیا رسول اللہ صلی اللہ علیہ وسلم تک یہ بات پہنچی ہے کہ میں نے اپنے ساتھیوں کی حفاظت اپنے تیروں کے پھلوں سے کی”۔ ایک روایت میں یہ اضافہ بھی ہے: “میں نے ان سے ان کے دشمن کو ہٹاتا رہا۔ کبھی یہ رسا کشی پتھریلی زمین پر پیش آتی تو کبھی ریتلی اور نرم زمین پر۔” “معد میں سے کسی تیر انداز نے مجھ سے پہلے اسلام میں تیر پھینکنے کی کوشش نہیں کی”۔ یونس بن بکیر نے اپنی زیادات میں، بحوالہ زہری اسی طرح کے اشعار نقل کیے ہیں، جن میں صرف تین اشعار ہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۳۷)\n(2) ترمذی کتاب المناقب باب مناقب سعد بن ابی وقاص (۳۷۵۲)\n(3) السیرۃ النبویۃ (۲۱۱/۱)\n(4) ترمذی، کتاب المناقب، باب مناقب سعد بن ابی وقاص (۳۷۵۱)\n(5) بخاری، کتاب الجہاد والسیر، باب الحراسۃ فی الغزو فی سبیل اللہ (۲۸۸۵) ترمذی، کتاب المناقب، باب مناقب سعد بن ابی وقاص (۳۷۵۶)"}],[3190,"§۳۱۹۶ ۔ سعد بن مالک(1)\nبن خالد بن ثعلبہ بن حارثہ بن عمرو بن خزرج بن ساعدہ انصاری ساعدی۔ سہل بن سعد کے والد۔ واقدی کی روایت ہے: سعد بن مالک نے بدر میں شرکت کی تیاری کی تو ایسے بیمار ہوئے کہ اسی میں(2) وفات ہو گئی۔ پھر بھی رسول اللہ صلی اللہ علیہ وسلم نے ان کا حصہ لگایا اور اجر بیان کیا۔ حارث نے اپنی مسند میں یہ روایت باضافہ نقل کی ہے۔ انہوں نے اپنی سواری کے کجاوے میں وصیت لکھ کر رکھ دی۔ اپنے سامان اور سواری کو نبی صلی اللہ علیہ وسلم کے لیے وقف کر گئے۔ ابونعیم کی روایت ہے کہ نبی صلی اللہ علیہ وسلم کے میرے والد کے پاس کئی گھوڑے تھے۔ (حدیث) ابونعیم نے ان کے والد کا نام سعد بتایا ہے جبکہ مشہور مالک ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۳۴) استیعاب (۹۵۸)\n(2) المستدرک (۱۹۱/۳)"}],[3191,"§۳۱۹۷ ۔ سعد بن مالک بن سنان(1)\nبن عبید بن ثعلبہ بن الابجر بن عوف بن حارث بن خزرج انصاری خزرجی ہیں یہی ابوسعید الخدری ہیں۔ کنیت سے مشہور ہیں۔ أحد میں کم سن قرار پائے، ان کے والد اسی میں شہید ہوئے جبکہ انہوں نے بعد کے معرکوں کو سر کیا۔ نبی صلی اللہ علیہ وسلم سے اکثر روایتیں نقل کی ہیں۔ اسی طرح سیدنا ابوبکر، عمر، عثمان، علی، زید بن ثابت وغیرہ صحابہ کرام رضی اللہ عنہم سے روایت کی ہے ان سے روایت کرنے والے صحابہ ابن عباس، ابن عمر، جابر، محمود بن لبید، ابوامامہ بن سہل اور ابوالطفیل رضی اللہ عنہم ہیں جبکہ اکابر تابعین میں سے ابن المسیب، ابو عثمان نہدی، طارق بن شہاب، عبید بن عمیر اور ان کے بعد عطاء، عیاض بن عبداللہ بن ابی سرح، بشر بن سعید، مجاہد، ابوالمتوکل الناجی، ابونضرہ معبد بن سیرین اور عبداللہ بن محیریز شامل ہیں۔ بکثرت احادیث نقل کرنے والے ہیں حنظلہ بن ابی سفیان بحوالہ اپنے شیوخ روایت کرتے ہیں۔ نوجوان صحابہ میں سے سب سے زیادہ فقیر تھے۔ خطیب کا قول ہے: فضیلت والے صحابہ میں سے ہیں اکثر احادیث یاد تھیں ہیثم بن کلیب نے اپنی مسند میں روایت نقل کی ہے کہ سیدنا سہیل بن سعد فرماتے ہیں: میں نے ابوذر، عبادہ بن الصامت، محمد بن مسلمہ ابوسعید اور چھٹے شخص نے نبی صلی اللہ علیہ وسلم کے ہاتھ پر اس شرط کے ساتھ بیعت کی، ہم اللہ تعالیٰ کے بارے میں کسی کی پروا نہیں کریں گے تو چھٹے شخص نے عرض کی میں بیعت واپس لینا چاہتا ہوں آپ نے فرمایا واپس ہے۔ اور بطریق یزید بن عبداللہ بن الشخیر روایت ہے حرہ کے روز سیدنا ابوسعید مدینہ سے نکل کر ایک غار میں چلے گئے ایک شامی بھی وہاں جا پہنچا آپ نے فرمایا: نکل جاؤ! اگر میرے پاس آئے تو میں تمہیں قتل کر دوں گا۔ اس نے کہا: میں نہیں نکلوں گا۔ چنانچہ جب وہ پاس آیا تو آپ نے تلوار رکھ دی اور فرمایا: لے (مجھے قتل کرنے والا) گناہ کر لے۔ وہ کہنے لگا: آپ ہی ابوسعید خدری ہیں؟ فرمایا: ہاں، کہنے لگا، تو میرے لیے استغفار کریں۔ امام(2) احمد وغیرہ کی بطریق عطیہ، بحوالہ ابوسعید رضی اللہ عنہ روایت ہے کہ میرے والد أحد میں شہید ہوئے اور ہمارے لیے کوئی مال نہ چھوڑا میں رسول اللہ صلی اللہ علیہ وسلم سے کچھ مانگنے آیا۔ آپ نے مجھے دیکھتے ہی بھانپ کر فرمایا: جو بے نیازی اختیار کرے گا اللہ تعالیٰ اسے بے نیاز کر دے گا اور جو پاکدامنی کا طالب ہو گا اللہ تعالیٰ اسے عفت نصیب فرمائے گا۔ تو میں لوٹ آیا۔ اس کی اصل صحیحین میں ہے، جس کا واقعہ اس سے مختلف ہے اس کے الفاظ ہیں: جو محتاجی سے بچنا چاہے گا اللہ تعالیٰ اس کے لیے اس کا سامان پیدا کر دے گا اور جو پاکدامنی چاہے گا اسے عفت عطا کرے گا اور جو صبر کرنا چاہے گا اللہ تعالیٰ اسے صبر کی توفیق عنایت کرے گا۔”(3) ....حدیث.... شعبہ ابوسعید رضی اللہ عنہ سے مرفوع روایت کرتے ہیں: تمہیں ہرگز لوگوں کا خوف حق گوئی سے نہ روکے، جب اسے حق نظر آ رہا ہو یا اس کا علم ہو جائے” ابوسعید فرماتے ہیں: اسی بات نے مجھے امیر معاویہ رضی اللہ عنہ کی طرف جانے پر مجبور کیا میں نے یہ بات ان کے گوش گزار کی اور پھر واپس آ گیا۔ ہند بنت سعید بن ابی سعید الخدری بحوالہ اپنے چچا روایت کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ابوسعید الخدری کی طرف واپسی پر آئے تو ہم نے بکری کی دستی ان کی خدمت میں پیش کی۔ علاء بن المسیب بواسطہ اپنے والد، بحوالہ ابوسعید روایت کرتے ہیں کہ ہم نے ان سے کہا: آپ کو رسول اللہ صلی اللہ علیہ وسلم کا دیدار اور صحابی ہونے کا شرف حاصل ہے مبارک ہو۔ فرمایا: تمہیں معلوم نہیں، ہم نے آپ کے بعد کیا نئے کام نکال لیے ہیں۔ علی بن الجعد، بحوالہ شعبہ سیدنا ابوسعید رضی اللہ عنہ کا ارشاد نقل کرتے ہیں: حدیث بیان کیا کرو کیونکہ حدیث سے حدیث کی رغبت پیدا ہوتی ہے۔ امام واقدی فرماتے ہیں: چہتر (۷۴ھ) بقول بعض چونسٹھ (۶۴ھ) میں انتقال ہوا۔ مدائنی فرماتے ہیں: تیرسٹھ (۶۳ھ) میں جبکہ عسکری کا قول ہے: پینسٹھ (۶۵ھ) میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۰۳۶) استیعاب (۹۶۹)\n(2) مسند احمد (۹/۳)\n(3) بخاری کتاب الزکاۃ باب الاستعفاف عن المسألۃ (۱۴۶۹)، مسلم (۱۲۴) ابوداؤد (۱۶۴۴) ترمذی کتاب البر والصلۃ باب ماجاء فی الصبر (۲۰۲۴)، نسائی (۲۵۸۷)"}],[3192,"§۳۱۹۸ ۔ سعد بن محمد(1)\nبن مسلمہ انصاری۔ ان کا نسب ان کے والد کے حالات میں بیان ہو گا۔ ابن شاہین کا، بحوالہ ابن ابی داؤد بیان ہے، کہ فتح مکہ اور بعد کے معرکوں میں شریک ہوئے۔ قداح نے ان کا ذکر کیا ہے کہ محمد بن مسلمہ کے دس بیٹے تھے۔","",{"fn":"(1) اسد الغابہ (۲۰۳۸)"}],[3193,"§۳۱۹۹ ۔ سعد بن محیصہ(1)\nبن مسعود بن کعب انصاری اوسی ان کے والد کے سوائح میں ان کا نسب بیان ہو گا۔ بغوی لکھتے ہیں محمد بن اسماعیل نے صحابہ میں ان کا ذکر کیا ہے، مجھے ان کی کوئی حدیث نہیں ملی۔ عبدالرزاق، بحوالہ حرام بن سعد بن محیصہ روایت کرتے ہیں وہ اپنے والد سے نقل کرتے ہیں کہ براء بن عازب کی اونٹنی کسی کے باغ میں چلی گئی اور ان کے پودے خراب کر دیے تو آپ صلی اللہ علیہ وسلم نے یہ فیصلہ صادر فرمایا، کہ “مال مویشی والوں کی ذمہ داری دن کے وقت کی ہے”۔ ....حدیث....(2) زہری سے آگے سخت اختلاف ہے ذہلی اور ابوداؤد “المفرد” میں لکھتے ہیں “عن ابیہ” کے الفاظ میں عبدالرزاق کی متابعت کسی نے نہیں کی۔ یہی روایت امام مالک اور الیاس نے بواسطہ زہری بحوالہ حرام بن سعد مرسلا نقل کی ہے۔ ابن عبدالبر “التمہید” میں لکھتے ہیں: یہ صحابی نہیں، انہیں صرف اپنے والد سے روایت حاصل ہے۔ ابن ابی شیبہ، بحوالہ حرام بن سعد وہ اپنے والد سے روایت کرتے ہیں کہ محیصہ نے نبی صلی اللہ علیہ وسلم سے سینگی لگانے والے کی کمائی کے متعلق دریافت کیا۔ ....حدیث.... ذہلی لکھتے ہیں: یہ روایت امام مالک وغیرہ کی بواسطہ زہری ابن محیصہ سے، بحوالہ ان کے والد مروی ہے اور جس نے یہ کہا ہے کہ: “حرام، بحوالہ اپنے والد نقل کرتے ہیں” یہی محفوظ ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۴۰) تجرید (۲۱۸/۱)\n(2) المعجم الکبیر (۵۴۶۹/۶) (۵۴۷۰/۶) السنن الکبریٰ (۳۴۲/۸)"}],[3194,"§۳۲۰۰ ۔ سعد بن المدحاس(1)\nبقول بعض المجباس ابن حبان(2) نے صحابہ میں ان کا ذکر کیا ہے کہ اہل شام سے ہیں۔ ابن مندہ کا قول ہے: اہل حمص میں شمار ہوتے ہیں۔ ابن السکن اور الباوردی کی روایت ہے کہ سعد بن مدحاس نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “جس(3) نے مجھ پر جھوٹ باندھا”۔ ....حدیث.... ابن حبان نے اسی سند سے، بحوالہ ان کے روایت کی ہے کہ ہم نے نبی صلی اللہ علیہ وسلم کی معیت میں جہاد کیا۔ طبرانی نے مسند شامیین میں اسی سند سے روایت کی ہے۔ ابن عائذ کا قول ہے کہ ابوامامہ نے فرمایا: کہ سعد بن مدحاس نے فرمایا: وہ صحابی بھی تھے۔ میں نے خواب میں دیکھا کہ میں ایک چشمہ میں اترا وہاں لوگ چھوٹی بڑی مشکلیں پانی سے بھر رہے ہیں میں نے کہنا: یہ کیا ہے؟ تو کسی نے کہہ دیا اس کی تعبیر قرآن ہے تو سعد نے قسم کھائی کہ میں ضرور سورۃ بقرہ اور آل عمران پڑھوں گا”۔","",{"fn":"(1) اسد الغابہ (۲۰۴۱) تجرید (۲۲۸/۱)\n(2) الثقات (۱۵۴/۳)\n(3) المعجم الکبیر، السنن الکبریٰ، سابقہ حوالہ۔"}],[3195,"§۳۲۰۱ ۔ سعد بن مسعود انصاری(1)\nایک حدیث میں ان کا ذکر آتا ہے۔ طبرانی اور ابن ابی عاصم نے، بحوالہ سیدنا ابوہریرہ رضی اللہ عنہ روایت کی ہے کہ حارث غطفانی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: محمد! (صلی اللہ علیہ وسلم) مدینہ کی کھجوروں کا نصف ہمیں دیا جائے۔ یہ واقعہ احزاب کی بات ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: مجھے سعدوں(2) سے مشورہ کر لینے دو، چنانچہ آپ نے سیدنا سعد بن معاذ، سعد بن خیثمہ، سعد بن عبادہ اور سعد بن مسعود رضی اللہ عنہم کی طرف پیغام بھیجا۔ ....حدیث.... ابن الاثیر لکھتے ہیں:(3) سعد بن خیثمہ کے تذکرہ میں تامل ہے کیونکہ وہ بدر میں شہادت پا چکے تھے۔ اور غزوہ خندق (احزاب) اس کے تین سال بعد پیش آیا۔ میں کہتا ہوں: سعد بن خیثمہ کے بارے میں غلطی سے سعد بن مسعود کے متعلق غلطی واقع ہونا ضروری نہیں۔ اگر یہ روایت ثابت ہو جائے تو وہ اس وقت کے اکابر انصار میں سے جن سے رائے لی جاتی تھی۔","",{"fn":"(1) اسد الغابہ (۲۰۴۲)\n(2) المعجم الکبیر (۵۴۰۹) مجمع الزوائد (۱۳۲/۶) اسد الغابہ (۳۱۲/۲)\n(3) ایضا"}],[3196,"§۳۲۰۲ ۔ سعد بن مسعود الکندی(1)\nبقول بغوی: انہیں شرف صحابیت حاصل ہے۔ ابن مندہ فرماتے ہیں: صحابہ میں ان کا ذکر تو آتا ہے لیکن ان کا صحابی ہونا صحیح سند سے ثابت نہیں۔ البتہ امام بخاری نے انہیں صحابہ میں شمار کیا ہے اور اپنی تاریخ(2) میں، بحوالہ قیس بن ابی حازم روایت کی ہے کہ ہم سعد بن مسعود کی عیادت کرنے گئے پھر وہ واقعہ ذکر کیا۔ ابو موسیٰ نے طبرانی کے اتباع میں یہ واقعہ سابقہ شخصیت کے حالات میں نقل کر دیا ہے جو وہم پر مبنی ہے۔ جبکہ ابن ابی حاتم(3) نے تابعین میں ان کا ذکر کیا ہے۔ اور ان کے حالات میں لکھا ہے عمر بن عبدالعزیز نے انہیں اہل مصر کی تعلیم و تربیت کے لیے بھیجا تھا جس سے معلوم ہوا کہ ان کی وفات دیر سے ہوئی ہے۔ ابن مندہ کی روایت ہے کہ سعد بن مسعود نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جس نے سخت غم کیا اس نے صبر کا دامن چھوڑ دیا”۔ پھر یہ آیت پڑھی، “میں اپنی پریشانی اور غم کی فریاد صرف اللہ سے کرتا ہوں”۔(4)(5) حکم ترمذی نے اسرار الحج میں ابن جریر نے دوسری سند سے، بحوالہ ابن انعم مرسل روایت کی ہے جس میں صحابی کا ذکر نہیں۔ اور ابن مردویہ نے ایک اور سند سے، بحوالہ ابن انعم روایت کر کے اسے مسند عبداللہ بن عمرو میں شمار کیا ہے۔ ابن انعم ضعیف راوی ہے۔ ابن المبارک کتاب الزہد میں لکھتے ہیں راشدین بن سعد بن انعم نے ہمیں، بحوالہ سعد بن مسعود بتایا کہ عثمان بن مظعون نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگے: مجھے آختہ (خصی) ہونے کی اجازت دیجئے۔ ....حدیث.... بحوالہ سعد بن مسعود روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اجنبی عورتوں سے بات چیت کرنے سے بچنا کیونکہ جو شخص بھی کسی ایسی عورت کے ساتھ تنہائی میں ہوتا ہے جہاں اس کا محرم ساتھ نہ ہو تو اس سے ملوث ہونے کا ارادہ کر لیتا ہے، ”(6) ....حدیث.... ہم نے غیلانیات میں بطریق یحییٰ بن ایوب بواسطہ عبداللہ بن زحر، بحوالہ سعد بن مسعود روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے کسی نے پوچھا: سب سے عقلمند کون سا مومن ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “جو موت کو زیادہ یاد کرے اور اس کی اچھے طریقہ سے تیاری کرے”(7)۔","",{"fn":"(1) اسد الغابہ (۲۰۴۴) استیعاب (۹۶۲) تجرید (۲۱۹/۱)\n(2) التاریخ الکبیر (۴۹/۲)\n(3) الجرح والتعدیل (۹۴/۴)\n(4) سورۃ یوسف ۸۶\n(5) تفسیر الطبری (۳۲/۱۳) تفسیر القرطبی (۲۴۷/۹) الدرالمنثور (۳۱/۴)\n(6) مختصر تاریخ دمشق (۱۱۱/۶)\n(7) جامع المسانید (۲۴۵/۵) اسد الغابہ (۸۲/۲)"}],[3197,"§۳۲۰۳ ۔ سعد بن مسعود ثقفی\nمختار بن ابی عبید کے چچا۔ امام(1) بخاری نے صحابہ میں ان کا ذکر کیا ہے۔ طبرانی کا بھی یہی قول ہے ابوخنف کا بیان ہے: سیدنا علی رضی اللہ عنہ نے ان کے سپرد کوئی ذمہ داری کی تھی۔ بعد میں صفین میں اپنے ساتھ رکھا۔ طبرانی کی روایت ہے کہ سعد بن مسعود ثقفی نے فرمایا: نوح علیہ السلام جب کپڑا پہنتے تو الحمد للہ کہتے اور جب کھاتے پیتے تو تب بھی الحمد للہ فرماتے اسی بنا پر انہیں شکر گزار بندہ کہا گیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۲۹۶/۴)"}],[3198,"§۳۲۰۴ ۔ سعد بن مسعود\nان سے سعید بن صفوان روایت کرتے ہیں۔ بقول ابن حبان:(1) صحابی ہیں ایسا ہی تجرید میں لکھا ہے۔ لیکن ابن حبان نے خود صحابہ میں ان کا تذکرہ نہیں کیا۔ صرف سعید بن صفوان کے حالات میں تابعین کے طبقہ میں اس بات کا ذکر کیا ہے میرے خیال میں یہ کندی ہیں۔ ابن ابی حاتم(2) ان کے سوائح میں لکھتے ہیں ان سے یزید بن ابی حبیب، عبدالرحمن الافریقی۔ جو ابن انعم ہی ہیں جن کا کندی کے حالات میں ذکر ہوا ہے۔ روایت کرتے ہیں۔","",{"fn":"(1) الثقات (۲۹۶/۴)\n(2) الجرح والتعدیل (۹۲/۴)"}],[3199,"§۳۲۰۵ ۔ سعد بن معاذ(1)\nبن نعمان بن امری القیس بن زید بن عبد الاشہل بن جشم بن حارث بن خزرج بن النبیت بن مالک بن الاوس انصاری اشہلی، اوس کے سردار، والدہ کا نام کبشہ بنت رافع ہے وہ بھی صحابیہ ہیں۔ کنیت ابو عمرو تھی اتفاق ہے کہ بدر میں شریک ہوئے۔ غزوہ خندق میں ان کے ایک تیر لگا جس کے بعد مہینہ بھر زندہ رہے اسی دوران بنی قریظہ کا فیصلہ کیا، اس بارے میں ان کی دعا قبول ہوئی۔ پھر یہی زخم ہرا ہو کر بہہ پڑا تو فوت ہو گئے یہ بخاری کی روایت ہے اور یہ واقعہ پانچ (۵ھ) کا ہے۔ جب ان کا جنازہ نکلا تو منافق کہنے لگے: کتنا ہلکا جنازہ ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: “فرشتوں نے ان کا جنازہ اٹھا رکھا ہے” صحیحین وغیرہ میں کئی طرق سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا تھا: “سعد بن معاذ کی موت کی وجہ سے عرش کانپ اٹھا”،(2) سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ بنی عبدالاشہل میں تین افراد ایسے ہوئے ہیں کہ ان سے افضل کوئی نہیں: سعد بن معاذ، اسید بن حضیر، عباد بن بشر۔ ابن اسحاق کا بیان ہے کہ آپ نے جب مصعب بن عمیر رضی اللہ عنہ کے ہاتھ پر اسلام قبول کیا تو بنی عبدالاشہل سے فرمانے لگے: جب تک تم لوگ مسلمان نہیں ہو لیتے تمہارے مردوں اور عورتوں سے بات کرنا میرے لیے حرام ہے۔ چنانچہ وہ سارے مسلمان ہو گئے۔ انہیں اسلام میں سب سے بڑی برکت حاصل تھی۔ ابن اسحاق(3) غزوہ خندق کے ذیل میں فرماتے ہیں: کہ سیدہ عائشہ رضی اللہ عنہا نے فرمایا: “میں بنی حارثہ کے قلعہ میں سعد بن معاذ کی والدہ کے ساتھ بیٹھی تھی کہ وہاں سے سعد بن معاذ کا گزر ہوا وہ یہ اشعار پڑھ رہے تھے: ع “ذرا ٹھہر کر لڑائی کا غبار مل جائے وہ موت کتنی اچھی ہے جس کا وقت قریب آ گیا ہو”۔(4) تو ان کی والدہ نے فرمایا: بیٹا! جلدی ملو تم تو پیچھے رہ گئے۔ میں کہنے لگی: ام سعد! کاش ان کی زرہ ذرا لمبی ہوتی۔ تو انہیں وہیں تیر لگا جہاں کا سیدہ عائشہ رضی اللہ عنہا کو خدشہ تھا جس نے ان کے تیر مارا وہ کہنے لگا: لو! میں ابن العرقہ ہوں۔ آپ نے فرمایا: اللہ دوزخ میں تیرا چہرہ آلو د کرے۔ ابن العرقہ کا نام حبان بن عبد مناف تھا جو بنی عامر بن لؤی سے تعلق رکھتا تھا۔ العرقہ اس کی والدہ کا نام تھا۔ بقول بعض ابوامامہ جشمی نے ان کے تیر مارا تھا۔ امام بخاری(5) کی روایت ہے کہ جب بنی قریظہ سیدنا سعد کے فیصلے پر قلعہ سے باہر آ گئے تو آپ ایک گدھے پر سوار ہو کر تشریف لائے اس وقت نبی صلی اللہ علیہ وسلم نے فرمایا: (قبیلہ اوس) اپنے سردار کی طرف بڑھو (کیونکہ آپ اس وقت بیمار تھے) ابن اسحاق(6) نے بغیر سند فرمایا ہے کہ جب سیدنا سعد بن معاذ رضی اللہ عنہ کا انتقال ہوا تو ان کی والدہ نے یہ اشعار کہے۔ “ام سعد کا غم سعد کے کھو جانے پر جو باہمت اور حوصلے والا تھا۔ اور ایسا سردار تھا کہ اب اس کا قائم مقام کوئی نہیں”۔ جس پر نبی صلی اللہ علیہ وسلم نے فرمایا: “رونے والیاں اکثر جھوٹ بولتی ہیں لیکن یہ سچ کہتی ہے”۔(7) یہی روایت طبرانی نے ضعیف سند سے بحوالہ ابن عباس رضی اللہ عنہما نقل کی ہے کہ ام سعد کہنے لگیں، پھر یہ اشعار جو اوپر گزرے ہیں بیان کیے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: اس سے زیادہ کچھ نہ کہنا، اللہ کی قسم وہ واقعی دور اندیش اور اللہ کے دین میں مضبوط تھا”۔","",{"fn":"(1) اسد الغابہ (۲۰۴۵) استیعاب (۲۹۶۳)\n(2) بخاری کتاب مناقب الانصار باب مناقب سعد بن معاذ (۳۸۰۳) مسلم کتاب فضائل الصحابہ باب من فضائل سعد بن معاذ (۲۶۹۶) ابن ماجہ (۱۵۸) مسند احمد (۳۱۶/۲) المعجم الکبیر (۵۳۳۵/۶)\n(3) السیرۃ النبویۃ (۱۷۹/۳)\n(4) اشعار اسد الغابہ (۳۱۴/۲) السیرۃ النبویۃ اور الروض للسہیلی (۱۹۲/۲) میں ہیں\n(5) بخاری کتاب الاستئذان باب قول النبی صلی اللہ علیہ وسلم: قوموا الی سیدکم (حدیث ۶۲۶۲)\n(6) السیرۃ النبویۃ (۱۹۸/۲)\n(7) المعجم الکبیر (۵۳۶۹/۶)"}],[3200,"§۳۲۰۶ ۔ سعد بن معاذ الانصاری (دوسرے)(1)\nبغوی نے صحابہ میں ان کا ذکر کیا ہے لکھتے ہیں: میں نے محمد بن اسماعیل کی کتاب میں ان کا نام دیکھا ہے لیکن ان کی حدیث ذکر نہیں کی۔ میں کہتا ہوں: شبیب بن قرہ کے حالات میں ان کا ذکر ہے۔ خطیب نے المتفق میں ایک کمزور ترین سند سے اور ابو موسیٰ نے ذیل میں مجہول سند سے، بواسطہ حسن، بحوالہ انس رضی اللہ عنہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم جب تبوک سے واپس آئے تو سعد بن معاذ انصاری نے آپ کا استقبال کیا تو آپ نے ہاتھ ملانے سے پوچھا کہ تمہارے ہاتھ میں یہ سختی کا کیا اثر ہے؟ عرض کی: یہ پھاڑی کے نشان ہیں میں یہ چلا کر اپنے گھر والوں کے لیے کمائی کرتا ہوں تو نبی صلی اللہ علیہ وسلم نے ان کے ہاتھ پر بوسہ دے کر فرمایا: یہ ایسا ہاتھ ہے جسے آگ نہیں چھوئے گی۔”(2) ابو موسیٰ کی روایت میں یہ نام سعد بن الانصاری لکھا ہے۔","",{"fn":"(1) المعجم الکبیر (۵۳۲۸/۶)\n(2) المنتظم (۲۵۱/۲)"}],[3201,"§۳۲۰۷ ۔ سعد بن معاذ یا معاذ بن سعد\nبخاری میں شک کے ساتھ ہی منقول ہے تحریر کر لیا جائے۔"],[3202,"§۳۲۰۸ ۔ سعد بن المنذر الانصاری(1)\nامام بخاری(2) نے ان کا ذکر کیا ہے کہ ابن لہیعہ نے ان کی حدیث روایت کی ہے لیکن صحیح نہیں۔ میں کہتا ہوں: ابن المبارک نے اسے “الزہد” میں ابن لہیعہ سے، بحوالہ سعد بن المنذر انصاری نقل کیا ہے کہ انہوں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! کیا میں تین راتوں میں ایک کلام پاک ختم کر لیا کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ٹھیک ہے اگر تم ایسا کر سکتے ہو”۔(3) چنانچہ وہ وفات تک اسی طرح پڑھا کرتے تھے۔ یہی روایت حسن بن سفیان، اور بغوی نے، بطریق ابن لہیعہ، بحوالہ ابن حبان نقل کی ہے۔ ابن مندہ کا گمان ہے کہ یہی سعد بن المنذر بن عمیر بن عدی بن خرشہ ہیں جو بیعت عقبہ، اور بدر و أحد میں شریک ہوئے۔ ابونعیم نے ان کا تعاقب کرتے ہوئے لکھا ہے کہ ابن اسحاق اور زہری نے انہیں بدری صحابہ میں اور نہ اہل عقبہ میں ذکر کیا ہے۔ بات یہی ہے۔ ابن مندہ کے کلام میں ان کی نسبت کے بارے میں تامل ہے اس واسطے کہ عدی بن خرشہ صحابی ہیں لیکن میں نے نہیں دیکھا کہ کسی نے منذر کو صحابہ میں ذکر کیا ہو۔ لہذا یہ بات قلبند کر لی جائے۔","",{"fn":"(1) اسد الغابہ (۲۰۴۶) استیعاب (۹۶۴)\n(2) التاریخ الکبیر (۶۵/۲)\n(3) المعجم الکبیر (۵۴۸۱/۶) الزہد لابن المبارک (۱۲۷۴) مجمع الزوائد (۱۷۱/۷)"}],[3203,"§۳۲۰۹ ۔ سعد بن المنذر الساعدی(1)\nابوحمید کے والد۔ ابن ابوحاتم(2) نے ان کا ذکر کیا اور ابوعمر(3) کا قول ہے: مجھے خدشہ ہے یہ پہلے والے نہ ہوں۔ میں کہتا ہوں: ان کے نسب میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۴۷) استیعاب (۹۶۵)\n(2) الجرح والتعدیل (۹۳/۴)\n(3) استیعاب (۱۷۰/۲)"}],[3204,"§۳۲۱۰ ۔ سعد بن النعمان(1)\nبن زید بن اکال بن لوذان بن حارث بن امیہ بن زید بن مالک بن عوف بن عمرو بن عوف انصاری اوسی۔ بقول ابن اسحاق(2) کہ مجھ سے عبداللہ بن ابی بکر نے بیان کیا کہ: عمرو بن سفیان بدر کے روز گرفتار ہو گیا تو کسی نے ابوسفیان سے کہا: کیا آپ ان کا فدیہ نہیں دے دیتے؟ انہوں نے حنظلہ کو قتل کیا ہے اور میں عمرو کا فدیہ دوں؟ میرا مال اور خون یکجا نہیں ہو سکتے۔ فرماتے ہیں: اسی اثناء میں سعد بن نعمان بن زید بن اکال عمرہ کے لیے روانہ ہوئے تو ابوسفیان نے ان پر حملہ کر کے انہیں گرفتار کر لیا۔ اور یہ کلام کیا بمع “اے ابن اکال کے قبیلے! اس کی بات کا جواب دو! تم نے کھو دیا دھیر عمر سردار حوالے نہ کرو کیونکہ بنی عمرو بن عوف اس وقت تک ذلیل رہیں گے جب تک تم اپنے قیدی سے بیڑیاں نہیں کھول دیتے۔”(3) چنانچہ یہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس عمرو بن ابی سفیان کا فدیہ سعد کی صورت میں لے کر گئے آپ نے عمرو ان کے حوالے کر دیا۔ جس کے متعلق حسان رضی اللہ عنہ فرماتے ہیں: ع “اگر مکہ کے روز سعد آزاد ہوتے تو قید ہونے سے پہلے تمہارے بہت زیادہ قتل کرتے”۔ بقول ابوعمر:(4) ابن کلبی نے یہی واقعہ سعد کے والد نعمان کے بارے میں ذکر کیا ہے۔ میں کہتا ہوں: سیدنا حسان رضی اللہ عنہ کے اشعار سے ابن اسحاق کے قول کی تائید ہوتی ہے۔ واللہ تعالیٰ اعلم","",{"fn":"(1) اسد الغابہ (۲۰۴۸) استیعاب (۹۶۶)\n(2) السیرۃ النبویۃ (۲۲۱/۲)\n(3) السیرۃ النبویۃ، اسد الغابہ (۳۱۸/۲)\n(4) استیعاب (۱۷۰/۲)"}],[3205,"§۳۲۱۱ ۔ سعد بن النعمان(1)\nبن قیس بن عمرو بن زید بن امیہ الظفری۔ ابن لہیعہ نے، بواسطہ ابوالاسود، بحوالہ عروہ ان کا تذکرہ شرکاء بدر میں کیا ہے۔ جبکہ ابن اسحاق اور موسیٰ بن عقبہ نے ان کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۲۰۴۹)"}],[3206,"§۳۲۱۲ ۔ سعد بن ہلال\nطبری نے صحابہ میں ان کا ذکر کیا ہے۔ لیکن ان کی کوئی روایت نقل نہیں کی۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[3207,"§۳۲۱۳ ۔ سعد بن وائل(1)\nبن عمرو العبدی۔ الجذامی۔ بقول ابن مندہ: اہل رملہ میں شمار ہوتے ہیں۔ پھر یہ اور باوردی بطریق عبداللہ بن کثیر بن سعد بواسطہ ابومعاویہ حکم بن ابی سفیان العبدی روایت کرتے ہیں کہ میں نے سعد بن وائل کو فرماتے سنا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “جو شخص لا الہ الا اللہ اور محمد رسول اللہ کی گواہی دیتا ہے وہ جنت کا مستحق ہے”۔(2)","",{"fn":"(1) اسد الغابہ (۲۰۵۲) تجرید (۲۱۹/۱)\n(2) جامع المسانید (۲۵۱/۵) اسد الغابہ (۸۸/۳)"}],[3208,"§۳۲۱۴ ۔ سعد بن ابی وقاص\nیہی سعد بن مالک ہیں تذکرہ ہو چکا ہے۔"],[3209,"§۳۲۱۵ ۔ سعد بن وہب الجہنی\nرشدان کے حالات میں تذکرہ ہوا ہے۔"],[3210,"§۳۲۱۶ ۔ سعد بن وہب النضیری(1)\nثعلبی نے اپنی تفسیر میں لکھا ہے کہ ان کے اور سفیان بن عمیر بن وہب کے علاوہ بنی نضیر میں سے کوئی مسلمان نہیں ہوا۔ ایسا ہی ابو موسیٰ نے بلا اسناد ذکر کیا ہے ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۵۴)"}],[3211,"§۳۲۱۷ ۔ سعد بن یزید بن الفاکہ\nاسعد میں تذکرہ ہو چکا ہے۔"],[3212,"§۳۲۱۸ ۔ سعد الاسود السلمی ثم الذکوانی\nابن عدی، ابن حبان اور المخلص نے اپنے فوائد کی دوسری جلد میں سب نے، بحوالہ انس رضی اللہ عنہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم کے پاس ایک شخص آ کر عرض کرنے لگا: اللہ کے رسول صلی اللہ علیہ وسلم! کیا میں اپنے سیاہ رنگ اور بدصورتی کی وجہ سے جنت میں نہیں جا سکوں گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ایسی بات نہیں”۔ ....حدیث.... اسی میں ہے کہ میں بنی سلیم میں سے پھر ذکوان میں سے مشہور نسب اور حسب والا ہوں صرف مجھ پر سیاہ رنگت کا غلبہ ہے جو میرے ماموں کی رنگت ہے۔ اور اسی میں ہے۔ آپ نے بنت عمر یا عمرو بن وہب ثقفی سے ان کا نکاح کر دیا پھر جلیبیب اور محمد بن عمر کے واقعہ سے ملتا جلتا ایک قصہ ذکر کیا۔ الحاکم کا بیان ہے انہوں نے یہ موضوع حدیث نقل کی ہے۔"],[3213,"§۳۲۱۹ ۔ سعد الاسلمی\nسعد الحرجی کے بیان میں ان کا ذکر ہونا ہے۔"],[3214,"§۳۲۲۰ ۔ سعد الاحمسی\nان کے مولا ہیں۔ بغوی بطریق ابو محمد۔ بواسطہ اسماعیل بن ابو خالد، بحوالہ سعد جوان کے مولا ہیں روایت کی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سجدہ کرتے دیکھا۔"],[3215,"§۳۲۲۱ ۔ سعد مولا ابی بکر الصدیق(1)\nبقول بعض: سعید لیکن پہلا نام زیادہ مشہور اور صحیح ہے۔ یہ ابن عبد البر(2) کا قول تھا۔ ابن ماجہ نے ان کی حدیث روایت کی ہے جس کی طرف ترمذی نے اشارہ کیا ہے جو بروایت حسن بصری ان سے مروی ہے کہ وہ نبی صلی اللہ علیہ وسلم کی خدمت کرتے تھے پھر کھجور ملا کر کھانے کی حدیث روایت کی۔ اس میں فرماتے ہیں: سعد مولا رسول اللہ صلی اللہ علیہ وسلم سے مروی ہے۔ جس سے ابن فتحون کو یہ گمان ہو گیا یہ رسول اللہ صلی اللہ علیہ وسلم کے وہ مولا ہیں جن کا ذکر ہو گا۔ جبکہ ایسا نہیں۔ انہیں تو بس خادم رسول ہونے کی وجہ سے آپ کا مولا کہا گیا ہے جبکہ آنے والی شخصیت کے نام میں اختلاف ہے جیسا کہ بیان ہو گا۔","",{"fn":"(1) اسد الغابہ (۱۹۷۱) استیعاب (۹۷۵)\n(2) استیعاب (۱۷۵/۲)"}],[3216,"§۳۲۲۲ ۔ سعد الانصاری\nسعد بن عبادہ میں ان کا بیان ہوا ہے۔"],[3217,"§۳۲۲۳ ۔ سعد الانصاری\nسعد بن عمارہ میں تذکرہ ہوا ہے۔"],[3218,"§۳۲۲۴ ۔ سعد مولا اوس بن حجر\nعسکری نے ان کا ذکر کیا ہے مشہور یہ ہے جن کا انہوں نے ذکر کیا وہ ان کے علاوہ مسعود ہیں تذکرہ ابھی ہوتا ہے۔"],[3219,"§۳۲۲۵ ۔ سعد مولا ثابت بن قیس الانصاری\nصدیق اکبر رضی اللہ عنہ نے ان کے آقا کی وصیت پوری کرنے کے لیے انہیں آزاد کر دیا تھا اچانک سیدنا بلال رضی اللہ عنہ نے انہیں خواب میں دیکھا۔ واقدی نے “الردہ” میں اپنی سند سے یہ بات نقل کی ہے۔"],[3220,"§۳۲۲۶ ۔ سعد الجہنی(1)\nبقول ابو عمر: ان کی روایت کردہ حدیث میں کلام ہے جو بروایت سنان بن سعد الجہنی بحوالہ ان کے والد مروی ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: “امام لوگوں کو چھوڑ کر خصوصی اپنے لیے دعا نہ کرے”۔","",{"fn":"(1) اسد الغابہ (۱۹۷۵)"}],[3221,"§۳۲۲۷ ۔ سعد مولا حاطب بن ابی بلتعہ\nسعد بن خولی میں ذکر ہو چکا ہے۔"],[3222,"§۳۲۲۸ ۔ سعد مولا حاطب (دوسرے)\nأحد کے بعد تک زندہ رہے اسماعیل بن ابی خالد بحوالہ سعد مولا حاطب روایت کرتے ہیں کہ میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! کیا حاطب جہنمی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: بدر اور بیعت رضوان میں شریک کوئی مسلمان بھی ہرگز جہنم میں نہیں جائے گا۔(1) بغوی لکھتے ہیں: مجھے نہیں لگتا کہ ابن ابی خالد نے ان کا زمانہ پایا ہے۔ میں کہتا ہوں: جس نے انہیں پہلے شخص سے ملا دیا اسے وہم ہوا ہے اس واسطے کہ بیعت رضوان أحد کے مدت بعد ہوئی جبکہ پہلی شخصیت أحد میں شہید ہو چکی تھی جیسا کہ پہلے بیان ہو چکا ہے صحیح مسلم میں حدیث جابر سے مروی ہے کہ حاطب کا غلام آ کر کہنے لگا: اللہ کے رسول صلی اللہ علیہ وسلم! پھر حدیث ابن ابی خالد کا مفہوم ذکر کیا اور ان کا نام نہیں لیا۔","",{"fn":"(1) کنز العمال (۳۳۸۹۹)"}],[3223,"§۳۲۲۹ ۔ سعد الخیر\nسعد بن قیس میں تذکرہ ہوا ہے۔"],[3224,"§۳۲۳۰ ۔ سعد الدوسی(1)\nباوردی کی بطریق ابو قلابہ بحوالہ سیدنا انس رضی اللہ عنہ روایت ہے کہ ایک دیہاتی نے قیامت کے متعلق سوال کیا، اتنے میں ازدشوہ کا ایک شخص وہاں سے گزرا جس کا نام سعد تھا، تو نبی کریم صلی اللہ علیہ وسلم نے اسے دیکھ کر فرمایا: اسے اگر اتنی لمبی عمر ملی کہ اسے اپنی عمر فنا کرنے کا موقع مل گیا تو تم میں سے ایک آدمی بھی زندہ نہیں رہے گی،(2) یہی روایت ابن مندہ نے دوسری سند سے، بواسطہ قیس بن وہب۔ بحوالہ سیدنا انس رضی اللہ عنہ نقل کی ہے کہ سعد دوسی کا گزر ہوا اور یہی حدیث جب قرہ بن خالد نے، بواسطہ حسن، بحوالہ سیدنا انس رضی اللہ عنہ روایت کی تو اس میں یہ اضافہ نقل کیا: تو آپ نے دوس کے ایک جوان کے بارے فرمایا جس کا نام سعد تھا اور قتادہ نے، بحوالہ سیدنا انس رضی اللہ عنہ روایت کی تو اس میں فرمایا: مغیرہ بن شعبہ کا ایک غلام گزرا جو میرا ہم عمر تھا”، محمد نامی حضرات کے حالات میں اس سے ملتا جلتا واقعہ بیان ہو گا بظاہر لگتا ہے دو واقعات ہیں۔","",{"fn":"(1) اسد الغابہ (۱۹۸۸) استیعاب (۹۷۲)\n(2) مسلم کتاب الفتن باب قرب الساعۃ (۷۳۳۷)"}],[3225,"§۳۲۳۱ ۔ سعد مولا رسول اللہ صلی اللہ علیہ وسلم(1)\nامام احمد(2) فرماتے ہیں: ہم سے جعفر بن عثمان بن عتاب نے بیان کیا کہ میں ابوعثمان نہدی کے ساتھ تھا تو لوگوں میں سے ایک شخص بولا: ہمیں سعد یا عبید مولا رسول اللہ صلی اللہ علیہ وسلم نے روایت سنائی کہ انہیں روزہ رکھنے کا حکم ہوا اتنے میں ایک شخص آ کر عرض کرنے لگا: اللہ کے رسول صلی اللہ علیہ وسلم! فلاں فلاں عورتوں کی حالت غیر ہو رہی ہے....حدیث.... حسن بن سفیان بطریق یحییٰ قطان، بحوالہ عثمان بن عتاب روایت کرتے ہیں کہ ابو عثمان کے حلقہ محفل میں ہم سے ایک شخص، بحوالہ سعد مولا رسول اللہ صلی اللہ علیہ وسلم حدیث بیان کرنے لگا پھر اسے طویل انداز میں روایت کیا۔ یہی حدیث بروایت سلیمان اتمی، بواسطہ ابوعثمان، بحوالہ عبید مولا رسول اللہ صلی اللہ علیہ وسلم بیان ہو گی۔ واللہ تعالیٰ اعلم","",{"fn":"(1) اسد الغابہ (۱۹۹۵) استیعاب (۹۷۶)\n(2) مسند احمد (۴۳۱/۵)"}],[3226,"§۳۲۳۲ ۔ سعد والد زید (بے نسبت)(1)\nابن ابی عاصم کی زید بن سعد سے، بحوالہ ان کے والد روایت ہے کہ نبی صلی اللہ علیہ وسلم کو جب اپنی وفات کی اطلاع ملی تو آپ پرانے کپڑے اوڑھ کر منبر پر تشریف فرما ہوئے۔ ارشاد فرمایا: “لوگو! میری انصار کے اس قبیلہ کے بارے میں وصیت یاد رکھنا”۔(2) حدیث۔ ابن مندہ نے یہ روایت سابقہ شخصیت سعد بن زید الانصاری کے سوانح میں لکھی ہے۔ جبکہ ابوحاتم(3) اور ابن عبد البر(4) نے دونوں میں فرق کیا ہے۔ یہی مناسب ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۰۲) استیعاب (۹۴۲)\n(2) المعجم الکبیر (۵۴۲۵/۶) مجمع الزوائد (۳۶/۱۰) جامع المسانید (۹۵/۵)\n(3) الجرح والتعدیل (۹۷/۴)\n(4) استیعاب (۹۷۳)"}],[3227,"§۳۲۳۳ ۔ سعد ظفری(1)\nابوحاتم(2) نے صحابہ میں ان کا ذکر کیا ہے اور طبرانی(3) نے بطریق عبد الرحمن بن حرملہ، بحوالہ سعد ظفری روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے داغنے (لوہا گرم کر کے زخم وغیرہ کا علاج کرنے) سے منع کیا ہے۔ ابو موسیٰ کو تردد ہے کہ آیا یہ سعد بن نعمان ظفری ہی ہیں یا کوئی اور ہیں؟","",{"fn":"(1) اسد الغابہ (۲۰۱۰) استیعاب (۱۵۹/۲) تجرید (۲۱۵/۱)\n(2) الجرح والتعدیل (۹۷/۴)\n(3) المعجم الکبیر (۵۴۸۰/۶)"}],[3228,"§۳۲۳۴ ۔ سعد مولا عتبہ بن غزوان(1)\nعبد الغنی بن سعید ثقفی نے اپنی تفسیر میں، بحوالہ ابن عباس رضی اللہ عنہما روایت کی ہے کہ مذکورہ آیت “اور ان لوگوں کو اپنے پاس سے نہ ہٹانا جو صبح و شام اپنے رب کو پکارتے ہیں”۔(2) ان کے بارے میں اور سعد مولا حاطب، حاطب اور عتبہ کے بارے میں نازل ہوئی۔ ابوعمر(3) کا گمان ہے: یہ اپنے مولا کے ساتھ بدر میں شریک ہوئے۔ جبکہ ابن اسحاق نے بدریین میں صرف خباب مولا عتبہ بن غزوان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۱۸) استیعاب (۹۷۷)\n(2) سورۃ الانعام: ۵۲\n(3) استیعاب (۱۷۶/۲)"}],[3229,"§۳۲۳۵ ۔ سعد العرجی(1)\nان سے روایت ہے کہ میں عرج سے مدینہ تک نبی صلی اللہ علیہ وسلم کی رہنمائی کر رہا تھا۔ میں نے دیکھا کہ آپ صلی اللہ علیہ وسلم نے ٹیک کا سہارا لے کر کوئی چیز کھائی تھی۔(2) زیادات المسند میں ہے۔ میں ابراہیم بن عبداللہ بن ابی ربیعہ کے ساتھ نکلا، ابن سعد کی طرف پیام بھیجا تو وہ ہمارے پاس عرج میں آ گئے۔ ابن سعد(3) لکھتے ہیں: مجھ سے میرے والد نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم ان کے ہاں تشریف لائے۔ آپ کے ساتھ سیدنا ابو بکر صدیق رضی اللہ عنہ تھے۔ سیدنا ابو بکر رضی اللہ عنہ کے گھرانے کی کوئی بچی ہمارے ہاں دودھ پلوائی پر آئی ہوئی تھی۔ رسول اللہ صلی اللہ علیہ وسلم کا ارادہ تھا کہ مختصر (شارٹ کٹ) رستہ مل جائے تو سعد نے انہیں سواری کا رستہ بتایا پھر آپ صلی اللہ علیہ وسلم کی قبا تشریف آوری اور سعد بن خیثمہ کے ہاں فروش کی حدیث ذکر کی۔ اسی میں ہے کہ آپ کے پاس سے دو شخص گزرے۔ آپ نے پوچھا تم دونوں کا کیا نام ہے؟ انہوں نے کہا: ہم دونوں کثیر شخص ہیں آپ نے فرمایا: نہیں بلکہ تم دونوں عزت مند انسان ہو۔ ابو عمر کو اس بارے میں خطب ہو گیا چنانچہ ملاحظہ ہو لکھتے ہیں: سعد العرجی بنی العرج بن حارث بن کعب بن ھوازن سے تعلق رکھتے ہیں۔ بقول بعض یہ سلمین کے مولا ہیں۔ انہیں عرجی صرف اس وجہ سے کہا جاتا ہے کہ عرج میں نبی صلی اللہ علیہ وسلم سے ان کی ملاقات ہوئی تھی۔ آپ مدینہ کا ارادہ رکھتے تھے یہ وہاں اسلام لے آئے، پھر لکھتے ہیں: سعد اسلمی سے ان کا بیٹا عبداللہ روایت کرتا ہے کہ وہ نبی صلی اللہ علیہ وسلم کے پاس سعد بن خیثمہ کے ہاں ٹھہرے۔ یوں انہوں نے ایک شخصیت کے دو افراد بنا دیے۔","",{"fn":"(1) استیعاب (۲۰۲۰) استیعاب (۹۷۴)\n(2) الطبقات (۴۳/۴) جامع المسانید (۲۵۹....۵)\n(3) استیعاب (۱۷۵/۲)"}],[3230,"§۳۲۳۶ ۔ سعد مولا عمرو بن العاص(1)\nیوسف بن موسیٰ وغیرہ نے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ فرماتے ہیں: ان کا صحابی ہونا صحیح نہیں۔ حسن بن سفیان، بحوالہ سعد مولا عمرو بن العاص روایت کرتے ہیں کہ دو آدمیوں کا ایک آیت کے بارے میں بحث و مباحثہ ہو گیا جس کا حل نبی صلی اللہ علیہ وسلم سے پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: قرآن مجید (کی آیات) میں نہ جھگڑنا کیونکہ جو اس میں جھگڑتا ہے وہ کفر تک پہنچ جاتا ہے”،(2) ابن حبان(3) نے ثقات التابعین میں لکھا ہے: یہ مرسل حدیث ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۲۷)\n(2) المعجم الکبیر (۴۹۱۶/۵) مجمع الزوائد (۱۵۷/۱) جامع المسانید (۲۵۷/۵)\n(3) الثقات (۳۰۰/۴)"}],[3231,"§۳۲۳۷ ۔ سعد مولا قدامہ بن مظعون(1)\nابن عبد البر(2) نے ان کا ذکر کیا ہے کہ: ان کے صحابی ہونے کے بارے میں تامل ہے۔ انہیں خوارج نے اکتالیس (۴۱ھ) میں شہید کیا تھا۔","",{"fn":"(1) اسد الغابہ (۲۰۳۰) استیعاب (۹۷۸)\n(2) استیعاب (۱۷۶/۲)"}],[3232,"§۳۲۳۸ ۔ سعد الکندی\nسنان کے والد، ان سے ان کا بیٹا روایت کرتا ہے یہ بات ابن یونس نے تاریخ مصر میں نقل کی ہے۔"],[3233,"§۳۲۳۹ ۔ سعد ابو الحارث\nابن حبان “الصحابہ” میں لکھتے ہیں: ان کی کنیت: ابو المطرف تھی اور یہ صحابی ہیں۔"],[3234,"§۳۲۴۰ ۔ سعد (بے نسبت)\nبقول ابن مندہ ان سے ان کا بیٹا عبداللہ روایت کرتا ہے ان کے حالات نا معلوم، میں کہتا ہوں: ہو سکتا ہے یہ عرجی ہوں۔"],[3235,"§۳۲۴۱ ۔ سعد (بے نسبت)\nبغوی کی بواسطہ زیاد بن جبیر، بحوالہ سعد روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے خواتین سے بیعت لی تو ایک دراز قد عورت کھڑی ہوئی لگتا تھا وہ مضر کی ہے کہنے لگی: اللہ کے رسول صلی اللہ علیہ وسلم! خاوندوں کی کون سی چیز ہمارے لئے حلال ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: تازہ کھجور جو تم عورتیں کھا بھی سکتی ہو اور اڑوس پڑوس میں ہدیہ بھی بھیج سکتی ہو۔(1) میں کہتا ہوں: یہی روایت بزار، عبد بن حمید اور یحییٰ بن عبد الحمید حیانی نے مسند سعد بن ابی وقاص میں نقل کی ہے۔ بغوی اور ابن مندہ نے ان کا الگ ذکر کیا ہے یہی راجح ہے۔ کیونکہ دار قطنی نے علل میں اس کا اختلاف ظاہر کیا ہے کہ سعد ایک انصاری شخص ہیں، جس نے انہیں سعد بن ابی وقاص لکھا اسے وہم ہوا ہے۔ میں کہتا ہوں: اس کی تائید اس سے بھی ہوتی ہے کہ یہ اور ہیں کہ ابن مندہ بطریق حماد بن سلمہ بواسطہ یونس بن عبید، بحوالہ زیاد بن جبیر روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سعد نامی ایک شخص زکوۃ وصولی کے لیے بھیجا، تو اگر وہ ابن ابی وقاص ہوتے تو راوی انہیں اس نام سے تعبیر نہ کرتے۔","",{"fn":"(1) ابوداؤد کتاب الزکاۃ باب: المرأۃ تتصدق من مال زوجھا (۱۶۸۶) جامع المسانید (۱۳۱/۵)"}],[3236,"§۳۲۴۲ ۔ سعد(1)\nمحمد انصاری کے والد۔ ابو نعیم نے ان کا ذکر کیا ہے کہ ایک شخص نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کوئی مختصر نصیحت کریں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جو کچھ لوگوں کے پاس ہے اس سے نا امید ہو جاؤ”۔(2) (حدیث) ابن الاثیر(3) کا قول ہے: یہ حدیث سعد بن عمارہ کے حالات میں بیان ہو چکی ہے۔ ابو موسیٰ سے منقول ہے: یہ اسماعیل وہی ابن محمد بن سعد بن ابی وقاص ہیں۔ میں کہتا ہوں: اگر بات یہی ہے جو اس ابو موسیٰ نے لکھی ہے تو جس نے انہیں انصاری لکھا ہے اس سے غلطی ہوئی ہے۔ رہی ابن الاثیر کی بات کہ یہ حدیث سعد بن عمارہ کے حالات میں بیان ہو چکی ہے تو یہ دوسری سند سے ہے دونوں حدیثوں کا مضمون مختلف ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۳۹)\n(2) کنز العمال (۴۴۱۵۶) کشف الخفاء (۳۲۵/۱)\n(3) اسد الغابہ (۳۱۱/۲)"}],[3237,"§۳۲۴۳ ۔ سعد (بے نسبت)\nامام بخاری(1) نے انہیں علیحدہ ذکر کیا ہے اور بطریق حفص بن المضاء شلمی بواسطہ عامر بن خارجہ بن سعد انہوں نے، بحوالہ اپنے دادا سعد روایت کی ہے کہ کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے قحط باراں کی شکایت کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “گھٹنوں کے بل بیٹھ کر رب رب کہو”،(2) کسی اور نے یہ روایت مسند سعد بن ابی وقاص میں لکھی ہے۔ واللہ اعلم","",{"fn":"(1) اتاریخ الکبیر (۵۵/۲)\n(2) مجمع الزوائد (۲۱۴/۲)"}],[3238,"§۳۲۴۴ ۔ سعدی(1)\nابن شاہین نے ان کا ذکر کیا ہے اور، بحوالہ ابن سعد نقل کیا ہے کہ ان کی، بحوالہ نبی صلی اللہ علیہ وسلم صدقہ کے اونٹوں کے متعلق ایک روایت ہے۔ مجھے اس کے قلب مبد کرنے کی فرصت نہ ملی۔ میرے خیال میں یہ نام نسب کے لفظ سے ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۹۷)"}],[3239,"§۳۲۴۵ ۔ سَعر دُئلی(1)\nبقول دار قطنی اور ابن حبان:(2) انہیں شرف صحابیت حاصل ہے۔ عسکری نے مخضرمین میں ان کا ذکر کیا ہے۔ ان کے والد کے نام میں اختلاف ہے سوادہ، دسم، مختلف اقوال ہیں۔ بقول بعض: عامری ہیں۔ ایک قول ہے: جاہلیت میں شام تجارت کی غرض سے آئے تھے۔ یعقوب بن شیبہ نے بطریق عبداللہ الحمرانی روایت کی ہے میں سعربن سوادہ کی اولاد کے چند لوگوں کے ساتھ بیٹھا کرتا تھا وہ مجھے سناتے کہ انہوں نے فرمایا: میں کسی عرب سردار کا نوکر تھا ایک دفعہ میں شام گیا وہاں سے مکہ پہنچا وہاں میں نے ایک شخص دیکھا جس کا رنگ کھلا ہوا ہے اس کے سامنے اونٹ نحر (ذبح) کیے جا رہے تھے پھر ایک کہنے والا کہہ رہا تھا: اللہ کے وفد! آؤ کھانے کے لئے۔ فرماتے ہیں: ہمیں شام میں بتایا گیا کہ حجاز میں ایک نبی مبعوث ہو گا۔ اب اس کا ظہور ہو چکا ہے چنانچہ میں اس کے پاس آیا میں نے کہا: السلام علیک یا نبی اللہ! وہ کہنے لگا: بس، وہ آنے ہی والا ہے”، میں نے ایک شخص سے پوچھا: یہ صاحب کون ہیں؟ اس نے کہا: ابو نضلہ ہاشم بن عبد مناف”، میں نے کہا اللہ کی قسم! یہی بزرگی و عزت ہے نہ کہ بنی حنیفہ کی شان و عزت۔ خطیب نے “مختلف” میں، بواسطہ ابوعثوارہ خثاجی، بحوالہ سعد بن سوادہ عامری نقل کیا کہ میں ایک جگہ نوکر تھا پھر اسی سے ملتا جلتا طویل واقعہ ذکر کیا۔ اسی میں ہے: میں نے دیکھا کہ زمین کے بلند مقام پر کھڑا ایک شخص اعلان کر رہا ہے۔ اللہ کے وفد! دوپہر کا کھانا تیار ہے اور دوسرا راستے کی چورنگی میں کھڑا اعلان کر رہا ہے: جو کھانا کھا لے وہ شام کے لیے آرام کر لے، پھر ہے انہوں نے اس سے کہا: السلام علیک یا نبی اللہ”، اس نے کہا: میں وہ نہیں ہوں، اس کا زمانہ قریب ہے تم ضرور اس کی خوشخبری سنو گے”، میرا غالب گمان یہ ہے کہ اس واقعہ والے عامری جو ہاشم بن عبد مناف نبی صلی اللہ علیہ وسلم کے پردادا کے ساتھ ہے اس دئلی کے علاوہ ہیں جن کی روایت ابوداؤد اور نسائی نے نقل کی ہے کہ نبی صلی اللہ علیہ وسلم کے زکوۃ وصول کنندگان ان کے پاس زکوۃ لینے آئے۔ اس لیے کہ عامری کے واقعہ سے یہ تقاضا ہوتا ہے کہ اسے بہت لمبی عمر ملی ہو وجہ یہ ہے ہاشم کا دور زکوۃ وصول کرنے والوں کی روانگی سے کافی دور ہے اور نبی صلی اللہ علیہ وسلم کی بعثت کے بارے میں اطلاعات بہت زیادہ تھیں اور بعید ہے کہ آپ اس وقت مبعوث ہوئے ہوں۔ اس کا ذکر بھی حجاز کی سرزمین میں ہو پھر اس کے متعلق میں(۲۰) سال بعد ہی شدید ہو سکتی ہے۔ ابوعثوارہ کی ایک روایت میں، بحوالہ ان کے مذکور ہے جس سے پتہ چلتا ہے کہ وہ نبی صلی اللہ علیہ وسلم کے بعد بھی زندہ رہے اس واسطے کہ ابوعثوارہ تابعی ہیں اور اس عامری کو صحابہ میں شمار کرنا دئلی کے مقابلہ میں زیادہ قریب ہے۔ واللہ اعلم۔ ابوداؤد اور نسائی نے بطریق مسلم بن ثفنہ، بحوالہ ان کے روایت کی ہے کہ ان کے پاس نبی صلی اللہ علیہ وسلم کے ہاں سے دو شخص زکوۃ کی وصولی کے لیے آئے۔(3) ....حدیث.... سنن ابی داؤد کی روایت سے معلوم ہوتا ہے کہ وہ خلافت معاویہ رضی اللہ عنہ تک زندہ رہے۔ اور ابو عمر(4) کے ہاں لکھا ہے: یہ سحر بن شعبہ بن کنانہ ہیں۔ ابن الاثیر کا قول ہے: اس میں کئی اوہام ہیں۔ کیونکہ شعبہ تو مسلم کے والد ہیں جو ان سے روایت کرتے ہیں۔ بقول بعض انہیں شفنہ بھی کہا جاتا ہے، زر ہے کنانہ تو وہ شعبہ کے والد نہیں۔ اور درست نام کنانہ ہی ہے اس میں لفظی غلطی ہوئی ہے۔","",{"fn":"(1) ایضا (۲۰۵۸) استیعاب (۱۱۳۸)\n(2) الثقات (۱۸۲/۲)\n(3) ابوداؤد کتاب الزکاۃ باب زکاۃ السائمۃ (۱۵۸۱) (۱۰۸۲) نسائی کتاب الزکاۃ باب اعطاء السید المال بغیر اختیار المصدق (۲۴۶۲)\n(4) استیعاب (۲۴۲/۲)"}],[3240,"§۳۲۴۶ ۔ سَعفنہ\nبروزن حمزہ بقول بعض: سعید ابن عریض بن عاویہ التیماوی، حجاز اور شام کے درمیان تیما نامی جگہ کی طرف نسبت ہے سوال بن عادیا یہودی کے بھتیجے ہیں اور جاہلیت میں قلعہ تیماء کے مالک، جن کی وفا کے بارے میں مثال دی جاتی ہے۔ مخضرمین میں ان کا ذکر ہوتا ہے۔ قسم ثالث میں ان کا ذکر ہو گا۔ لیکن مجھے “رجال السبعۃ الامامیۃ” میں ابن ابی طی کے قلم سے لکھی ایک روایت مل گئی ہے جس کا تقاضا ہے کہ یہ صحابی ہیں۔ ابو جعفر المخاری جو امامیہ کے ایک امام ہیں ان کی سند سے منقول ہے۔ ان میں سے اکثر ان سات میں سے جو ابن لہیعہ تک سند نقل کرتے ہیں کہ ابن زبیر رضی اللہ عنہ سے مروی ہے کہ امیر معاویہ رضی اللہ عنہ حج کرنے آئے مسجد میں داخل ہوئے تو وہاں بزرگ شخص تھا جس کی دومینڈھیاں تھیں وہ باقی بزرگوں میں سے اچھی چال ڈھال اور صاف ستھرے کپڑوں والے تھے امیر معاویہ رضی اللہ عنہ نے ان کے متعلق پوچھا، تو کسی نے بتایا: یہ ابن عریض ہیں۔ آپ نے ان کی طرف پیام بھیجا تو وہ آ گئے۔ آپ نے پوچھا: تمہاری زمین تیماء کا کیا ہوا؟ انہوں نے بتایا: باقی ہے، فرمایا: میرے ہاتھ فتح دو، کہا ٹھیک ہے مجھے اگر ضرورت نہ ہوتی تو میں اسے نہ بیچتا، اور پھر ان سے ان کے بیٹے کا اپنا کہا ہوا مرثیہ کہنے کی درخواست کی تو انہوں نے سنا دیا، درمیان میں سیدنا علی رضی اللہ عنہ کے بارے میں بھی گفتگو ہوئی۔ ابن عریض نے امیر معاویہ کا مرتبہ گھٹایا تو امیر معاویہ یہ کہنے لگے: لگتا ہے ان کا ذہنی توازن ٹھیک نہیں انہیں درست کر دو وہ کہنے لگے: میں کوئی باؤلا نہیں ہوا، لیکن میں تمہیں اللہ کا واسطہ دے کر کہتا ہوں معاویہ آپ کو یاد ہو گا جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے اتنے میں علی رضی اللہ عنہ آئے آپ صلی اللہ علیہ وسلم نے ان کا استقبال کرتے ہوئے فرمایا: جو تم نے لڑے اللہ اسے ہلاک کرے اور جو تم سے دشمنی رکھے اللہ اسے اپنی عداوت سے مارے”، سیدنا معاویہ رضی اللہ عنہ نے ان کی بات کاٹتے ہوئے دوسری بات شروع کر دی۔ میں کہتا ہوں: اس واقعہ کی اصل عمر بن شبہ نے اپنی سند سے جو ہیشم بن عدی تک ہے نقل کی ہے جس میں ابن عریض کا یہ قول نہیں کہ آپ کو اللہ کا واسطہ دیتا ہوں، لگتا ہے کسی راوی کا اختلاف ہے۔ مرز بانی نے مجمع الشعراء میں ان کا ذکر کیا ہے اور لفظ سعید میں اختلاف نقل کیا ہے آیا نون سے ہے یا یاء سے اور امالی ثعلب میں ان کے اشعار نقل کیے ہیں کہ جو شعر اس میں شراب کی تعریف میں ہے وہ ابن عریض کا ہے۔ ع جب شراب پرانی تھی تو قریش کو اس سے نفرت تھی اور جب انہوں نے سیدنا عثمان کے قتل کو جائز سمجھ کر انہیں شہید کر دیا تو شراب حلال ہو گئی۔"],[3241,"§۳۲۴۷ ۔ سعید بن بُجَیر الجہنی(1)\nابن الکن اور ابن مندہ کی بطریق ابی ذکوان عمران رفلی فرمایا: میں نے عطیہ بن سلیم بن سعید جو بنی جشم کے ایک فرد ہیں سے سنا کہ میں نے اپنے والد کو فرماتے سنا: میں اپنے والد کے ہمراہ نبی صلی اللہ علیہ وسلم کے پاس آیا آپ نے فرمایا: تمہارا کیا نام ہے؟ میں نے کہا: فلاں۔ آپ نے فرمایا: نہیں تم سلیم ہو”۔(2)","",{"fn":"(1) اسد الغابہ (۲۰۶۰)\n(2) جامع المسانید (۲۶۱/۵)"}],[3242,"§۳۲۴۸ ۔ سعید بن ثجیر(1)\nابن فتحون نے انہیں المشتری قلب مبد کیا ہے۔ ابن الکن بطریق جنادہ بن مروان، بحوالہ ابن الحکم بن الشقری وہ اپنے والد سے روایت کرتے ہیں کہ ان کے دادا سعید بن ثجیر نبی صلی اللہ علیہ وسلم کے پاس آئے اور اسلام قبول کر لیا۔ راستے میں بنی عامر ملے اور ان سے کہنے لگے: تم بے دین ہو گئے ہو؟ تو میرے دادا نے یہ اشعار کہے: ع بنی عامر بلا وجہ ہم سے بگڑتے ہیں کہ ہم مسلمان ہو گئے ہیں۔ ابن الکن کا قول ہے مجھے ان کا ذکر صرف اس واقعہ میں ملا ہے۔","",{"fn":"(1) استیعاب (۹۷۹)"}],[3243,"§۳۲۴۹ ۔ سعید بن البختری(1)\nبقول ابن مندہ: ابن خزیمہ نے صحابہ میں ان کا ذکر کیا ہے لیکن صحیح نہیں، پھر بحوالہ سعید بن البختری روایت کی ہے کہ وہ اپنے ایک غلام کو مار رہے تھے تو وہ ان سے اللہ کی پناہ مانگنے لگا اتنے میں رسول اللہ صلی اللہ علیہ وسلم کا وہاں سے گزر ہوا تو پھر اس نے اللہ کی پناہ مانگی تو انہوں نے اسے چھوڑ دیا آپ نے ان سے فرمایا: اللہ تعالیٰ پناہ مانگنے والے کی زیادہ حفاظت کرنے والا ہے”، وہ کہنے لگے: میں آپ کو گواہ بناتا ہوں کہ یہ آزاد ہے آپ نے فرمایا: اگر تم ایسا نہ کرتے تو آگ کی لپٹ(2) کا سینک تمہارے چہرے پر لگ جاتا”۔(3) میں کہتا ہوں: لگتا ہے اس میں تحریف ہوئی ہے اصل میں یوں تھا سعید ابو البختری سے مروی ہے جو مشہور تابعی ہیں یہ روایت بھی انہوں نے مرسل نقل کی ہے اس کا سبب یہ بنتا کہ مجھے یہ معلوم نہیں کہ کبیر طائی کی کسی صحابی سے ملاقات ہوئی ہو”، یہ متن تو ابو مسعود انصاری رضی اللہ عنہ کے حوالہ سے مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۶۱) تجرید (۲۲۰/۱)\n(2) جھلسنا\n(3) جامع المسانید (۲۶۲/۵) اسد الغابہ (۳۲۱/۲) الدر المنثور (۱۶۱/۲)"}],[3244,"§۳۲۵۰ ۔ سعید بن ثابت\nبن الجذع انصاری۔ طبری کا بیان ہے یہ طائف کے محاصرہ میں شہید ہوئے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[3245,"§۳۲۵۱ ۔ سعید بن حارث\nبن عبد المطلب بن ہاشم ہاشمی اگر ثابت ہو جائے تو نبی صلی اللہ علیہ وسلم کے چچا زاد بھائی ہیں۔ المستدرک(1) میں حاکم کی روایت ہے یہ شام آئے تو لوگوں نے ان سے پوچھا: آپ اور معاذ میں کیا رشتہ داری ہے؟ فرماتے ہیں: میرے چچا زاد ہیں۔ لوگوں نے کہا: انہوں نے ہم سے بیان کیا ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: جس کی اس حال میں اللہ کے حضور حاضری ہوئی کہ وہ اللہ تعالیٰ کے ساتھ کسی کو شریک نہیں کرتا تو وہ جنت میں داخل ہو گا”، موسیٰ بن جبیر کہتے ہیں میں نے یہ روایت سلیمان الاغر سے بیان کی تو انہوں نے فرمایا: میں گواہی دیتا ہوں کہ سعید بن حارث بن عبد المطلب نے مجھے یہی الفاظ سنائے ہیں۔ میں کہتا ہوں: اسناد میں ابن لہیعہ ہیں جو ضعیف ہیں۔ مجھے کتب انساب میں ان سعید کا ذکر نہیں ملا، دار قطنی کتاب الاخوۃ میں جہاں ان کا ذکر کرتے ہیں وہاں یہ حدیث بھی ذکر کی ہے اور ایک دوسری حدیث بھی روایت کی ہے لیکن وہ موقوف ہے لیکن اس میں ان کا نسب ان کے دادا نفیل تک سعید بن نفیل لکھا ہے۔","",{"fn":"(1) المستدرک (۲۴۷/۳)"}],[3246,"§۳۲۵۲ ۔ سعید بن حارث(1)\nبن قیس بن عدی بن سعید بن سعد بن سہم بن عمر و قرشی سہمی، موسیٰ بن عقبہ اور ابن اسحاق نے مہاجرین حبشہ میں ان کا ذکر کیا ہے۔ موسیٰ بن عقبہ فرماتے ہیں: اجنادین میں شہید ہوئے۔ ابن اسحاق(2) نے اور ابوالاسود نے، بحوالہ عروہ نقل کیا ہے کہ یرموک میں شہید ہوئے ایسا ہی زبیر، سیف اور ابن سعد نے لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۶۳) استیعاب (۹۸۱)\n(2) السیرۃ النبویۃ (۷/۴)"}],[3247,"§۳۲۵۳ ۔ سعید بن حاطب(1)\nبن حارث بن معمر بن حبیب بن وہب بن حذافہ بن جمح قرشی جمحی، محمد بن حاطب کے بھائی۔ امام بخاری(2) نے صحابہ میں ان کا ذکر کیا ہے اور ابن حبان(3) لکھتے ہیں جس کا گمان ہے یہ صحابی ہیں اسے وہم ہوا ہے۔ میں کہتا ہوں: بعید نہیں کہ ان کی روایت ہو۔ چنانچہ صالح بن حی نے بواسطہ اپنے والد، بحوالہ ان کے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم باہر نکلتے منبر پر تشریف فرما ہوتے پھر مؤذن اذان دیتا جو نبی وہ فارغ ہوتا آپ کھڑے ہو کر خطبہ دیتے۔","",{"fn":"(1) اسد الغابہ (۲۰۶۲)\n(2) التاریخ الکبیر (۴۶۴/۱)\n(3) الثقات (۲۷۷/۴)"}],[3248,"§۳۲۵۴ ۔ سعید بن حریث(1)\nبن عمرو بن عثمان بن عبداللہ بن عمر بن مخزوم مخزومی ان لوگوں میں سے ہیں جو فتح مکہ سے پہلے مسلمان ہوئے۔ واقدی کا بیان ہے فتح مکہ میں شریک ہوئے اور اپنے بھائی عمرو بن حریث سے زیادہ عمر والے تھے۔ ابن ماجہ(2) اور ابن ابی عاصم(3) کی بطریق عبد الملک بن عمیر، بواسطہ عمرو بن حریث، بحوالہ سعید بن حریث روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے کوئی جائیداد یا حویلی بیچ کر پھر اسی جیسی چیز میں وہ قیمت نہیں لگائی تو اس میں اسے برکت نہیں ہو گی”، سعد بن ذؤیب کے حالات میں ان کا تذکرہ ہو گا۔ بقول ابن مندہ کوفہ میں فوت ہوئے۔ بقول بعض اور یہ ابو عمر(4) کا قول ہے۔ کربلاء میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۰۶۵) استیعاب (۹۸۲) تجرید (۲۲۱/۱)\n(2) ابن ماجہ کتاب الزھون باب من باع عقار او لم. یجعل ثمنہ من مثلہ (۲۴۹۰)\n(3) الاحاد والمثانی (۷۱۰)\n(4) استیعاب (۱۷۷/۲)"}],[3249,"§۳۲۵۵ ۔ سعید بن خالد(1)\nبن سعید بن عاص بن امیہ۔ عسکری نے صحابہ میں ان کا ذکر کیا ہے۔ موسیٰ بن عقبہ کا بیان ہے یہ حبشہ میں پیدا ہوئے جب ان کے والد نے وہاں ہجرت کی تھی۔ اور مرج الصفر میں شہید ہوئے۔ بقول ابن ابی حاتم(2) بحوالہ اپنے والد روایت کی ہے کہ وہ دونوں کشتیوں کے سواروں میں سے تھے۔ ابن سعد کا قول ہے کہ یہ ام خالد کے سگے بھائی ہیں۔ دونوں کی والدہ حمینہ ہیں بقول بعض: امینہ بنت خلف بن اسعد الخزاعیہ، سیف نے مرج الصفر میں ان کے شہید ہونے کا لمبا واقعہ ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۶۸) استیعاب (۹۸۴)\n(2) الجرح والتعدیل (۱۶/۴)"}],[3250,"§۳۲۵۶ ۔ سعید بن ابی راشد(1)\nبقول بعض: تجمی، ابن حبان(2) کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ حسن بن سفیان، ابن ابی داؤد، ابن شاہین، اور ابن عدی نے الکامل میں بطریق یونس بن حبان، بواسطہ عبد الرحمن بن سابط، بحوالہ سعید بن ابی راشد روایت کیا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: کہ میری امت میں رضاء، بگڑاؤ، اور پھراؤ ہو گا”،(3) اس کی اسناد میں ضعف ہے۔ سعید بن ابی راشد، عبداللہ بن عثمان بن جشم کے شیخ ہیں ان سے، بحوالہ قیصر کے قاصد ایک حدیث روایت کرتے ہیں میرے خیال میں یہ ان کے علاوہ ہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۶۹) استیعاب (۶۸۵)\n(2) الثقات (۲۹۰/۴)\n(3) المعجم الکبیر (۵۵۳۷/۶) مجمع الزوائد (۱۱/۸) جامع المسانید (۲۶۷/۵)"}],[3251,"§۳۲۵۷ ۔ سعید بن حَیوہ(1)\nبقول بعض: حیدہ پہلے پر ابن ابی حاتم(2) و عسکری وغیرہ نے اعتماد کیا ہے۔ ابن مندہ، دلائل میں بیہقی نے ایک جماعت نے بطریق داؤد بن ابی ہند، کندیر بن سعید سے، بحوالہ اپنے والد روایت کی ہے۔ میں نے جاہلیت میں حج کیا تو مجھے طواف کرتے ایک شخص نظر آیا جو کہہ رہا تھا: “اے میرے رب! میرے سوار محمد (صلی اللہ علیہ وسلم) کو میری طرف واپس لوٹا دے۔ اور مجھ پر ایک احسان اور کر دے”،(3) میں نے کہا: یہ کون ہے؟ لوگوں نے کہا: عبد المطلب بن ہاشم ہیں۔ انہوں نے اپنے بیٹے (یعنی پوتے) کو اونٹ کی تلاش میں بھیجا ہے۔ وہ انہیں جس کام کے لیے بھیجتے ہیں اس میں کامیاب ہوتے ہیں۔ تو اتنے میں وہ آ گئے اور انھیں اپنے ساتھ چمنا لیا۔ میں کہتا ہوں: میں نے کسی حدیث کے طریق میں ان کے حوالہ سے یہ بات نہیں دیکھی کہ انہوں نے بعثت کے بعد نبی صلی اللہ علیہ وسلم سے ملاقات کی ہو۔ واللہ اعلم۔ اسی طرح کے مفہوم کا واقعہ حیدہ قشیری کے حوالہ سے پہلے بیان ہو چکا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۶۷)\n(2) الجرح والتعدیل (۱۱/۴)\n(3) اشعار استیعاب میں ہیں (۲۵۱/۲) اسد الغابہ (۳۲۳/۲) جامع المسانید (۲۶۵/۵)"}],[3252,"§۳۲۵۸ ۔ سعید بن الربیع(1)\nبن عدی بن مالک اون از بنی جحجبی۔ موسیٰ بن عقبہ نے شہداء یمامہ میں ان کا ذکر کیا ہے ایسا ہی ابوالاسود نے، بحوالہ عروہ ان کا ذکر کیا ہے اور ابن مندہ نے سعد نامی لوگوں میں ان کا ذکر کیا ہے اور ابو نعیم نے ان کا تعاقب کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۷۰)"}],[3253,"§۳۲۵۹ ۔ سعید بن ربیعہ الثقفی(1)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق ابراہیم بن مختار، بحوالہ سعید بن ربیعہ روایت کی ہے کہ ثقیف کا وفد رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا۔ آپ نے مسجد میں ان کے لیے خیمہ لگوایا تو یہ لوگ نصف (۱۵ ویں) رمضان میں مسلمان ہو گئے۔ اور ان سے فرمایا: کہ وہ آئندہ روزے رکھیں اور جو رہ گئے ان روزوں کی قضاء کریں۔(2) یہی روایت ابراہیم بن سعد نے ابن اسحاق سے، بحوالہ ابن عیسیٰ روایت کی ہے فرمایا: عطیہ بن سفیان بن ربیعہ ثقفی، بحوالہ ان کے وفد کے کسی آدمی سے روایت کرتے ہیں یہی محفوظ ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۷۱)\n(2) جامع المسانید (۲۶۸/۵) اسد الغابہ (۳۲۴/۲)"}],[3254,"§۳۲۶۰ ۔ سعید بن قیس(1)\nبن ثابت بن ثمر بن صبرہ بن مرہ بن کبیر بن غنم بن دودان بن اسد بن خزیمہ۔ ابن اسحاق(2) نے مہاجرین مدینہ میں ان کا ذکر کیا ہے ابن مندہ کی کتاب میں لکھا ہے: یہ انصاری ہیں۔ جوان کا وہم ہے۔ ابو نعیم نے ان کا تعاقب کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۷۲) استیعاب (۹۸۶)\n(2) السیرۃ النبویۃ (۸۹/۲)"}],[3255,"§۳۲۶۱ ۔ سعید بن زید بن سعد اشہلی\nسعد بن اشہلی سعد میں تذکرہ ہوا ہے۔"],[3256,"§۳۲۶۲ ۔ سعید بن زید(1)\nعمرو بن نفیل بن عبد العزیٰ العدوی عشرہ مبشرہ میں سے ایک جنہیں جنت کی خوشخبری ملی۔ والدہ کا نام فاطمہ بنت بعبجہ بن ملیح خزاعیہ۔ جو اسلام کی طرف سبقت کرنے والی ہیں۔ نبی صلی اللہ علیہ وسلم کی دار ارقم میں تشریف آوری سے پہلے مسلمان ہوئے۔ پھر ہجرت کی اور أحد اور بعد کے معرکوں میں شریک ہوئے۔ بدر کے دور میں مدینہ میں نہیں تھے۔ اسی بنا پر وہ اس میں شریک نہ ہو سکے۔ صحابہ میں سے ان سے روایت کرنے والے ابن عمر، عمرو بن حریث، ابو الطفیل ہیں جبکہ تابعین میں سے ابو عثمان نہدی، ابن المسیب اور قیس بن ابی حازم وغیرہ ہیں۔ عروہ اور ابن اسحاق(2) وغیرہ مغازی میں بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بدر میں ان کا حصہ لگایا۔ کیونکہ وہ شام میں غائب تھے اور بہت پہلے اسلام لا چکے تھے۔ اور سیدنا عمر رضی اللہ عنہ کا اسلام لانا انہی کے گھر میں ہوا۔ کیونکہ آپ سیدنا عمر رضی اللہ عنہ کے بہنوئی تھے۔ امام بخاری(3) نے بطریق قیس بن ابی حازم، بحوالہ سعید بن زید روایت کی ہے فرمایا: مجھے یاد ہے کہ عمر میرے اسلام لانے کی وجہ سے مجھے زنجیروں میں جکڑ دیتے۔ اصحاب فضیلت والوں میں سے تھے۔ ارویٰ بنت انیس کے ساتھ ان کا واقعہ مشہور ہے آپ نے اس کے لیے بد دعا کی تھی۔ سعید بن زید جنگ یرموک اور فتح دمشق میں شریک ہوئے۔ سعید بن حبیب کا قول ہے: نبی صلی اللہ علیہ وسلم کے ساتھ سیدنا ابو بکر، عمر، عثمان، علی، سعد، سعید، طلحہ، زبیر اور عبد الرحمن بن عوف کا مقام ایک تھا۔ یہ سب حضرات جنگ میں آپ کے آگے ہوتے اور نماز میں آپ کے پیچھے ہوتے اسے بخاری(4) و مسلم وغیرہ نے نقل کیا ہے۔ اس واقعہ میں ہے کہ اس بارے میں آپ کی دعا قبول ہوئی۔ ابو نعیم نے “حلیۃ الاولیاء” میں ان کے حالات میں بطریق ابو بکر بن حزم روایت کی ہے کہ سعید بن زید نے دعا کی: اے اللہ! اس کا گمان ہے کہ اس پر ظلم ہوا ہے اگر یہ جھوٹی ہے تو اسے اندھا کر دے۔ اور اسی کے کنویں میں اسے ڈال دے اور میرے حق میں مسلمانوں کے درمیان ایک نور پیدا فرما کہ میں نے اس پر ظلم نہیں کیا ہے۔ فرماتے ہیں: کہ اسی دوران وادی عقیق میں ایسا سیلاب آیا کہ اس جیسا پہلے نہیں آیا، اس وقت وہ حد جس میں ان کا اختلاف تھا وہ کھل گئی۔ سعید بن زید رضی اللہ عنہ اسی جگہ تھے اور وہ بچے تھے۔ تھوڑی دیر کے بعد وہ اندھی ہو گئی۔ اسی دوران جب وہ اپنی زمین میں گھوم رہی تھی کہ اپنے کنویں میں گر گئی۔ فرماتے ہیں: ہم لڑکے تھے ایک شخص کو کہتے سنا جو جھگڑتے ہوئے دوسرے سے کہہ رہا تھا، اللہ تعالیٰ تجھے ایسا اندھا کرے جیسے ارویٰ کو اندھا کیا ہے۔ ہم سمجھ رہے تھے وہ اسے دھمکی دے رہا تھا جبکہ اس کی مراد سعید بن زید کی ارویٰ سے متعلق بد دعا ہے۔ امام واقدی کا قول ہے: عقیق میں فوت ہوئے وہاں سے ان کا جنازہ مدینہ کی طرف لایا گیا یہ پچاس(۵۰) ہجری کا واقعہ ہے۔ بقول بعض اکاون (۵۱ھ) یا باون (۵۲ھ) کا ہے اور ستر سے اوپر زندہ رہے۔ دراز قد، گندمی رنگ اور سیاہ بالوں والے تھے۔ ہشام بن عدی کا قول ہے کوفہ میں فوت ہوئے اور مغیرہ بن شعبہ نے آپ کا جنازہ پڑھایا اور ستر(۷۳) برس زندہ رہے۔","",{"fn":"(1) اسد الغابہ (۲۰۷۵) استیعاب (۹۸۷)\n(2) السیرۃ النبویۃ (۲۴۶/۲)\n(3) بخاری کتاب بدء الخلق باب ماجاء فی سبع ارضین (۳۱۹۸)\n(4) ایضا مسلم کتاب المساقاۃ باب تحریم الظلم و غصب الارض وغیرھا (۴۱۰) مسند احمد (۲۹۵/۶)"}],[3257,"§۳۲۶۳ ۔ سعید بن سعد(1)\nبن عبادہ الانصاری خزرجی ان کا نسب، ان کے والد کے حالات میں بیان ہو چکا ہے جمہور نے انہیں صحابہ میں ذکر کیا ہے۔ ابن عبد البر(2) فرماتے ہیں: ان کا صحابی ہونا صحیح ہے۔ البتہ ابن حبان(3) کا ان کے بارے اختلاف ہے۔ چنانچہ انہوں نے صحابہ اور ثقات التابعین میں ان کا ذکر کیا ہے۔ ابن سعد(4) لکھتے ہیں: ثقہ ہیں اور حدیث کم روایت کرتے ہیں۔ امام واقدی کا قول ہے: سیدنا علی رضی اللہ عنہ کی جانب سے یمن کے والی تھے۔ ان کی حدیث نسائی اور ابن ماجہ(5) میں بروایت ابو امامہ بن سہل، بحوالہ ان کے مروی ہے اسی طرح ان سے ان کا بیٹا شرحبیل بن سعد روایت کرتا ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۶۲)\n(2) استیعاب (۹۸۰)\n(3) الثقات (۲۷۷/۴)\n(4) الطبقات (۵۸/۵)\n(5) ابن ماجہ کتاب الحدود باب حد السکران (۲۵۶۹) المعجم الکبیر (۷۷/۶) کنز العمال (۱۲۹۵۸)"}],[3258,"§۳۲۶۴ ۔ سعید بن سعید(1)\nبن العاص بن امیہ۔ ابان خالد اور عمرو کے بھائی جو ابو احیحہ کے بیٹے ہیں۔ سب کے سب اسلام لائے۔ ابن اسحاق نے صرف انہی کا ذکر طائف کے شہداء میں کیا ہے۔ جبکہ ابن شاہین، بحوالہ اپنے شیوخ روایت کرتے ہیں: کہ فتح مکہ سے پہلے مسلمان ہوئے نبی صلی اللہ علیہ وسلم نے مدینہ کے بازار کا انھیں نگران مقرر کیا تھا۔","",{"fn":"(1) اسد الغابہ (۲۰۷۷) استیعاب (۹۸۹) تجرید (۲۲۲/۱)"}],[3259,"§۳۲۶۵ ۔ سعید بن سفیان الدُّعلی(1)\nبقول بعض: الرعینی۔ ابن شاہین نے صحابہ میں ان کا ذکر کیا ہے اور بطریق مدائنی بواسطہ ابو معشر، بحوالہ یزید بن رومان روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے سعید بن ابی سفیان الرعلی کو قطعہ ارض عطا کیا اور اس کے بارے میں انہیں تحریر لکھوادی۔ وہ تحریر خالد بن سعید نے قلم بند کی تھی۔","",{"fn":"(1) اسد الغابہ (۲۰۷۸)"}],[3260,"§۳۲۶۶ ۔ سعید بن سوید(1)\nبن قیس بن عامر بن عباد بن الابجر یہی خدرہ انصاری خدری ہیں جو سمرہ بن جندب کے ماں شریک بھائی ہیں۔ ابن اسحاق نے شہداء أحد میں ان کا ذکر کیا ہے۔ اوزاعی، ثابت بن عمیر سے بواسطہ ربیعہ، عبد الملک بن سعید بن سوید سے وہ اپنے والد سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم سے کسی نے لقطہ کے متعلق سوال کیا۔ مشہور یہ ہے کہ ربیعہ کی روایت یزید مولا منبعث سے بواسطہ زید بن خالد الجہنی مروی ہے۔(2) اگر یہ روایت محفوظ ہے تو عبد الملک صحابی ہیں یا انہیں دیدار نبوی صلی اللہ علیہ وسلم نصیب ہوا ہے۔ اگر چہ اپنے والد سے مرسل روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۷۹) استیعاب (۹۹۱) تجرید (۲۲۲/۱)\n(2) بخاری کتاب العلم باب الغضب فی الموعظۃ (۹۱) ایضا کتاب المساقاۃ باب شر الناس (۲۳۷۲) (۲۴۲۷) مسلم کتاب اللقطہ باب معرفۃ الفصاص والوکاء (۴۴۷۳) (۴۴۷۴) (۴۴۷۵) ابوداؤد (۱۷۰۱) ابن ماجہ کتاب الاحکام باب اللقطہ (۲۵۰۶) مسند احمد (۱۱۶/۴)"}],[3261,"§۳۲۶۷ ۔ سعید بن سہیل\nسعد نامی حضرات میں تذکرہ ہوا ہے۔"],[3262,"§۳۲۶۸ ۔ سعید بن شراحیل(1)\nبن قیس بن حارث بن سفیان بن فاتک بن معاویہ الکندی، ابن کلبی کا بیان ہے نبی صلی اللہ علیہ وسلم کے پاس اپنے بھتیجے معروف بن قیس بن شراحیل کے ساتھ آئے۔ بعد میں معروف(2) بہجیر کے روز (نعوذ باللہ من ذلک) مرتد ہو گیا اور اسی میں قتل ہوا۔ ابن سعد نے اعتماد سے لکھا ہے کہ قتل ہونے والا شخص مذکورہ سعید تھے۔ واللہ اعلم۔ میں نے ثمہرہ کے ایک معتبر نسخہ میں دیکھا ہے، شراحیل کی جگہ شرحبیل لکھا ہے یہی زیادہ درست ہے شبیب خارجی جس نے حجاج کے خلاف بغاوت کی تھی اس کے واقعہ میں ہے کہ عثمان بن سعید بن شرحبیل بن عمرو کا لقب جزل تھا وہ اسی واقعہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۰۸۱)\n(2) اسد الغابہ (۳۲۸/۲)"}],[3263,"§۳۲۶۹ ۔ سعید بن العاص(1)\nبن سعید بن عاص بن امیہ قرشی الاموی۔ ابو عثمان سعید بن سعید جن کا ابھی ہی تذکرہ ہوا ہے ان کے بھتیجے۔ والدہ کا نام ام کلثوم بنت عبد اللہ بن ابی قیس بن عمرو عامری۔ یہ عاص کا سعید کے علاوہ کوئی بیٹا نہ تھا۔ ابن ابی حاتم(2) نے بحوالہ اپنے والد روایت کی ہے کہ انہیں شرف صحابیت حاصل ہے۔ میں کہتا ہوں: نبی صلی اللہ علیہ وسلم کے وصال کے دن یہ نو سال کے تھے۔ ان کا والد بدر میں قتل ہوا۔ سیدنا علی رضی اللہ عنہ نے اسے قتل کیا تھا۔ بقول بعض: سیدنا عمر رضی اللہ عنہ نے سعید بن عاص سے کہا: میں نے تمہارے والد کو نہیں قتل کیا بلکہ ماموں عاص بن ہشام کو قتل کیا ہے تو وہ کہنے لگے: اگر آپ نے اسے قتل کیا ہے تو آپ حق پر تھے اور وہ باطل پر تو سیدنا عمر رضی اللہ عنہ کو ان کی بات اچھی لگی۔ وہ قریش کے فصیح شخص تھے اسی بنا پر سیدنا عثمان رضی اللہ عنہ نے انہیں کتابت قرآن کے لیے منتخب لوگوں میں شامل کیا تھا۔ ابن ابی داؤد کا مصاحف میں قول ہے کہ قرآن کی عربیت کا مدار سعید بن عاص کی زبان پر تھا کیونکہ ان کا لب ولہجہ رسول اللہ صلی اللہ علیہ وسلم کے مشابہ تھا۔ وہ کوفہ کے والی بنے اور طبرستان کی جنگ جس میں فتح مند ہوئے اسی طرح غزوہ جرجان(3) کیا۔ سیدنا حذیفہ رضی اللہ عنہ اور دیگر اکابر صحابہ کے لشکر میں تھے۔ امیر معاویہ کی جانب سے مدینہ کے والی مقرر ہوئے۔ بروایت ایوب بن موسیٰ بن عمرو بن سعید بن عاص، بحوالہ ان کے والد ان کے دادا سے مروی ہے کہ ان کی ایک حدیث ہے اگر ضمیر موسیٰ کی جانب لوٹے، ان کی دوسری حدیث ان کے دادا کے حالات میں ہے جو قسم اخیر میں بیان ہو گی۔ زہری کی بطریق عبد العزیز بن ابان روایت ہے کہ ایک عورت نبی صلی اللہ علیہ وسلم کے پاس ایک چادر لے کر آئی اور کہنے لگی: میں یہ چادر سب سے شریف وعزت مند عرب کو دینا چاہتی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس(4) لڑکے کو دے دو۔ جو آپ کے پاس کھڑا تھا، یعنی سعید۔ زبیر فرماتے ہیں: سعدی کپڑے ان کی جانب منسوب کیے جاتے ہیں۔ مسلم اور نسائی نے ان کی روایت سے بحوالہ عثمان اور عائشہ رضی اللہ عنہما حدیث نقل کی ہے۔ ہیثم بن کلیب نے اپنی مسند میں لکھا ہے میں نے (یعنی سعید نے) سیدنا عمر رضی اللہ عنہ کو فرماتے سنا پھر ان کی ایک حدیث نقل کی۔ طبرانی کی جبیر بن مطعم سے مروی ایک روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ سعید بن عاص کی عیادت کرنے آئے تو آپ ایک کپڑے سے ان کی ٹکور کر رہے تھے۔ ایک احتمال یہ ہے کہ یہاں سعید سے مراد صاحب عنوان ہی ہوں اور جبیر کی یہ روایت فتح مکہ کے بعد کی ہو اور یہ بھی احتمال ہے کہ ان کے دادا ہوں اور جبیر نے ہجرت سے پہلے انہیں دیکھا ہو۔ کافر کی عیادت کرنے سے کوئی مانع نہیں خصوصاً اس دور میں کیونکہ ابھی تک کفار سے جنگ کی اجازت نہیں ملی تھی۔ ابن سعد نے ان کے سوانح میں ولید بن عقبہ کے بعد ان کے کوفہ کے والی بننے کا واقعہ اور اہل کوفہ کی ان کے بارے شکایت کرنے اور ان کے معزول ہونے کا واقعہ نقل کیا ہے۔(5) امیر معاویہ رضی اللہ عنہ نے اپنی جنگوں میں ان کی گوشہ نشینی پر ڈانٹا تھا تو انہوں نے معذرت کر لی۔ پھر انہیں مدینہ کا گورنر بنا دیا۔ جس کی ولایت کے دوران ان میں اور مروان کے درمیان نوبت بنوبت سلسلہ جاری رہا۔ ابن ابی خیثمہ کی روایت ہے کہ یحییٰ ابن سعید نے کہا: محمد بن عقیل بن ابی طالب ان کے والد کے پاس آئے اور پوچھا سب سے شریف کون ہے؟ فرمایا: میں اور میری ماں کا بیٹا، جبکہ سعید بن عاص اکیلا ہی کافی ہے۔ امیر معاویہ نے فرمایا: قریش کے سبھی انسان سعید بن عاص ہیں۔ وہ سخاوت و کرم نوازی میں شہرت رکھتے تھے۔ حتیٰ کہ اگر ان کے پاس کوئی حاجت مند آتا اور فی الفور ان کے پاس کچھ نہ ہوتا تو اسے سر بمہر تحریر لکھ دیتے، جب انتقال ہوا تو ان پر اسی ہزار(۸۰۰۰۰) دینار قرض تھا جو آپ کے بیٹے عمرو الاشدق نے ادا کیا۔ سیدنا سعید نے انچاس(۴۹) ہجری یا باون(۵۲) ہجری میں لوگوں کے ساتھ حج کیا جس کے بعد کچھ ہی عرصہ زندہ رہے۔ یہ بات یعقوب بن سفیان نے اپنی تاریخ میں بواسطہ یحییٰ بن کثیر بحوالہ لیث نقل کی ہے۔ صالح بن کیسان سے مروی ہے کہ سعید بن عاص بڑے بردبار اور وقار والے انسان تھے جب کسی چیز کو پسند یا نا پسند کرتے تو اس کا اظہار نہ کرتے تھے فرماتے: دل بدلتے رہتے ہیں اس سے آدمی کے لئے مناسب نہیں کہ وہ آج کسی چیز کی تعریف اور کل مذمت کرنے لگے۔ ان کی حکیمانہ باتوں میں سے ایک قول ہے: شریف سے مزاح نہ کرو وہ تم سے بغض کرنے لگے گا۔ اور نہ کسی کمینے سے مزاح کرو ورنہ وہ جری اور دلیر ہو جائے گا۔ یہ بات المجالسہ میں بطریق ابی عبیدہ منقول ہے ابن ابی الدنیا نے بواسطہ ابن المبارک دوسری سند سے نقل کیا ہے ان کے اقوال میں سے ہے: دو جگہ خاموش رہنے سے میں معذور نہیں۔ جب میں کسی جاہل سے مخاطب ہوں یا مجھے کوئی اپنا کام ہو۔ اسے بھی المجالسہ میں بطریق اسمعی نقل کیا ہے۔ زبیر فرماتے ہیں: انہیں شہد کا ڈبہ کہا جاتا تھا، زبیر بن بکار کا قول ہے: سعید عقیق میں اپنے محل میں ترپن (۵۳ھ) میں فوت ہوئے۔","",{"fn":"(1) ایضا (۲۰۸۲) استیعاب (۹۹۲)\n(2) الجرح والتعدیل (۴۸/۴)\n(3) استیعاب (۱۸۳/۲)\n(4) کنز العمال (۳۷۱۱۷)\n(5) الطبقات (۲۱/۵)"}],[3264,"§۳۲۷۰ ۔ سعید بن عاص\nبن ہشام بن مغیرہ بن عبد اللہ بن عمر بن مخزوم اکثر وہی۔ ان کی ایک حدیث ہے۔ ذہبی نے تجرید میں ان کا نسب بیان کیا ہے: سعید بن عامر بن ہشام بن مغیرہ مخزومی، عکرمہ بن خالد کے دادا معجم طبرانی میں ہے۔ مطین بن سفیان، حماد بن سلمہ سے وہ عکرمہ بن خالد سے وہ اپنے والد سے بحوالہ اپنے دادا روایت کرتے ہیں: جب طاعون پڑا۔۔۔۔ لیکن وہاں طبرانی سے سہو ہوا اور انہیں خاء میں یعنی خالد بن عاص میں ذکر کیا ہے۔ میں کہتا ہوں: میں نے یہ حدیث ذکر کی ہے اور اس کا شاہد بھی بیان کیا ہے قسم رابع میں حرف عین عاص بن ہشام میں ان کی تحریر ہے جیسا کہ بیان ہوگا۔ ان شاء اللہ تعالیٰ ادھر ذہبی نے عاص بن ہشام کے سوانح کا عنوان طبرانی، ابونعیم اور ابوموسیٰ کے اتباع میں قائم کیا ہے۔"],[3265,"§۳۲۷۱ ۔ سعید بن عامر(1)\nبن حذیم بن سلامان بن ربیعہ بن سعد حج قرشی تھی، اکابر اور فضیلت والے صحابہ میں سے ہیں۔ والدہ کا نام اروی بنت ابی محیط ہے۔ خیبر سے پہلے اسلام لائے، ہجرت کی اس میں اور بعد کے معرکوں میں شریک ہوئے۔ سیدنا عمر رضی اللہ عنہ نے انہیں حمص کا والی بنایا تھا۔ خیر و نیکوکاری میں مشہور تھے۔ ان سے عبد الرحمن بن سابط تھی روایت کرتے اور شہر بن حوشب وغیرہ ان سے مرسل روایت کرتے ہیں۔ ابو یعلیٰ بروایت ابن سابط بحوالہ سعید بن حذیم روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر کوئی حور عین اپنا ہاتھ باہر نکال دے تو ہر جاندار اس کی خوشبو سونگھ لے\" حدیث مختصر ہے،(2) جبکہ ابو احمد الحاکم اور ابن سعد نے طویل نقل کی ہے۔ جس میں سعید کا اپنی اہلیہ کے ساتھ ایک واقعہ ہے جس میں ہے کہ انہوں نے اپنا ملنے والا وظیفہ تقسیم کر دیا تھا۔ محمد بن عثمان بن ابی شیبہ اپنی تاریخ میں بطریق زید بن اسلم روایت کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے سعید بن عامر بن حذیم سے کہا کہ اہل شام تمہیں پسند کرتے ہیں۔ فرمایا: چونکہ میں ان سے تعاون کرتا اور انہیں تسلی دیتا رہتا ہوں۔ آپ نے فرمایا: یہ دس ہزار لے لو اور اس سے وسعت حاصل کرو۔ عرض کی: یہ رقم مجھ سے زیادہ ضرورت مند کو دے دیجئے۔ (حدیث) ابن سعد کی بطریق ابن سابط روایت ہے کہ سیدنا عمر رضی اللہ عنہ نے سعید بن عامر کی طرف پیام بھیجا کہ میں تمہیں گورنر بنانے والا ہوں۔ عرض کی: مجھے مشقت میں نہ ڈالیں۔ فرمایا: میں تمہیں ایسی قوم کی طرف بھیج رہا ہوں جن سے تم افضل نہیں۔ میں تمہیں اس لیے نہیں بھیج رہا کہ انہیں سزائیں دو یا ان کی بے عزتی کرو بلکہ انہیں ساتھ ملا کر دشمن سے جہاد کرو اور ان کا مال غنیمت مسلمانوں میں تقسیم کرو۔ ابو یعلیٰ، حسن بن سفیان اور بغوی کی بطریق ابن سابط بحوالہ سعید بن عامر روایت کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"فقراء مسلمان جلدی لائے جائیں گے، انہیں حساب کے لیے روکا جائے گا۔ وہ کہیں گے: اللہ کی قسم! ہمارے پاس تو کچھ نہ تھا جس کا ہم حساب دیں، جس پر اللہ تعالیٰ فرمائے گا: \"میرے بندوں نے سچ کہا۔ یوں وہ دوسرے لوگوں سے ستر سال پہلے جنت میں جائیں گے۔\"(3) بقول ابن سعد رضی اللہ عنہ: تیسرے طبقہ میں ہیں۔(4) بیس (۲۰ھ) میں فوت ہوئے، اس وقت وہ سیدنا عمر رضی اللہ عنہ کی طرف سے شام کے کسی علاقہ کے گورنر تھے۔ امام بخاری رضی اللہ عنہ نے بطریق زہری روایت کی ہے کہ خلافت فاروقی میں فوت ہوئے۔ ابوبکر بغدادی نے حمص فروکش ہونے والے صحابہ کے ناموں میں لکھا ہے: سیدنا عمر رضی اللہ عنہ نے انہیں عیاض کے بعد حمص کا والی مقرر کیا تو وہ آدھے سال سے کم عرصہ اس کے گورنر رہ کر فوت ہوئے۔ محرم بیس (۲۰ھ) میں والی بنے تھے اور جمادی الاولیٰ میں فوت ہوئے تھے۔ جبکہ ہشیم بن عدی اور ابن زبیر نے ان کی تاریخ وفات (۱۹ھ) لکھی ہے۔ ہشیم نے یہ اضافہ نقل کیا ہے: قیصاریہ میں فوت ہوئے، ابو عبیدہ کا قول ہے: اکیس (۲۱ھ) میں فوت ہوئے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۲۰۸۳) استیعاب (۹۹۳) تجرید (۲۲۳/۱)\n(2) المعجم الکبیر (۵۵۱۲/۶) مجمع الزوائد (۴۱۷/۱۰) الزہد لابن المبارک (۲۲۶) مختصر تاریخ دمشق (۳۲۱/۹)\n(3) المعجم الکبیر (۵۵۰۸/۶) مجمع الزوائد (۲۶۱/۱۰) جامع المسانید (۳۰۶/۵)\n(4) الطبقات (۱۳/۶)"}],[3266,"§۳۲۷۲ ۔ سعید بن عامر\nثعلبی نے اپنی تفسیر میں لکھا ہے: ان یہودیوں میں سے ہیں جو اسلام لائے، جن کے متعلق یہ آیت اتری: \"جن لوگوں کو ہم نے کتاب دی، جبکہ وہ اس کی تلاوت اس طرح کرتے ہوں جیسا اس کی تلاوت کا حق ہے (تو وہ لوگ ہی (درحقیقت) اس پر ایمان رکھتے ہیں۔”(1)۔","",{"fn":"(1) سورۃ البقرۃ: ۱۲۱"}],[3267,"§۳۲۷۳ ۔ سعید بن عبد قیس(1)\nبقول بعض: سعید بن عبید بن قیس بن لقط بن عامر بن امیہ یا ربیعہ بن ظرب بن حارث بن فہر قرشی فہری۔ ابن شاہین نے بطریق ابن کلبی وغیرہ نقل کیا ہے، بہت پہلے اسلام لائے اور حبشہ ہجرت کی۔ بلاذری کا بیان ہے کہ جعفر بن ابی طالب رضی اللہ عنہ سے پہلے وہ اور ان کے بھائی نافع بن عبد قیس مدینہ آئے۔","",{"fn":"(1) اسد الغابہ (۲۰۸۵) استیعاب (۹۹۴)"}],[3268,"§۳۲۷۴ ۔ سعید بن عبید(1)\nبن ابی اسید بن ملان بن ابی سلمہ بن عبد العزیز بن غیرہ بن عوف بن ثقیف ثقفی۔ اسماعیل بن طرح شاعر کے دادا۔ ابن مندہ کی روایت ہے کہ ابو سفیان نے اسماعیل شاعر کے دادا کو طائف کے روز تیر مارا جو ان کی آنکھ پر لگا وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، عرض کی: اللہ کے رسول! میری یہ آنکھ اللہ کی راہ میں شہید ہو گئی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو میں اللہ تعالیٰ سے دعا کروں وہ تمہاری آنکھ درست کر دے اور اگر چاہو تو جنتی آنکھ نکھل جائے۔”(2) انہوں نے عرض کی: جنتی آنکھ۔ ابن مندہ فرماتے ہیں: غریب ہے جو ہمیں اسی سند سے معلوم ہوئی۔ میں کہتا ہوں: اس میں ایک منکر لفظ ہے (معتبر راویوں کے خلاف) وہ یہ کہ طائف کے محاصرہ میں سیدنا ابو سفیان رضی اللہ عنہ مسلمان ہو چکے تھے، بھلا سعید اگر مسلمان تھے تو ابو سفیان ان کے کیسے تیر مار سکتے ہیں؟ مجھے لگتا ہے درست یہ ہے کہ سعید نے ابو سفیان کے تیر مارا تھا جس کی تائید اس روایت سے ہوتی ہے جو زبیر بن بکار نے اسی سند سے نقل کی ہے کہ سعید بن عبید سے مروی ہے کہ طائف کے روز میں نے ابو سفیان کو ایک باغ میں بیٹھے کھاتے دیکھا، میں نے تیر مارا تو اس کی آنکھ پر جا لگا۔۔۔۔ پھر وہ حدیث ذکر کی۔ ابن عائذ کی روایت ہے کہ ابو سفیان رضی اللہ عنہ کی آنکھ طائف کی جنگ میں شہید ہوئی۔ ابو الفرج اصبہانی کی بحوالہ قاسم بن محمد روایت ہے کہ وہ تیر جو عبد اللہ بن ابی بکر کے لگا وہ طائف کے وفد کے آنے تک اسی طرح رہا تو آپ نے انہیں وہ تیر دکھایا، تو سعید بن عبید نے کہا: میں نے بھی یہ تیر گھڑا تھا اور میں نے ہی پھینکا تھا۔ جس پر ابوبکر رضی اللہ عنہ نے فرمایا: الحمد للہ جس نے تمہارے ہاتھ سے اسے عزت بخشی اور اس کے ہاتھ سے تمہیں رسوا نہیں کیا۔ اس حدیث کا ایک اور طریق ہے جو عبد اللہ بن ابی بکر کے حالات میں ہے۔ اس سے ثابت ہوا کہ سعید بن عبید صحابی ہیں اور پہلی روایت بھی ثابت ہو گئی۔ والحمد للہ۔","",{"fn":"(1) اسد الغابہ (۲۰۸۸)\n(2) جامع المسانید (۳۰۸/۵) اسد الغابہ (۲۳۲/۲)"}],[3269,"§۳۲۷۵ ۔ سعید بن عبید بن نعمان\nسعد میں تذکرہ ہوا ہے وہی صحیح ہے۔ ابن ابی شیبہ کی روایت سے پتہ چلتا ہے یہ سعید ہیں اور جن سعد کا تذکرہ ہوا ہے ان کے علاوہ ہیں۔ شعبی سے مروی ہے کہ نبی صلی اللہ علیہ وسلم کے دور میں ابی، معاذ، زید، ابو الدرداء اور سعید بن عبید نے قرآن پڑھ لیا تھا۔ (حدیث)"],[3270,"§۳۲۷۶ ۔ سعید بن عتاب\nسلیط بن سلیط کے حالات میں ان کا ذکر ہوگا۔"],[3271,"§۳۲۷۷ ۔ سعید بن عثمان انصاری(1)(4)\nاحد میں شریک ہوئے۔ اسحاق بن راہویہ نے اپنی مسند میں بطریق زبیر روایت کی ہے کہ اللہ کی قسم! میں معتب بن قشیر کی بات سن رہا تھا اور مجھے اونگھ بھی آ رہی تھی۔ وہ کہتے ہیں کہ: \"اگر ہمیں بھی کچھ اختیار ہوتا تو ہم یہاں قتل نہ ہوتے۔\"(2) پھر فرمایا اور اللہ تعالیٰ کا یہ ارشاد: \"جن لوگوں نے اس دن پیٹھ پھیر دی جب دونوں لشکر ایک دوسرے سے ٹکرائے۔\"(3) ان میں عثمان بن عفان، سعید بن عثمان، علقمہ بن عثمان دونوں انصاری بھی تھے۔ فرماتے ہیں: یہ لوگ مدینہ کے پاس ایک پہاڑ تک جو اعوص کے میدان میں تھا جا پہنچے، جہاں تین دن ٹھہرے رہے۔ میں کہتا ہوں: ابن اسحاق نے یہ روایت اپنی مسند میں اپنے ادراج (اصل روایت سے ہٹ کر اضافہ) کے ساتھ نقل کی ہے۔ ان کا یہ کہنا پھر فرمایا: یہ سارا مغازی میں ابن اسحاق کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۸۸)\n(2) سورۃ آل عمران: ۱۵۴\n(3) سورۃ آل عمران: ۱۵۵\n(4) السیرۃ النبویۃ (۱۲۵/۲)"}],[3272,"§۳۲۷۸ ۔ سعید بن عدی الانصاری\nاموی نے شہداء یمامہ میں اور ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے اس کی نظیر سعد بن عثمان میں گزر چکی ہے۔ مجھے معلوم نہیں آیا یہ دونوں بھائی ہیں یا ایک شخص ہے جس کے نام میں اختلاف ہے؟"],[3273,"§۳۲۷۹ ۔ سعید بن عمارہ\nدوسرے سعد میں تذکرہ ہوا ہے۔"],[3274,"§۳۲۸۰ ۔ سعید بن عمرو التمیمی(1)\nبنی تمیم کے حلیف، موسیٰ بن عقبہ اور ابن اسحاق(2) نے مہاجرین حبشہ میں ان کا ذکر کیا ہے۔ موسیٰ بن عقبہ کا قول ہے: وہ اور ان کے ماں شریک بھائی تمیم بن حارث بن قیس اجنادین میں شہید ہوئے ایسا ہی زبیر کا قول ہے یہ ذہبی کا قول ہے۔(3) ابن سعد نے پہلے اسلام لانے والوں میں ان کا ذکر کیا ہے: بدر میں شریک نہ ہوئے۔ واقدی، ابو معشر، ابو الاسود، بحوالہ عروہ ان کا نام سعید کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۲۰۹۰) استیعاب (۹۹۵)\n(2) السیرۃ النبویۃ (۷/۴)\n(3) الطبقات (۱۴۴/۴)"}],[3275,"§۳۲۸۱ ۔ سعید بن عمرو بن غَزِیَّہ انصاری\nحارث کے بھائی۔ ابن السکن کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ ابن فتحون کا قول ہے: ابن عبد البر نے ان کے بھائی حارث کے حالات میں ان کا ذکر کیا ہے اور علیحدہ ان کا عنوان نہیں قائم کیا۔ میں کہتا ہوں: بلکہ ابو عمر(1) نے ان کے بھائی زید بن عمرو کے حالات میں لکھا ہے: سعید کے لیے شرف صحابیت ثابت نہیں۔","",{"fn":"(1) اسد الغابہ (۲۰۹۲)"}],[3276,"§۳۲۸۲ ۔ سعید بن عمرو الکندی(1)\nابن الاثیر نے بحوالہ ابن ماکولا(2) ان کا ذکر کیا ہے البتہ انہوں نے کہا: ان کی حدیث محمد بن المطلب نے علی بن قرین سے عبیدہ بن حریث کندی سے بواسطہ الصلت بن حبیب، الثقفی سے بحوالہ ان کے روایت کی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا۔","",{"fn":"(1) اسد الغابہ (۲۳۴/۲)\n(2) الاکمال (۵۰۳/۴) (۵۰۴/۴)"}],[3277,"§۳۲۸۳ ۔ سعید بن عمرو العیذنیّ المحاربیّ\nابو عبید نے اپنی قوم میں سے نبی صلی اللہ علیہ وسلم کے پاس آنے والوں میں ان کا ذکر کیا ہے۔ بقول رشاطی: ابو عمر اور ابن فتحون نے ان کا ذکر نہیں کیا ہے۔"],[3278,"§۳۲۸۴ ۔ سعید بن عمرو\nبقول بعض: یہ ابو کبشہ انماری کا نام ہے جس پر ابن حبان نے اعتماد کیا ہے۔ کنیتوں میں ان کے نام میں اختلاف کی وضاحت ہوگی۔"],[3279,"§۳۲۸۵ ۔ سعید بن القشب الازدی(1)\nبنی عبد مناف کے حلیف۔ بقول بعض: نبی صلی اللہ علیہ وسلم نے انہیں جرش (مکہ کی جانب یمن کے اضلاع) کا والی بنایا تھا۔ یہ ابو عمر کی(2) روایت ہے۔","",{"fn":"(1) اسد الغابہ (۲۰۹۳) استیعاب (۹۹۶)\n(2) استیعاب (۱۸۷/۲)"}],[3280,"§۳۲۸۶ ۔ سعید بن قیس\nبن صخر بن حرام بن ربیعہ بن عدی بن غنم بن کعب بن سلمہ انصاری سلمی۔ ابو الاسود نے بحوالہ عمروہ شکر کا یہ بدر میں ان کا ذکر کیا ہے۔"],[3281,"§۳۲۸۷ ۔ سعید بن مرّہ العجلیّ\nسیف اور طبری کا بیان ہے کہ مثنیٰ بن حارثہ نے انہیں بارہ (۱۲ھ) میں عراق کا گورنر بنایا وہ سب سے زیادہ نصاریٰ بنی تغلب کے لیے سخت تھے۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے اور یہ پہلے بیان ہو چکا ہے کہ صحابہ ہی امیر بنائے جاتے تھے۔"],[3282,"§۳۲۸۸ ۔ سعید بن مقرّن المزنی\nبھائیوں میں سے ایک۔ طبری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ سیف نے فتوح میں لکھا ہے: خالد بن ولید رضی اللہ عنہ نے اس وقت عراق کے کسی علاقہ پر مقرر کیا جب خلافت صدیقی میں شام کی جانب روانہ ہوئے تھے۔"],[3283,"§۳۲۸۹ ۔ سعید بن المنذر\nبن محمد بن عقبہ بن احیمر بن جلاح انصاری۔ ابن حبان(1) نے صحابہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الثقات (۱۵۷/۳)"}],[3284,"§۳۲۹۰ ۔ سعید بن مینا (مولا رسول اللہ صلی اللہ علیہ وسلم)(1)\nخطیب نے المتفق میں بطریق موسیٰ بن سلیمان الایادی بحوالہ سعید بن مینا مولا رسول اللہ صلی اللہ علیہ وسلم روایت کی ہے کہ \"مخذوم سے ایسے بھاگو جیسے شیر سے بھاگتے ہو۔\"(2)","",{"fn":"(1) اسد الغابہ (۲۰۹۶)\n(2) مسند احمد (۴۴۲/۲) دلائل النبوۃ للبیہقی (۱۳۵/۷) اسد الغابہ (۲۳۴/۲)"}],[3285,"§۳۲۹۱ ۔ سعید بن نوفل\nبن حارث بن عبد المطلب بن ہاشم نبی صلی اللہ علیہ وسلم کے چچا زاد بھائی۔ اجازت(1) لینے کے بارے میں نبی صلی اللہ علیہ وسلم کی ایک حدیث روایت کرتے ہیں ان سے عمار بن ابی عمار نقل کرتے ہیں۔ ابن مندہ نے ان کا ذکر کیا ہے اور ابو نعیم کا قول ہے: میرے نزدیک یہ حدیث مرسل ہے۔ میں کہتا ہوں: دار قطنی کی بات سے پتہ چلتا ہے یہ سعید بن حارث ہیں جو نوفل کے بھائی ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۲۳۵/۲)"}],[3286,"§۳۲۹۲ ۔ سعید بن یربوع(1)\nبن عنکمہ بن عامر بن مخزوم بن قرم قرشی مخزومی۔ بقول نسائی وغیرہ انہیں شرف صحابیت حاصل ہے۔ ان کا نام المحرم بقول بعض اسمرم تھا۔ یہ بخاری(2) اور عسکری کا بیان ہے۔ زبیر کا قول ہے: ان کے دو بیٹے تھے ھود اور حکم، ان کی کنیت ابو ھود تھی ابن سعد لکھتے ہیں: ان کی کنیت ابو الکشم تھی۔ والدہ کا نام لبنی بنت سعید بن رباب ہمیہ۔ نبی صلی اللہ علیہ وسلم نے ان (صحابی) کا نام تبدیل کیا تھا۔ ابوداؤد(3) نے ان کے بیٹے عبد الرحمن کی روایت سے بحوالہ ان کے ان کی حدیث روایت کی ہے۔ اسی طرح ان کا دوسرا بیٹا جس کا نام عثمان ہے وہ بھی ان سے روایت کرتا ہے۔ بغوی اور ابن مندہ کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا تھا: \"ہم میں سے کون بڑا ہے، میں یا تم؟\"(4) عرض کی: آپ بڑے ہیں اور مجھ سے بہتر ہیں جبکہ میرا سن آپ سے پہلے کا ہے۔ آپ نے ان کا نام تبدیل کر کے سعید رکھا تھا اور فرمایا: \"المحرم گزر چکا ہے۔\" ابن مندہ فرماتے ہیں: یہ روایت غریب ہے جسے ہم اسی سند سے جانتے ہیں۔ میں کہتا ہوں: اس کا کچھ حصہ ابوداؤد میں ہے اور بغوی نے المحرم کے حالات میں حرف صاد میں اسی سند سے دوسری حدیث نقل کی ہے۔ الزبیر وغیرہ کا قول ہے: فتح مکہ کے روز اسلام لائے۔ بقول بعض: اس سے پہلے مسلمان ہوئے۔ کنیت ابو ھود تھی، حنین میں شریک ہوئے اور اس کی غنیمت میں سے حصہ پایا۔ امام بخاری رحمتہ اللہ علیہ نے اپنی تاریخ میں لکھا ہے کہ سعید بن یربوع کی نظر چلی گئی تو سیدنا عمر رضی اللہ عنہ ان کی عیادت کرنے گئے تو ان سے فرمایا: جمعہ اور جماعت کی حاضری نہ چھوڑنا۔ انہوں نے کہا: مجھے لے جانے والا کوئی نہیں۔ تو سیدنا عمر رضی اللہ عنہ نے قیدیوں میں سے ایک نوجوان کو ان کی خدمت پر مامور کر دیا۔ یہ کسی نے اضافہ نقل کیا ہے۔ الزبیر کا قول ہے، جن چار افراد کو سیدنا عمر رضی اللہ عنہ نے نشانات حرم کی تجدید (To Repeat) کے لیے مقرر کیا تھا، ان میں سے ایک یہ بھی تھے۔ واقدی بطریق نافع بن جبیر روایت کرتے ہیں کہ جب سیدنا عمر رضی اللہ عنہ شام آئے تو یہاں لوگوں کو طاعون میں مبتلا پایا، قریش کے بزرگوں سے مشورہ کیا، جن میں محرمہ بن نوفل، سعید بن یربوع، حکیم بن حزام وغیرہ بھی تھے۔ ان میں سے جس نے لوٹنے کا مشورہ دیا وہ محرمہ بن نوفل تھے اور بتایا کہ قریش کے اتنی آدمی تجارت کی غرض سے گئے، انہیں طاعون کے علاقہ میں رات آ گئی تو سب کے سب اسی رات مر گئے۔ صرف دو شخص بچے جن میں سے ایک کا بھائی صفوان بن نوفل تھا۔ زبیر فرماتے ہیں: چون (۵۴ھ) میں ایک سو بیس(۱۲۰) سال کی عمر میں، بقول ایک سو چوبیس(۱۲۴) سال کی عمر میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۰۱) استیعاب (۹۹۸)\n(2) التاریخ الکبیر (۴۵۳/۱)\n(3) ابوداؤد کتاب الجہاد باب قتل الاسیر (۲۶۸۴)\n(4) المعجم الکبیر (۵۵۲۸/۶) مجمع الزوائد (۵۳/۸) جامع المسانید (۳۱۲/۵)"}],[3287,"§۳۲۹۳ ۔ سعید بن یزید الازدی(1)\nمصر فروکش ہوئے۔ ابن یونس \"تاریخ الغرباء\" میں لکھتے ہیں: یہ فلسطین والوں میں سے تھے اور یزید بن معاویہ کی جانب سے مصر کے گورنر تھے، ان سے اہل مصر میں سے ابو الخیر مرشد الیزنی نے روایت کی ہے، پھر بطریق لیث اسے بیان کیا۔ اسی طرح حسن بن سفیان نے بحوالہ سعید بن یزید روایت کی ہے کہ ایک شخص نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کوئی نصیحت کیجئے۔ فرمایا: \"میں تمہیں یہ وصیت کرتا ہوں اللہ تعالیٰ سے ایسے حیا کرو جیسے تم اپنی قوم کے کسی نیک شخص سے شرم کرتے ہو۔\"(2) ابو عمر(3) لکھتے ہیں: ابو الخیر کا گمان ہے انہیں شرف صحابیت حاصل ہے اور ہم نے جو ان کی روایت دیکھی تو وہ ابن عمر سے ہے۔ ابن ابی حاتم(4) کا بیان ہے اس میں عبد الحمید بن جعفر سے آگے اختلاف ہے۔ بعض نے سعید بن مرشد سے بحوالہ ان کے چچا زاد سے نقل کیا ہے۔ میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم مراسیل ابن ابی حاتم میں ہے میں نے اپنے والد کو فرماتے سنا: ہمیں معلوم نہیں یہ صحابی ہیں یا نہیں۔ البتہ عبد الحمید ابن جعفر بحوالہ سعید بن یزید ایک صحابی سے روایت کرتے ہیں: \"اپنے رب سے حیا کر۔\" جس سے ہمیں پتہ چلا کہ یہ صحابی نہیں ہیں۔ اس بنا پر ان کا قول یہی صحیح ہوگا جو ابو عمر(5) کا ہے: \"عن ابن عمر سے مروی ہے۔\" یہ لفظی غلطی ہے۔ ابو عمر الکندی کا بیان ہے: جب یہ اہل مصر کے گورنر بنے تو وہاں کے رؤساء نے کہا: ہمارے دور میں ان کے جیسا کوئی نوجوان نہیں ہوا، اس سے بھی معلوم ہوا کہ یہ صحابی نہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۰۲) استیعاب (۹۹۹) الزہد لاحمد (ص ۴۶) المعجم الکبیر (۵۵۳۹/۶) کنز العمال (۵۷۷۰)\n(2) مجمع الزوائد (۲۸۴/۱۰)\n(3) استیعاب (۱۸۸/۲)\n(4) الجرح والتعدیل (۷۲/۴)\n(5) استیعاب (۱۸۸/۲)"}],[3288,"§۳۲۹۴ ۔ سعید بن یزید البلوی\nابن ابی خیثمہ اور ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ان میں اور سابقہ شخصیت میں فرق کیا ہے جبکہ دوسروں نے دونوں کو ایک لکھا ہے۔"],[3289,"§۳۲۹۵ ۔ سعید بن فلان\nیا فلان بن سعید۔ حسن بن سفیان بطریق یونس بن ابی یعقوب وہ بحوالہ اپنے والد روایت کرتے ہیں کہ میں جعفر بن عمرو بن حریث اور سعید بن اشوع فلان بن سعید یا سعید بن فلان کے پاس بیٹھے تھے۔ انہوں نے ہم سے بیان کیا کہ کچھ لوگ نبی صلی اللہ علیہ وسلم کے پاس آئے اور کہنے لگے: اللہ کے رسول صلی اللہ علیہ وسلم! ہمیں کچھ جنتی لوگ دکھائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں جنتی ہوں اور ابوبکر و عمر رضی اللہ عنہما بھی جنتی ہیں۔\"(1) ایک جماعت نے ان کا نام لیا ہے کہ فلان بن سعید یا سعید بن فلان نے فرمایا: میں بھی جنتی ہوں۔ میں کہتا ہوں: حسن بن سفیان نے مسند سعید بن زید میں یہ روایت نقل کی ہے جس میں تامل ہے، کیونکہ ابن اشوع نے ان کا نام نہیں پایا۔ اگر یہ روایت محفوظ ہے تو وہ کوئی اور ہیں۔","",{"fn":"(1) کنز العمال (۳۶۷۴۲)"}],[3290,"§۳۲۹۶ ۔ سعید\nمیسرہ کے والد، ان کا ذکر ان کی مولاۃ کثیرہ بنت سفیان میں ہوگا۔"],[3291,"§۳۲۹۷ ۔ سعید الشامی\nعبد العزیز کے والد۔ ان سے کئی احادیث مروی ہیں۔ جوان کے بیٹے کی روایت سے بحوالہ ان کے مروی ہیں۔ ان میں عبد الغفور ابو الصباح بن عبد العزیز وہ بحوالہ اپنے والد عبد العزیز وہ اپنے والد سعید سے روایت کرتے ہیں: ایک روایت وہ ہے جو ابن عدی نے اسی سند سے بحوالہ نبی صلی اللہ علیہ وسلم نقل کی ہے: \"مومن بندے کے دل میں کبھی بھی ایمان اور بخل اکٹھے نہیں ہوں گے۔\"(1) ابن عدی نے لکھا ہے اس سند سے بائیس(۲۲) احادیث مروی ہیں۔ ابن مندہ نے بطریق بقیہ، بحوالہ عبد الغفور اسی سند سے نقل کیا ہے۔ اس میں ہے ان کے والد سے مروی ہے جو صحابی رسول صلی اللہ علیہ وسلم ہیں، پھر دوسری حدیث نقل کی ہے، ابن قانع نے ان کی حدیث نقل کی۔ عبد العزیز نے بحوالہ اپنے والد روایت کی ہے کہ میں نے نبی صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی، میں آپ صلی اللہ علیہ وسلم کے قریب تھا۔ (حدیث) ان کے حوالہ سے ایک اور حدیث روایت کی جس میں ان کا نسب انصاری بیان کیا ہے۔ ابو عبد العزیز کا تذکرہ کنیتوں میں ہوگا جو ایک حدیث میں ہے وہ یہی ہیں۔ طبری نے تفسیر میں ابن ابی عاصم نے \"وحدان\" میں اور امام بخاری رحمتہ اللہ علیہ نے کتاب الضعفاء میں عبد الغفور کے حالات میں بروایت عثمان بن مطر بواسطہ ان کے، عبد العزیز بن سعید سے انہوں نے بحوالہ اپنے والد نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ بہت سی مخلوق کو مسخ کرے گا۔ انسان خلوت و تنہائی میں گناہ کرتا ہے تو اللہ تعالیٰ فرماتا ہے: اس نے مجھے حقیر سمجھا ہے پھر اس کی صورت مسخ کر دیتے ہیں پھر قیامت کے دن اسے انسان ہی اٹھائے گا۔ اور اس سے فرمائے گا: جیسے اس نے تمہیں پہلی بار بنایا وہ یہی تم لوٹو گے، پھر اسے جہنم میں ڈال دے گا۔\"(2) حجی بن مخلد کی مسند میں ان کی چار حدیثیں ہیں۔","",{"fn":"(1) الکامل فی الضعفاء (۱۹۶۶/۵)\n(2) جمع الجوامع (۵۳۳۸)"}],[3292,"§۳۲۹۸ ۔ سُعَید (تصغیر)\nسعید بن سہل میں تذکرہ ہوا ہے۔"],[3293,"§۳۲۹۹ ۔ سُعَیر (تصغیر)\nبن خفاف تمیمی۔ سیف نے الفتوح میں ان کا ذکر کیا ہے کہ بطون تمیم پر وہ نبی صلی اللہ علیہ وسلم کی طرف سے مقرر تھے۔ سیدنا ابوبکر رضی اللہ عنہ نے بھی انہیں اسی عہدہ پر برقرار رکھا۔"],[3294,"§۳۳۰۰ ۔ سعیر بن سوادہ العامری\nبقول بعض: وہی سفیان ہیں۔ ابن مندہ کی بطریق علاء بن فضل بواسطہ ابو سوید المنقری بحوالہ اپنے آباء واجداد روایت ہے کہ سعیر بن سوادہ نبی صلی اللہ علیہ وسلم کے پاس آئے۔"],[3295,"§۳۳۰۱ ۔ سعیر بن العدّاء الفریعی(1)\nبقول بعض: البکائی۔ مدائنی نے کاتبین رسول اللہ صلی اللہ علیہ وسلم میں ان کا ذکر کیا ہے۔ عبد اللہ بن یحییٰ کے طریق سے مروی ہے کہ سعیر بن عدّاء کے بیٹے نے مجھے ایک تحریر دکھائی جو یوں تھی: \"محمد رسول اللہ صلی اللہ علیہ وسلم کی طرف سے بنو سعیر بن عدّاء نے قلمبند کیا ہے۔\" باورودی اور ابن مندہ نے اسی سند سے لکھا ہے اور یہ اضافہ نقل کیا ہے: \"میں نے رنجح کی ذمہ داری سنبھالی ہے۔\"(2)","",{"fn":"(1) اسد الغابہ (۲۱۰۴)\n(2) اسد الغابہ (۲۱۰۵)"}],[3296,"§۳۳۰۲ ۔ سَعِیَہ\nابن الحریض، بقول بعض: سعنہ، قریب ہی تذکرہ ہوا ہے۔"],[3297,"§۳۳۰۳ ۔ سُفَعَہ الغافقی(1)\nایک صحابی رسول اللہ صلی اللہ علیہ وسلم ہیں جو فتح مصر میں شریک ہوئے۔ ابن یونس نے ان کا ذکر کیا ہے کہ لوگوں نے اپنی کتابوں میں ان کا نام لکھا ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۷/۲)"}],[3298,"§۳۳۰۴ ۔ سفیان بن اسد(1)\nابید الحضری۔ ابن ابی خیثمہ اور ابن ابی عاصم(2) وغیرہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بروایت بقیہ ایک حدیث نقل کی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بڑی بد دیانتی اور خیانت یہ ہے کہ تم اپنے (مسلمان) سے کوئی ایسی بات کہو جس میں وہ تمہیں سچا سمجھے جبکہ تم اس سے جھوٹ بول رہے ہو۔\"(3) ابن مندہ فرماتے ہیں: روایت غریب ہے، ابن عدی کا قول ہے کہ محمد بن ضبارہ نے بحوالہ اپنے والد بقیہ کی متابعت میں اسے نقل کیا ہے یہی روایت یزید بن شرتح نے بواسطہ جبیر بن نفیر نقل کی تو فرمایا: تواس بن سمعان سے مروی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۲۱۰۶) استیعاب (۱۰۰۱) تجرید (۲۲۵/۱)\n(2) الاحاد والمثانی (۲۶۲۳/۵)\n(3) ابوداؤد کتاب الادب باب فی المعاریض (۴۹۷۱) السنن الکبری (۱۹۹/۱۰)"}],[3299,"§۳۳۰۵ ۔ سُفیان بن اُمَیَّہ\nبن ابی سفیان بن امیہ بن عبد شمس قرشی زہری بلاذری نے ان کا ذکر کیا ہے۔ فرماتے ہیں: اہل حجاز کے پاس سیدنا علی رضی اللہ عنہ کی وفات کی اطلاع یہی لے کر گئے تھے ان کی کوئی نرینہ اولاد نہ تھی، ان کے والد حالت کفر پر مرے، جو سیدنا ابو سفیان بن حرب رضی اللہ عنہ کے چچا زاد تھے۔ رہے ان کے بیٹے سفیان جن کا عنوان ہے تو مؤرخین کے قول کا تقاضا یہ ہے کہ فتح مکہ کے بعد مکہ میں جو قریشی بچا وہ مسلمان ہو کر نبی صلی اللہ علیہ وسلم کے ساتھ حجۃ الوداع میں حج کے لیے شریک ہوا ہے تو یہ صحابی ہیں۔"],[3300,"§۳۳۰۶ ۔ سفیان بن بشر\nسر میں ذکر ہوگا۔"],[3301,"§۳۳۰۷ ۔ سفیان بن ثابت الانصاری(1)\nاز بنی عمیب۔ ابن ابی حاتم(2) نے بحوالہ اپنے والد صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن شاہین کا قول ہے کہ امام واقدی نے فرمایا: بئر معونہ کے واقعہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۰۷) استیعاب (۱۰۰۳)\n(2) الجرح والتعدیل (۲۱۶/۴)"}],[3302,"§۳۳۰۸ ۔ سفیان بن حاطب(1)\nبن امیہ بن رافع بن سوید بن حرام بن ہیثم بن ظفر انصاری ظفری، بقول ابن شاہین: ابن کلبی فرماتے ہیں: اُحد میں شریک اور واقعہ بئر معونہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۰۸) استیعاب (۱۰۰۴)"}],[3303,"§۳۳۰۹ ۔ سفیان بن الحکم الثقفی\nحکم بن سفیان میں تذکرہ ہوا۔"],[3304,"§۳۳۱۰ ۔ سفیان بن خولی(1)\nبن عبد عمرو بن خولی بن ہمام العبدی۔ ابن کلبی کا بیان ہے انہیں بارگاہ نبوی میں آنے کی سعادت حاصل ہے، رشاطی نے حدادی میں لکھا ہے: ابو عمر اور ابن فتوح نے ان کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۲۱۱۰)"}],[3305,"§۳۳۱۱ ۔ سفیان بن ابی زہیر ازدی(1)\nاز ازد شنوءۃ۔ مدائنی اور خلیفہ کا قول ہے: ان کے والد کا نام القرد ہے۔ بقول بعض: ابن نمیر بن مرارہ بن عبد اللہ بن مالک۔ انہیں نمری بھی کہا جاتا ہے، کیونکہ یہ نمیر بن عثمان بن نضر بن زہران کی اولاد سے ہیں۔ مدینہ فروکش ہوئے، بخاری میں بروایت عبد اللہ بن زبیر بحوالہ ان کے ان کی حدیث آئی ہے۔ اسی طرح امام بخاری رحمتہ اللہ علیہ(2) نے بطریق سائب بن یزید بحوالہ ان کے روایت کی ہے کہ ازد شنوءۃ کے ایک شخص ہیں، صحابی رسول اللہ صلی اللہ علیہ وسلم ہیں: \"جس نے حفاظت کے لیے کتا پالا۔۔۔\"(3) (حدیث)","",{"fn":"(1) اسد الغابہ (۲۱۱۱) استیعاب (۱۰۰۶) تجرید (۲۲۶/۱)\n(2) بخاری کتاب الحرث والمزارعۃ باب اقتناء الکلب للحراسۃ (۲۳۲۳) کتاب بدء الخلق باب اذا وقع الذباب فی شراب احدکم فلیغمسہ (۳۳۲۶)\n(3) مسلم کتاب المساقاۃ باب الامر بقتل الکلاب و بیان نسخہ (۴۰۱۲) نسائی کتاب الصید والذبائح (۴۲۹۶) ابن ماجہ کتاب الصید باب النھی عن اقتناء الکلب الا کلب صید اور حرث او ماشیۃ (۳۲۰۶)"}],[3306,"§۳۳۱۲ ۔ سفیان بن زید(1)\nیا یزید ازدی۔ امام بخاری رحمتہ اللہ علیہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے کہ ان سے جو حدیث مروی ہے وہ منقطع ہے جو بروایت روح بواسطہ ابن عوف، ابن سیرین سے بحوالہ ان کے العتیرہ کے بارے مروی ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۱۲) استیعاب (۱۱۰۶)"}],[3307,"§۳۳۱۳ ۔ سفیان بن زیاد الحمصیّ\nعبد الصمد بن سعید نے ان صحابہ میں ان کا ذکر کیا ہے جو حمص فروکش ہوئے۔"],[3308,"§۳۳۱۴ ۔ سفیان بن سہل(1)\nیا ابن ابی سہل ثقفی۔ حدیث مغیرہ بن شعبہ میں ان کا ذکر ہے۔ امام احمد، نسائی، اور ابن حبان وغیرہ نے حدیث عبد الملک بن عمیر بواسطہ حصین بن عقبہ بحوالہ مغیرہ بن شعبہ رضی اللہ عنہ روایت کی کہ میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم سفیان بن ابی سہل کی کوکھ کا کپڑا پکڑ کر فرما رہے تھے: \"اپنا ازار نیچے نہ لٹکنے دیا کرو۔\"(2) الفاظ امام احمد کے ہیں، نسائی میں ہے سفیان بن سہل، محدثین کے ہاں اس کا مدار شریک بن عبد الملک پر ہے۔ بقول بعض شریک بن عبد الملک سے، ایک قول ہے: شریک، عبد الملک سے بواسطہ قبیصہ بن جابر روایت کرتے ہیں۔ اس میں حصین بن عقبہ نہیں۔ بقول بعض: عبد الملک، مغیرہ سے بلا واسطہ نقل کرتے ہیں۔ پہلی سند زیادہ صحیح ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۱۳) تجرید (۲۲۶/۱)\n(2) مسند احمد (۲۴۶/۴) (۲۵۳/۴) المعجم الکبیر (۱۰۲۳/۲۰) الصحیح لابن حبان (۱۴۴۹) المصنف لابن ابی شیبہ (۳۹۵/۸)"}],[3309,"§۳۳۱۵ ۔ سفیان بن صہابہ المہری(1)\nخرق شاعر سے جانے پہچانے جاتے ہیں۔ ابن ابی داؤد نے صحابہ میں ان کا ذکر کیا ہے۔ ابن مندہ وغیرہ نے ان کا اتباع کیا ہے۔ ابن یونس نے ان کا تذکرہ کیا کہ فتح مصر میں شریک تھے، اور ان کا قول ہے: میں اور مقداد جاہلیت میں چوری کیا کرتے تھے۔","",{"fn":"(1) اسد الغابہ (۲۱۱۶)"}],[3310,"§۳۳۱۶ ۔ سفیان بن عبد اللہ\nبن ربیعہ بن حارث بن مالک بن حطیط بن جشم ثقفی الطائی، وفد کے ساتھ مسلمان ہوئے اور نبی صلی اللہ علیہ وسلم سے اعتماد کی کوئی دعا پوچھی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"کہو! اللہ میرا رب ہے، پھر اسی پر ثابت قدم رہو۔\"(1) مسلم اور نسائی نے ان کی حدیث نقل کی ہے۔ سیدنا عمر رضی اللہ عنہ نے طائف کی زکوۃ وصول کرنے پر انہیں مامور کیا تھا۔ ابن ابی شیبہ کی ایک مرسل روایت میں ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں مقرر کیا تھا۔ ان سے ان کی اولاد میں سے عاصم، عبد اللہ، علقمہ، عمرو اور ابو الحکم وغیرہ روایت کرتے ہیں۔ ابو الحسن المدینی کا قول ہے: سفیان بن عبد اللہ بن ربیعہ حنین میں شریک ہوئے۔ ان کے بھائی عثمان شہید ہوئے تو یہ اور آگے بڑھے اور ابو سوید سے کہنے لگے: ان کے بعد جینے کا کیا مزہ؟ ابو سوید کو لگا کہ انہیں شکست ہونے والی ہے جس کا سبب یہ بنا کہ ان کے گھوڑے کے رخسار والی لگام کٹ گئی۔ ادھر ابو سوید گھوڑی پر سوار تھے۔ انہوں نے سفیان کے گھوڑے کے قریب اپنی گھوڑی کر دی یہاں تک وہ اسے سونگھنے لگا پھر ابو سوید نے اپنی گھوڑی کو حرکت دی۔ اب سفیان کا گھوڑا اس کا پیچھا کرنے لگا تو سفیان لپک کر اسے روکنے گئے جس سے لگام کٹ گئی۔ اسی اثناء میں گھوڑا برابر اس کا تعاقب کرتا رہا بالآخر دونوں بچ گئے بعد میں سفیان مسلمان ہو گئے۔ میں کہتا ہوں: ابو سوید جن کا ابھی ذکر ہوا مجھے ان کا حال معلوم نہیں۔","",{"fn":"(1) مسلم کتاب الایمان باب جامع اوصاف الاسلام (۱۵۸) ترمذی کتاب الزہد باب ما جاء فی حفظ اللسان (۲۴۱۰) مسند احمد (۴۱۳/۳) المعجم الکبیر (۷۸/۷) المستدرک (۳۱۲/۴)"}],[3311,"§۳۳۱۷ ۔ سفیان بن عبد الاسد المخزومی(1)\nابو عمر(2) کا بیان ہے: تالیف قلبی والوں میں سے ہیں۔ نسب میں عدوی نے لکھا ہے یہ ابو سلمہ کے بھائی ہیں اور ان کے اسلام لانے کا ذکر نہیں کیا۔ ابن کلبی کی بات سے پتہ چلتا ہے کہ یہ اسلام لائے تھے ان کی پروردہ ام عمرو بنت سفیان کے حالات سے جو خواتین کے حصہ میں ہے ان کا تذکرہ لکھا جائے۔","",{"fn":"(1) اسد الغابہ (۲۱۱۵) استیعاب (۱۰۰۷)\n(2) اسد الغابہ (۱۹۰/۲)"}],[3312,"§۳۳۱۸ ۔ سفیان بن عبد شمس\nبن ابی وقاص زہری۔ قسم ثانی میں ان کے حالات دیکھیں۔ طبرانی کی روایت ہے کہ امیر معاویہ نے انہیں عمرو بن عاص کی جانب قاصد بنا کر بھیجا تھا کہ انہیں سیدنا علی رضی اللہ عنہ کی شہادت کی اطلاع دیں۔ سفیان بن امیہ کے سوانح میں گزر چکا ہے کہ اس طرح وہ حجاز کی جانب بھی اچھی بنا کر بھیجے گئے۔ حافظ ابن عساکر کا قول ہے: مجھے کتب انساب اور تاریخ میں ان کا ذکر نہیں ملا۔"],[3313,"§۳۳۱۹ ۔ سفیان بن العدیل\nبن حارث بن مصاد بن مازن بن ذویب بن کعب بن عمرو بن تمیم تمیمی۔ ابن سعد نے طبقات میں ان کا ذکر کیا ہے کہ سفیان بن عدیل نبی صلی اللہ علیہ وسلم کے پاس آئے اور اسلام قبول کر لیا۔ تو ان کا بیٹا قیس ان سے کہنے لگا: ابا جان! اپنے ساتھ مجھے بھی نبی صلی اللہ علیہ وسلم کے پاس جانے دیجئے۔ راوی کا بیان ہے کہ قیس کا انتقال سیدنا ابوبکر رضی اللہ عنہ کے دور میں بحرین میں علاء بن الحضرمی کے ساتھ ہوا جس کے متعلق کسی شاعر نے کہا: ع \"اگرچہ قیس اپنے راستے پہ چل نکلا تو قیس رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خوش ہو کر مسلمان ہوا تھا۔\" غنین میں ان کے بیٹے غنیم بن قیس کا ذکر ہوگا۔"],[3314,"§۳۳۲۰ ۔ سفیان بن ابی عزہ الجذامی\nبنی حنیفہ میں فروکش ہوئے اور مرتد نہیں ہوئے۔ دھیمہ نے اس کا ذکر کیا ہے اور لکھا ہے کہ سیدنا خالد بن ولید رضی اللہ عنہ نے اہل یمامہ کے جن لوگوں پر قابو پایا ان میں یہ بھی تھے۔ آپ نے انہیں قتل کرنا چاہا تو سفیان نے ان سے کہا: خالد! رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو بندہ کسی بندے کو قتل کرے گا تو قیامت کے روز وہ اس کے لیے پل صراط پر بیٹھے گا۔\" تو آپ صلی اللہ علیہ وسلم نے انہیں چھوڑ دیا۔ جس کے بارے شاعر کہتا ہے: ع \"میں، حصین اور ابن ابی عزہ سفیان، ہم سب کا دین اسلام ہے۔\""],[3315,"§۳۳۲۱ ۔ سفیان بن عطیہ(1)\nبن ربیعہ ثقفی۔ بغوی اور ان کے چچا احمد بن منیع بطریق ابن اسحاق(2) بحوالہ سفیان بن عطیہ بن ربیعہ ثقفی روایت کرتے ہیں کہ ثقیف کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ ابن ابی خیثمہ کا قول ہے: یہی عطیہ بن سفیان ہیں جو وفد ثقیف کے ساتھ آئے۔(3) میں کہتا ہوں: محفوظ یہ ہے کہ حدیث بروایت عیسیٰ بن عطیہ بن سفیان بن ربیعہ ثقفی بحوالہ وفد کے کسی فرد مروی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۲۱۱۷) استیعاب (۱۰۰۹)\n(2) السیرۃ النبویۃ (۱۴۳/۴)\n(3) جامع المسانید (۳۲۴/۵)"}],[3316,"§۳۳۲۲ ۔ سفیان بن عمیر بن وہب النضری\nسعد بن وہب میں ذکر ہوا۔"],[3317,"§۳۳۲۳ ۔ سفیان بن ابی العوجاء الثقفی(1)\nابن ابی عاصم نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور طبرانی(2) نے المعجم الکبیر میں صحابہ میں ان کا تذکرہ لکھا ہے، لیکن ان کا گمان ہے یہی ابو لیلیٰ انصاری ہیں جو عبد الرحمن کے والد ہیں۔ عسکری کا بیان ہے کہ جریر نے سفیان بن ابی زہیر کی حدیث میں روایت کی ہے کہ سفیان بن ابی العوجاء نے فرمایا۔","",{"fn":"(1) اسد الغابہ (۲۱۱۹)\n(2) المعجم الکبیر (۷۵/۷)"}],[3318,"§۳۳۲۴ ۔ سفیان بن عوف الاسلمی\nیا الغامدی۔ مالک بن وہب میں تذکرہ ہوگا۔ الحاکم مصعب زبیری سے روایت کرتے ہیں کہ سفیان بن عوف الغامدی صحابی رسول اللہ صلی اللہ علیہ وسلم ہیں۔ انہیں بڑا ادب، بہادری اور سخاوت حاصل تھی۔ انہوں نے ہی ہیت اور انبار پر سیدنا علی رضی اللہ عنہ کے دور میں حملہ کیا تھا اور مقابلوں کو قتل اور قید کیا تھا۔ سیدنا علی رضی اللہ عنہ اپنے خطبہ میں یہی مراد لیتے ہیں: غامد کے بھائی نے ہیت اور انبار پر حملہ کیا اور حسان بن حسان (جو سیدنا علی رضی اللہ عنہ کے گورنر تھے) کو قتل کیا۔ سیدنا امیر معاویہ رضی اللہ عنہ نے سفیان بن عوف کو صوائف کا والی بنا دیا اور ان کی بڑی قدر و منزلت کرتے تھے۔ پھر ان کے بعد ابن مسعود الغفاری کو گورنر بنا دیا۔ تو ایک شاعر نے ان سے کہا: ع \"ابن مسعود! لاٹھی کو ایسے ہی سیدھا رکھو جیسے سفیان بن عوف اسے قائم رکھتے تھے۔\" ابن عائذ کی روایت ہے کہ فرج بن محمد اپنے کسی شیخ سے نقل کرتے ہیں کہ ہم لوگ سفیان بن عوف الغامدی کے ساتھ روم کی زمین میں جا رہے تھے، تو انہوں نے \"باب الذہب\" پر حملہ کر دیا، یہاں تک کہ قسطنطنیہ والے باہر آ گئے، اور کہنے لگے: اللہ کی قسم! ہمیں معلوم نہیں تم لوگوں نے شمار میں غلطی کی ہے یا حساب کتاب غلط ہوگا۔ یا تم نے تقدیر سے پہل کر لی ہے۔ کیونکہ ہم اور تم جانتے ہو کہ یہ فتح ہوگا لیکن یہ اس کا وقت نہیں۔ ابن عساکر کا قول ہے: سفیان بن عوف الغامدی فتح شام میں شریک ہوئے پھر ایک روایت کی ہے کہ سفیان بن عوف الازدی نے فرمایا: ہمیں ابو عبیدہ نے سیدنا عمر رضی اللہ عنہ کے پاس خط دے کر بھیجا۔ خلیفہ کا بیان ہے یہ ترپن (۵۳ھ) میں اور ابو عبیدہ کا قول ہے باون (۵۲ھ) میں اور واقدی فرماتے ہیں: چون (۵۴ھ) میں فوت ہوئے۔ واللہ اعلم۔ ابن کلبی نے ان کا ذکر کیا تو فرمایا: سفیان بن عوف غامدی، صوائف والے ہیں۔"],[3319,"§۳۳۲۵ ۔ سفیان بن القرد\nیہی ابن ابی زہیر ہیں، پہلے ذکر ہوا ہے۔"],[3320,"§۳۳۲۶ ۔ سفیان بن قیس\nبن حارث بن مطلب قرشی مطلعی کی روایت ہے کہ ضحاک نامی ایک شخص سے مروی ہے جو عالم تھے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے حارث بن عبد المطلب اور سفیان بن قیس بن حارث کے درمیان بھائی چارہ قائم کیا۔"],[3321,"§۳۳۲۷ ۔ سفیان بن قیس بن ابان ثقفی\nطبرانی(1) وغیرہ نے صحابہ میں ان کا ذکر کیا ہے اور بحوالہ امیمہ بنت رقیقہ وہ رقیقہ سے روایت کرتی ہیں، فرمایا: رسول اللہ صلی اللہ علیہ وسلم طائف ثقیف کے پاس مدد طلب کرنے گئے، میرے پاس تشریف لائے تو میں نے آپ صلی اللہ علیہ وسلم کو ستو پلائے۔ آپ صلی اللہ علیہ وسلم نے ستو نوش کر کے فرمایا: “ان کے بت کی نہ عبادت کرنا اور نہ اس کی طرف رخ کر کے نماز پڑھنا”۔ میں نے عرض کی: تب تو یہ لوگ مجھے قتل کر دیں گے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اگر وہ تمہارے پاس آئیں تو کہو میرا رب وہی ہے جو اس بت کا رب ہے۔ اور نماز پڑھتے وقت اپنی پیٹھ اس کی طرف پھیر دو”۔ امیمہ کہتی ہیں: مجھ سے میرے بھائیوں وہب اور سفیان صاحبزدگان قیس نے بیان کیا کہ جب قبیلہ ثقیف مسلمان ہو گیا، تو نبی صلی اللہ علیہ وسلم نے ہم سے فرمایا: “تمہاری والدہ کا کیا ہوا؟” عرض کی: جس حال پر آپ صلی اللہ علیہ وسلم نے انہیں چھوڑا تھا اسی پر فوت ہوئی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “تب تو تمہاری والدہ مسلمان ہو گئی تھی”۔","",{"fn":"(1) المعجم الکبیر (الحدیث: ۶۴۳۱/۶)"}],[3322,"§۳۳۲۸ ۔ سفیان بن قیس الثعلبی\nبقول بغوی: امام بخاری(1) نے صحابہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) التاریخ الکبیر (۸۶/۲)"}],[3323,"§۳۳۲۹ ۔ سفیان(1)(2)\nبقول بعض: نفیر بن مجیب العمالی۔ ابن عساکر کا قول ہے: سفیان زیادہ صحیح ہے۔ ابن قانع وغیرہ نے بحوالہ حجاج بن عبید الثمالی روایت کی ہے، انہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا تھا اور آپ صلی اللہ علیہ وسلم کے ساتھ حجتہ الوداع میں شریک ہوئے تھے کہ سفیان بن مجیب نے ان سے بیان کیا وہ بھی صحابی رسول صلی اللہ علیہ وسلم تھے۔ فرمایا: “جہنم میں سات ہزار وادیاں ہیں”۔ (حدیث) ابن قانع کی روایت میں بخیت لکھا ہے۔ خطیب لکھتے ہیں مجیب درست ہے۔ ان کی حدیث کا دارو مدار اسمعیل بن عیاش پر ہے۔ اسمعیل سے آگے اختلاف ہے۔ چنانچہ ابوالیمان فرماتے ہیں: نفیر بن مجیب اور ہشیم بن خارجہ کا قول ہے: “سفیان”۔ ابو حاتم وغیرہ نے نفیر کے مقابلہ میں “سفیان” کو راجح قرار دیا ہے۔ اس سلسلہ میں دارقطنی منفرد ہیں۔ انہوں نے نفیر کو راجح قرار دیا ہے۔ مغازی میں ابن عائذ کی بطریق یزید بن ابی حبیب روایت ہے کہ عمرو بن عاص رضی اللہ عنہ نے امیر معاویہ رضی اللہ عنہ سے کہا: بعلبک والے سفیان ازدی کی طرف پیام بھیجیں کہ وہ اہل مصر میں سے خروج کرنے والوں کو بھیجیں، فرماتے ہیں: آپ نے سفیان بن مجیب کو بھیجا تو وہ عبدالرحمن بن عدیس کے تعاقب میں نکلے اور انہیں جا پایا۔ راوی کا بیان ہے امیر معاویہ نے حفصہ بنت امیہ بن حرب سے ان کی شادی کر دی۔ اسی طرح ابن عائذ بواسطہ ولید روایت کرتے ہیں کہ امیر معاویہ نے سفیان بن مجیب شمالی کو ایک جماعت کے ساتھ طرابلس بھیجا پھر ایک واقعہ نقل کیا۔","",{"fn":"(1) اسد الغابہ (۲۱۲۲)\n(2) التاریخ الکبیر (۱۲۴/۸) الجرح والتعدیل (۵۰۴/۸) الاکمال (۲۷۵/۷)"}],[3324,"§۳۳۳۰ ۔ سفیان بن معمر(1)(2)\nبن حبیب بن وہب بن حذافہ بن جمح قرشی تیمی۔ ابن اسحاق اور موسیٰ بن عقبہ نے بحوالہ ابن ہشام، مہاجرین حبشہ میں ان کا ذکر کیا ہے۔ ان کے ساتھ ان کی خوبصورت بیوی تھی جو شرحبیل کی والدہ ہے۔ زبیر بن بکار کا قول ہے: یہ جمیل بن معمر کے بھائی ہیں۔ ابن اسحاق کا بیان ہے کہ معمر نے سفیان کو لے پالک بنایا، اصل میں وہ انصار میں بنی زریق سے تھے۔ معمر سے عہد حلف کیا تو انہوں نے اپنا بیٹا بنا لیا۔ اسی بنا پر ان کی طرف منسوب ہونے لگے۔ لوگوں کا کہنا ہے کہ یہ سفیان اور ان کے دونوں بیٹے جابر اور جنادہ خلافت فاروقی میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۲۳) استیعاب (۱۰۱۱)\n(2) السیرۃ النبویہ (۶/۴، ۷/۴)"}],[3325,"§۳۳۳۱ ۔ سفیان بن نسر(1)\nبن زید بن حارث انصاری خزرجی از بنی جشم بن حارث، ابن اسحاق نے شرکاء اُحد میں ان کا ذکر کیا ہے۔ ان کے والد کے نام میں اختلاف ہے۔ بقول ابن کلبی، واقدی اور قداح: نسر نون اور سین سے ہے۔ ابن ماکولا(2) نے اسی کو درست کہا ہے۔ ابن اسحاق کا قول ہے: بشر باء کے زیر اور شین کے سکون سے ہے۔ ابن حبیب لکھتے ہیں: یہ غلط ہے اور ابو حاتم(3) فرماتے ہیں: اُحد میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۲۴)\n(2) الاکمال (۲۷۲/۱)\n(3) الجرح والتعدیل (۲۲۷/۴)"}],[3326,"§۳۳۳۲ ۔ سفیان بن ہمام(1)\nالمحاربی از محارب عبد القیس۔ بقول بعض: از محارب خصفہ۔ پہلا قول زیادہ صحیح ہے۔ ابن ابی عاصم، ابن السکن، طبرانی اور ابن شاہین بروایت یزید بن فضل بن عمرو بن سفیان بن ہمام وہ اپنے والد سے بحوالہ اپنے دادا سفیان بن ہمام روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: “اپنی قوم کو مٹکے میں نبیذ بنانے سے منع کرنا”۔(2) ابن اسکن کی روایت میں صرف عن ابیہ عن جدہ لکھا ہے۔ اسی روایت پر بزار نے اعتماد کیا ہے۔ چنانچہ یہ حدیث مسند عمرو بن سفیان میں روایت کر کے لکھا ہے۔ ہمیں معلوم نہیں کہ عمرو بن سفیان نے اس کے علاوہ کوئی حدیث نقل کی ہو۔ ابو عمر(3) نے بھی انہی کا اتباع کیا ہے۔ اور لکھا ہے: عمرو بن سفیان المحاربی سے مٹکے کی نبیذ کے بارے ایک روایت نقل کی جاتی ہے کہ حرام ہے۔ اہل شام میں شمار ہوتے ہیں۔ البتہ ابن مندہ کا قول ہے: عمرو بن سفیان المحاربی نے نبی صلی اللہ علیہ وسلم سے سماع کیا ہے۔ بصرہ کے اعرابیوں میں شمار ہوتے ہیں۔ پھر اسی طرح جس طرز پر بزار نے کی ان کی حدیث نقل کی۔ بعد میں انہوں نے مذکورہ حدیث اسی سند سے روایت کی ہے جو “سفیان بن ہمام” کے حالات میں ہے اور دونوں جگہ اس میں اختلاف کو نہیں بیان کیا۔ یہی صورتحال ابو عمر کے ساتھ پیش آئی۔ چنانچہ انہوں نے سفیان بن ہمام العبدی جو قیس سے ہیں، کے حالات میں لکھا ہے: مٹکے کی نبیذ کے متعلق حدیث روایت کرتے ہیں۔ ان سے ان کا بیٹا عمرو بن سفیان روایت کرتا ہے۔ لیکن وضاحت نہ انہوں نے کی اور نہ ابن الاثیر نے۔","",{"fn":"(1) اسد الغابہ (۲۱۲۷) استیعاب (۱۰۱۲) تجرید (۲۲۷/۱)\n(2) المعجم الکبیر (۶۴۰۳/۷) مجمع الزوائد (۶۱/۵) جامع المسانید (۳۲۷/۵)\n(3) استیعاب (۱۹۲/۲)"}],[3327,"§۳۳۳۳ ۔ سفیان بن وہب الخولانی(1)(4)\nابو ایمن۔ بقول ابو حاتم(2) انہیں شرف صحابیت حاصل ہے۔ امام بخاری رحمہ اللہ اپنی تاریخ میں بطریق عیاث الحرانی روایت کرتے ہیں کہ سفیان بن وہب کا ہمارے ہاں سے گزر ہوا وہ صحابی تھے انہوں نے ہمیں سلام کیا۔ ابن یونس فرماتے ہیں: نبی صلی اللہ علیہ وسلم کے پاس آئے اور فتح مصر میں شریک ہوئے اور افریقا کے والی مقرر ہوئے۔ یہ عبد العزیز بن مروان کا دور تھا۔ بیاسی (۸۲ھ) میں وفات پائی۔ سیدنا عمر اور زبیر رضی اللہ عنہما وغیرہ سے روایت کرتے ہیں۔ ان سے بکر بن سوادہ، عبد اللہ بن مغیرہ، ابوالخیر اور ابوعشانہ وغیرہ روایت کرتے ہیں۔ حسن بن سفیان اور ابن شاہین بطریق سعید بن ابی شمر سبائی روایت کرتے ہیں کہ میں نے سفیان بن وہب خولانی کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “صدی گزرنے پر اس زمین پر ان زندہ لوگوں میں سے کوئی بھی باقی نہیں رہے گا”۔ فرماتے ہیں: میں نے یہ حدیث عبد العزیز سے بیان کی تو انہوں نے کہا: آپ صلی اللہ علیہ وسلم کی مراد ہے کہ اس وقت جو آپ کے ساتھ موجود ہیں، ان میں سے کوئی بھی صدی کے آغاز تک زندہ نہیں رہے گا۔ ان کی دوسری حدیث مسند احمد میں اور تیسری حدیث ابن مندہ کی کتاب میں اور ایک حدیث بحوالہ عمر مسند ابی یعلی میں ہے۔(3) ابن حبان فرماتے ہیں: جس کا گمان ہے کہ یہ صحابی ہیں تو اسے وہم ہوا۔ تابعین میں انہوں نے ایسا ہی لکھا ہے اور اس سے پہلے “الصحابہ” میں لکھتے ہیں: مصر کے باسی تھے۔ صحابی ہیں۔ جبکہ عجلی کا قول ہے: معتبر تابعی ہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۲۸) استیعاب (۱۰۱۳)\n(2) الجرح والتعدیل (۲۱۷/۴)\n(3) المعجم الکبیر (۶۴۰۵/۷) (۶۴۰۶/۷) مجمع الزوائد (۶۱/۵) جامع المسانید (۳۲۷/۵)\n(4) الثقات (۱۸۳/۳)"}],[3328,"§۳۳۳۴ ۔ سفیان بن یزید\nابن زید میں تذکرہ ہو چکا ہے۔"],[3329,"§۳۳۳۵ ۔ سفیان الہذلی\nنضر کے والد، ابو عمر نے ان کا مختصر ذکر کیا ہے۔ قسم ثالث میں ان کا ذکر ہوگا۔"],[3330,"§۳۳۳۶ ۔ سفینہ(1)\nمولا رسول اللہ صلی اللہ علیہ وسلم۔ بقول بعض ان کا نام(۱) مہران،(۲) طہمان،(۳) مروان،(۴) نجران،(۵) رومان،(۶) ذکوان،(۷) کیسان،(۸) سلیمان،(۹) سنہ،(۱۰) ایمن،(۱۱) فرقتنہ،(۱۲) احمر،(۱۳) احمد،(۱۴) رباح،(۱۵) مفلح،(۱۶) عمیر،(۱۷) معتب،(۱۸) قیس،(۱۹) عبس،(۲۰) عیسی،(۲۱) شنہ۔ کل اکیس(۲۱) اقوال ہیں۔ اصل میں فارس کے تھے۔ ام سلمہ رضی اللہ عنہا نے انہیں خرید کر اس شرط پر آزاد کیا کہ وہ نبی صلی اللہ علیہ وسلم کی خدمت بجالائیں گے۔ نبی صلی اللہ علیہ وسلم، ام سلمہ، اور سیدنا علی رضی اللہ عنہ سے روایت کرتے ہیں جبکہ ان سے ان کے دونوں بیٹے عبدالرحمن اور عمر، سالم بن عبداللہ بن عمر، ابوریحانہ وغیرہ روایت کرتے ہیں۔ حماد بن سلمہ بواسطہ سعید بن جہمان بحوالہ سفینہ روایت کرتے ہیں: میں ایک سفر میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا، لوگوں میں سے کوئی تھک جاتا تو اپنا کپڑا مجھ پر ڈال دیتا یہاں تک کہ میں نے بہت بوجھ اٹھا لیا۔ نبی صلی اللہ علیہ وسلم نے یہ صورتحال دیکھی تو فرمایا: “تم تو بحری جہاز ہو”۔(2) وہ بطن نخلہ میں رہتے تھے۔","",{"fn":"(1) اسد الغابہ (۲۱۳۰) استیعاب (۱۱۴۰) تجرید (۲۳۸/۱)\n(2) مسند احمد (۲۲۱/۵) المعجم الکبیر (۸۵/۷) جامع المسانید (۳۳۵/۵، ۳۳۶)"}],[3331,"§۳۳۳۷ ۔ سکبہ بن الحارث الاسلمی(1)(2)\nمسدد نے اپنی مسند میں بطریق زیاد بن مخراق بحوالہ اسلم کے ایک شخص روایت کی ہے کہ ہم میں سے تین شخص اصحاب رسول صلی اللہ علیہ وسلم ہیں: بریدہ، محجن اور سکبہ۔ ابن شاہین کی روایت ہے کہ عمران بن حصین رضی اللہ عنہ مسجد میں داخل ہوئے تو سکبہ بن حارث نماز پڑھ رہے تھے اور بریدہ بیٹھے ہوئے تھے۔ آپ نے فرمایا: بریدہ! تم ایسے نماز کیوں نہیں پڑھتے جیسے سکبہ پڑھ رہے ہیں تو بریدہ نے انہیں کوئی جواب نہ دیا۔ اس کے بعد وہ مسجد کے دروازے پر آئے اور بیان کیا کہ وہ نبی صلی اللہ علیہ وسلم کے ساتھ باہر نکلے۔ ہمارے سامنے اُحد کا پہاڑ تھا، آپ صلی اللہ علیہ وسلم نے وہاں سے مدینہ کو جھانک کر دیکھا، پھر فرمایا: “بستی کے لئے ہلاکت ہے”۔ پھر نیچے اتر آئے، مسجد کے دروازے پر پہنچے تو ایک شخص نماز پڑھ رہا تھا، پوچھا: یہ کون ہے؟ میں نے عرض کی یہ فلاں شخص ہے جس کا اس طرح اس طرح کا کام ہے۔ آپ صلی اللہ علیہ وسلم نے میرا ہاتھ چھوڑ دیا اور اندر داخل ہو کر فرمانے لگے: “تمہارا بہترین (حصہ) دین وہ ہے جو سب سے آسان ہو”۔(3) ابو داؤد طیالسی نے اپنی مسند میں ابو بشر کے حوالہ سے نقل کیا ہے لیکن اس میں لکھا ہے ابن شقیق بحوالہ رجاء اسلمی روایت کرتے ہیں کہ میں مجن اسلمی کے ساتھ چلتے چلتے مسجد تک پہنچا وہاں ہمیں بریدہ مل گئے۔ پھر وہ حدیث ذکر کی۔ اس میں ہے، بریدہ نے کہا: مجن تم ایسے نماز کیوں نہیں پڑھ رہے جیسے سکبہ پڑھ رہا ہے؟ تو انہوں نے کوئی جواب نہ دیا۔ پھر مجن نے فرمایا رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ تھاما۔ دونوں حدیثوں(4) میں ایک ذکر کیا۔ اخبار مدینہ میں عمر بن شبہ نے بطریق جریر مودب کی روایت کا مفہوم لکھا ہے اور یہ اضافہ بھی نقل کیا ہے تو بریدہ بیٹھے ہوئے تھے، سکبہ صحابی رسول تھے جو کھڑے ہو کر چاشت کی نماز پڑھ رہے تھے۔ تو بریدہ نے کہا: عمران تم ایسے نماز کیوں نہیں پڑھ رہے جیسے سکبہ پڑھ رہے ہیں؟ تو عمران خاموش رہے۔ پھر ہم وہاں سے چلے تو عمران نے کہا: ایک دفعہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہا تھا۔ پھر اس کا ذکر کیا۔ اس کے بعد بطریق شعبہ بحوالہ رجاء بن ابی رجاء الباہلی روایت کی کہ مجن مسجد میں داخل ہوئے تو بریدہ کو دیکھ کر فرمایا تم ایسے نماز کیوں نہیں پڑھتے جیسے سکبہ پڑھ رہے ہیں۔ وہ خزاعہ کے ایک فرد تھے۔ پھر فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ تھاما۔ پھر حدیث ذکر کی۔ اور بطریق ہمس بواسطہ عبد اللہ بن شقیق بحوالہ مجن بن الادرع روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسی کام سے بھیجا، پھر مجھے ملے تو میں مدینہ کی کسی راہ میں تھا.... (حدیث) اور بطریق جریری بواسطہ عبد اللہ بن شقیق بحوالہ مجن اس کا مفہوم مروی ہے۔ احمد بن منبع اپنی مسند میں بطریق عیینہ بن عبد الرحمن بواسطہ اپنے والد بحوالہ بریدہ اسلمی روایت کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے ساتھ تھا، آپ ایک شخص کے پاس آئے مجھ سے فرمانے لگے: کیا یہ تمہیں ریا کار (دکھاوے کی عبادت کرنے والا) لگتا ہے؟(5) میں نے عرض کی: یہ واقعی ایسا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “تم لوگ میانہ روی اختیار کرو اور اس دین سے (اس کی حد سے زیادہ) جو بھی (عبادت یا عمل کر کے اس سے) مقابلہ کرے گا تو دین ہی غالب رہے گا”۔","",{"fn":"(1) اسد الغابہ (۲۱۳۱) استیعاب (۱۱۴۲)\n(2) مسند احمد (۲۲۰/۵ - ۲۲۲) المعجم الکبیر (۶۴۴۰/۷)\n(3) المعجم الکبیر (۲۳۰/۱۸)\n(4) مسند ابوداؤد طیالسی (۱۲۹۵)\n(5) مسند احمد (۱۹۸۰۷)"}],[3332,"§۳۳۳۸ ۔ السکران بن عمرو(1)\nبن عبد شمس بن عبدود بن مالک بن نصر بن حسل بن عامر بن لوی قرشی عامری، سہیل بن عمرو کے بھائی۔ موسیٰ بن عقبہ نے مہاجرین حبشہ میں ایسا ہی ابن اسحاق(2) نے ان کا ذکر کیا ہے۔ البتہ یہ اضافہ نقل کیا ہے کہ پھر یہ مکہ لوٹ آئے اور وہیں فوت ہوئے۔ تو آپ صلی اللہ علیہ وسلم نے ان کے بعد ان کی اہلیہ سودہ بنت زمعہ سے نکاح کر لیا تھا۔ اور آپ سے یہ نکاح سیدہ سودہ کے بھائی حاطب نے کیا تھا۔ ابو عبیدہ کا گمان ہے کہ جب یہ حبشہ آئے تو نصرانی ہو گئے تھے اور وہیں وفات پائی۔ بلاذری کا قول ہے: پہلا قول زیادہ صحیح ہے۔ بقول بعض: یہ حبشہ میں فوت ہوئے تھے۔","",{"fn":"(1) اسد الغابہ (۲۱۳۲) استیعاب (۱۱۴۱)\n(2) السیرۃ النبویہ (۸/۲)"}],[3333,"§۳۳۳۹ ۔ السکن\nبقول بعض: یہ سیدنا ابوذر غفاری رضی اللہ عنہ کا نام ہے۔ بقول بعض: ان کے والد کا نام ہے۔ انشاء اللہ تعالیٰ کنیتوں میں تذکرہ ہوگا۔"],[3334,"§۳۳۴۰ ۔ السکین الضمری(1)(4)\nتصغیر “اسکن” کا بھی قول ہے۔ بقول ابو حاتم(2) انہیں شرف صحابیت حاصل ہے۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں اور ابن ابی خیثمہ نے بطریق ابن جریج بواسطہ عطاء بن یسار ایک حدیث روایت کی ہے کہ میں نے سکین مصری کو فرماتے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا کہ مومن ایک آنت میں کھاتا ہے۔ (حدیث)(3) یہی روایت صفوان بن ہبیرہ نے ابن جریج سے بواسطہ سہیل بحوالہ عطاء نقل کی ہے۔ اور موسیٰ بن عبیدہ نے عطاء انہوں نے حجاج سے نقل کی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۲۱۳۳)\n(2) التاریخ الکبیر (۱۹۸/۴)\n(3) جامع المسانید (۳۴۳/۵) اسد الغابہ (۳۴۴/۲) تاریخ بغداد (۳۱۳/۱۰)\n(4) اسد الغابہ (۲۲۷۰)"}],[3335,"§۳۳۴۱ ۔ سلام (تشدید کے بغیر)\nعبد اللہ بن سلام کے بھانجے۔ سلیمہ عبد اللہ بن سلام کے بھتیجے کے حالات میں تذکرہ ہوگا۔"],[3336,"§۳۳۴۲ ۔ سلام (تشدید)(1)\nابن عمرو۔ ان کے صحابی ہونے میں اختلاف ہے۔ ابن حبان نے تابعین میں ان کا ذکر کیا ہے۔ ابن مندہ نے بطریق ابو عوانہ بواسطہ ابو بشر بحوالہ سلام بن عمرو روایت کی ہے، جو صحابی رسول صلی اللہ علیہ وسلم ہیں، فرمایا: “کتے ناپاک ہیں، صرف شکاری کتا رکھنا جائز ہے”۔ ابن مندہ کا قول ہے: اسے شعبہ نے بواسطہ ابو بشر، سلام بن عمرو بحوالہ ایک صحابی رسول صلی اللہ علیہ وسلم روایت کیا ہے۔ ابن مندہ فرماتے ہیں: یہی درست ہے۔(2) مسند احمد اور الادب المفرد للبخاری میں بطریق شعبہ اسی سند سے دوسرا متن منقول ہے۔","",{"fn":"(1) اسد الغابہ (۳۴۵/۲)\n(2) مسند احمد (۵۷/۵)"}],[3337,"§۳۳۴۳ ۔ سلام بن قیس الحضرمی\nآخر میں تذکرہ ہوگا۔"],[3338,"§۳۳۴۴ ۔ سلامہ بن سالم الثعلبی\nسلمہ بن سلامہ میں ذکر ہوگا۔"],[3339,"§۳۳۴۵ ۔ سلامہ بن عبداللہ(1)\nابن مندہ کی عمرو بن سلامہ سے بحوالہ ان کے والد روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اللہ تعالیٰ نے جنت الفردوس کی عمارت کو ایک اینٹ سونے اور ایک اینٹ مشک سے بنایا ہے۔” (حدیث)(2) ابن مندہ فرماتے ہیں: ان کا صحابی ہونا صحیح نہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۳۷)\n(2) حلیۃ الاولیاء (۹۵/۳) کنز العمال (۱۳۱۸۵)"}],[3340,"§۳۳۴۶ ۔ سلامہ بن عمیر الاسلمی\nبقول بعض: یہ ابو حدرد اسلمی کا نام ہے، کنیتوں میں تذکرہ ہوگا۔"],[3341,"§۳۳۴۷ ۔ سلامہ بن قیصر(1)\nبقول بعض: سلمہ، مصر فروکش ہوئے۔ احمد بن صالح کا قول ہے: یہ صحابی نہیں جبکہ ابو زرعہ اس کا انکار کرتے ہیں۔ ابن صالح لکھتے ہیں: ہمارے نزدیک سلمہ صحیح ہے اور یہ صحابی ہیں۔ امام بخاری رحمہ اللہ فرماتے ہیں: ان کی حدیث صحیح نہیں۔(2) مطین، حسن بن سفیان اور طبرانی(3) نے بطریق عمرو بن ربیعہ الحضرمی ان کی حدیث نقل کی ہے کہ میں نے سلامہ بن قیصر کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “جس نے اللہ کی رضا مندی کی خاطر روزہ رکھا اللہ تعالیٰ اس میں اور جہنم میں اتنا فاصلہ پیدا کر دے گا جتنے میں کسی کوے کا چوزہ اڑے اور بڑھاپے تک اڑتا رہے۔ اس حدیث کا مدار ابن لہیعہ پر ہے۔ چنانچہ ابن وہب اور ان کے دوسرے شاگردوں نے اسی طرح روایت کی ہے۔ ابن وہب کی روایت مسند ابی یعلی میں ہے اور عبد اللہ بن یزید المقری بحوالہ ان کے اس سند سے یوں نقل کرتے ہیں: سلمہ بن قیصر سے بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ مروی ہے۔ انہی سے امام احمد نے اپنی مسند میں روایت کی ہے اور ابو زرعہ نے اس اضافہ کو راجح قرار دیا ہے، جبکہ احمد بن صالح نے اس کا انکار کیا ہے۔ میں نے ابن عبد البر(4) کے قلم سے لکھا ہوا پڑھا ہے: خلف بن قاسم نے ہمیں بحوالہ ابو بکر بن خروف بیان کیا کہ میں نے احمد بن صالح سے پوچھا: تو انہوں نے کہا: المقری نے کوئی کارنامہ سرانجام نہیں دیا۔ ابن رشدین کا قول ہے کہ احمد بن صالح نے فرمایا: یہ المقری کی غلطی ہے۔ ابن یونس لکھتے ہیں: سلامہ بن قیصر، بقول بعض: سلمہ بن قیصر الحضرمی صحابی رسول صلی اللہ علیہ وسلم ہیں۔ ان سے عمرو بن ربیعہ، مرثد ابوالخیر الیزنی روایت کرتے ہیں۔ ابن حبان نے صحابہ میں ان کا ذکر کیا ہے کہ مصر رہتے ان کی حدیث وہاں کے لوگوں سے مروی ہے، بیت المقدس میں فوت ہوئے اور وہیں ان کی قبر ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۳۸) استیعاب (۱۱۴۴) تجرید (۲۲۹/۱)\n(2) التاریخ الکبیر (۱۹۴/۲)\n(3) المعجم الکبیر (۶۳۶۵/۷) المعجم الاوسط (۱۲۸)\n(4) استیعاب (۲۴۵/۲)"}],[3342,"§۳۳۴۸ ۔ سلامۃ العذری(1)\nانہیں المہلب کہا جاتا ہے۔ علی بن حرب نے “کتاب النجار” میں ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ یہ رشاطی کا قول ہے، بقول بعض قبیصہ جن کا تذکرہ ہوتا ہے ان کے والد ہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۴۰)"}],[3343,"§۳۳۴۹ ۔ سلم (بے نسب)\nابوداؤد نے سنن میں بغیر سند ان کا ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ایک شخص کا نام حرب تبدیل کر کے فرمانے لگے: “تم سلم ہو”۔"],[3344,"§۳۳۵۰ ۔ سلم بن سمی\nبن حارث ازدی ثم الدوسی ابوالعکر کنیت سے مشہور ہیں، کنیتوں میں ذکر ہوگا۔"],[3345,"§۳۳۵۱ ۔ سلکان بن سلامہ\nابو نائلہ کنیتوں میں ذکر ہوگا۔"],[3346,"§۳۳۵۲ ۔ سلکان بن مالک(1)\nابن الدباغ نے استیعاب کے استدراک میں ان کا ذکر کیا ہے کہ واقدی نے انہیں مصر داخل ہونے والے صحابہ رضی اللہ عنہم میں ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۴۲)"}],[3347,"§۳۳۵۳ ۔ سلمان بن ثمامہ(1)\nبن شراحیل ابن الاصہب الجعفی۔ بقول ابن مندہ کہ سلمان نبی صلی اللہ علیہ وسلم کے پاس آئے اور حضور کی معیت میں جنگ کی اور رقہ(2) میں فروکش ہوئے۔ ابن کلبی کا بیان ہے: فتنہ وفساد کے دور میں وہ اور جن لوگوں کو ان میں جنگ کرنے سے تردد تھا وہ اس میں قتال سے باز رہے۔ اور سارے رقہ میں ٹھہر گئے۔ سیدنا علی رضی اللہ عنہ ان کی طرف عطیات بھیجتے اور فرماتے: “ہم تمہیں غنیمت کے حق سے محروم نہیں رکھتے، کیونکہ تم لوگ مسلمان ہو، اگرچہ تم ہماری مدد سے باز رہتے ہو”۔ راوی کا بیان ہے کہ سلمان ان لوگوں کے ساتھ جنہوں نے حجر بن عدی کے ساتھ زیاد کے خلاف مہم چلائی تھی، پھر جب زیاد نے حجر بن عدی اور ان کے ساتھیوں کو گرفتار کر لیا تو سلمان چھوٹ گئے۔ ان کے دادا شراحیل جاہلیت میں سردار تھے۔ اصہب ان کے والد نہیں بلکہ ان کے پردادا ہیں، وہ شراحیل بن شیطان بن حارث بن اصہب ہے۔ ان کا نام عوف بن کعب بن حارث بن سعد بن عمرو بن ذہل مران بن جعفی بن سعد العشیرہ ہے۔ وہ بہت غارتگری کرتے۔ بنی جعدہ نے انہیں قتل کر دیا، جس کے بارے ان کے قتل پر فخر کرتے ہوئے نابغہ جعدی کہتا ہے:(3) “ہمیں شراحیل کے شر سے معد نے آرام پہنچایا، جب اسے صبح کے چمکتے ستاروں کے ساتھ دیکھا”۔","",{"fn":"(1) اسد الغابہ (۲۱۴۴)\n(2) اسد الغابہ (۳۴۶/۲)\n(3) اسد الغابہ (۲۱۴۵) تجرید (۲۲۹/۱)"}],[3348,"§۳۳۵۴ ۔ سلمان بن خالد الخزاعی(1)\nطبرانی نے صحابہ میں ان کا ذکر کیا ہے اور سلمان بن خالد سے جنہیں میں قبیلہ خزاعہ کا سمجھتا ہوں روایت کی ہے، فرمایا: میری خواہش ہے کہ میں نماز پڑھ کر راحت حاصل کرلوں، اس واسطے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “اے بلال! اٹھو، نماز قائم کرو اور ہمیں راحت پہنچاؤ”(2) سالم بن ابی الجعد خزاعہ کے ایک بے نام شخص سے روایت کرتے ہیں اور عبد اللہ بن محمد بن الحنفیہ بحوالہ اپنے والد وہ ایک بے نام صحابی سے روایت کرتے ہیں، اور ابوحمزہ ثمالی، عبد اللہ سے بواسطہ اپنے والد وہ اپنے اسلم کے ایک سسرالی رشتہ دار سے روایت کرتے ہیں۔","",{"fn":"(1) المعجم الکبیر (۶۲۱۴/۶)\n(2) ابوداؤد کتاب الادب، باب فی صلاۃ العتمۃ (۴۹۸۵، ۴۹۸۶) مسند احمد (۳۶۴/۴)"}],[3349,"§۳۳۵۵ ۔ سلمان بن ربیعہ(1)\nبن یزید بن عمرو بن سہم بن ثعلبہ الباہلی۔ ان کے صحابی ہونے میں اختلاف ہے۔ بقول ابو حاتم(2) انہیں شرف صحابیت حاصل ہے، کنیت ابو عبد اللہ تھی۔ ابو عمر(3) فرماتے ہیں: عقیلی نے صحابہ میں ان کا ذکر کیا ہے، میرے نزدیک بھی یہی ہے جو ابو حاتم نے کہا۔ ابن مندہ کا قول ہے: امام بخاری نے صحابہ(4) میں ان کا ذکر کیا ہے، لیکن صحیح نہیں۔ انہیں “سلمان الخیل” کہا جاتا تھا۔ ان سے اکابر تابعین جیسے ابو وائل، ابو میسرہ، ابو عثمان نہدی، سوید بن غفلہ روایت کرتے ہیں۔ فتوحات شام میں شریک ہوئے، پھر عراق رہنے لگے۔ اور خلافت عثمانی میں ارمینیا کی جنگ کے ذمہ دار بنے۔ تیس یا اس کے بعد کی عمر میں شہید ہوئے۔ بقول بعض یہ پہلے شخص ہیں جنہوں نے گھوڑوں کی عتاق اور ہجین میں فرق کیا۔ اسی بنا پر انہیں “سلمان الخیل” کہا جاتا ہے۔(5) ثقات التابعین میں ابن حبان نے لکھا ہے، خلافت فاروقی میں گھوڑوں کی ذمہ داری سنبھالی۔ پہلے شخص ہیں جن سے کوفہ(6) کا قاضی بننے کا مطالبہ ہوا۔ نیک شخص تھے، ہر سال حج کرتے۔ ابن سعد اور عجلی نے بھی تابعین میں ان کا ذکر کیا ہے۔ آجری بحوالہ ابوداؤد روایت کرتے ہیں، بہت کم روایتیں کی ہیں۔ ابو وائل سے منقول ہے: چالیس روز میں سلمان بن ربیعہ کے پاس جاتا رہا، میں نے ان کے پاس کوئی فیصلہ کرانے والا نہیں پایا۔ صحیح مسلم میں ان کی روایت سے بحوالہ عمر رضی اللہ عنہ ایک حدیث ہے۔ لقطہ کی حدیث میں ان کا ذکر ہے، سلمہ بن کہیل بحوالہ سوید بن غفلہ روایت کرتے ہیں کہ مجھے ایک کوڑا ملا جسے میں نے اٹھا لیا تو زید بن صوحان اور سلمان بن ربیعہ مجھے ملامت کرنے لگے۔ میں نے ابی بن کعب سے اس کا ذکر کیا تو انہوں نے فرمایا: تم نے بہتر اور سنت کے مطابق کیا۔ یہ روایت بخاری وغیرہ میں ہے۔ ابو موسیٰ کے واقعہ میں بھی ان کا ذکر آتا ہے جب ان سے کسی نے پوچھا کہ بیٹی اور پوتی کا کیا حصہ ہے؟ تو سلمان بن ربیعہ نے تقسیم میں ان کی موافقت کی۔ یہی مسئلہ ابن مسعود رضی اللہ عنہ سے پوچھا گیا تو آپ نے دونوں حضرات کے مخالف تقسیم کی۔ نسائی نے یہ روایت نقل کی جس کی اصل بخاری میں ہے۔ یہ واقعہ خلافت عثمانی میں پیش آیا۔","",{"fn":"(1) اسد الغابہ (۲۱۴۶) استیعاب (۱۰۱۶)\n(2) الجرح والتعدیل (۲۹۷/۴)\n(3) استیعاب (۱۹۳/۲)\n(4) التاریخ الکبیر (۱۳۶/۲)\n(5) الثقات (۳۳۲/۴)\n(6) مختصر تاریخ دمشق (۵۶/۱۰)"}],[3350,"§۳۳۵۶ ۔ سلمان بن صخر البیاض\nایسا ہی تجرید میں لکھا ہے، یہی سلمہ بن صخر ہیں تذکرہ ہوتا ہے۔"],[3351,"§۳۳۵۷ ۔ سلمان بن عامر(1)\nبن اویس بن حجر بن عمرو بن حارث بن تیم بن ذہل بن مالک بن بکر بن سعد بن ضبہ الضبی۔ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں ان سے ان کی بھتیجی ام الربیع جن کا نام رباب بنت صلح تھا اور پوتا عبد العزیز بن بشر بن سلمان الفسی(2) روایت کرتا ہے۔ دارقطنی نے جو کتاب ضبیوں کے لیے لکھی ہے اس میں یہ وضاحت موجود ہے کہ یہ نبی صلی اللہ علیہ وسلم کے دور میں بزرگ تھے۔ اسی طرح ان سے ابن سیرین اور ان کی بہن حفصہ بنت سیرین روایت کرتی ہیں۔ بصرہ رہائش رکھتے تھے۔ جس کا گمان ہے کہ خلافت فاروقی میں فوت ہو گئے تھے۔ اسے وہم ہوا ہے درست یہ ہے کہ خلافت معاویہ تک حیات رہے۔ الصریفینی کی کتاب میں ہے کہ خلافت عثمانی میں فوت ہوئے۔ امام مسلم رحمہ اللہ فرماتے ہیں: صحابہ رضی اللہ عنہم میں ان کے علاوہ کوئی ضبی نہیں ہیں۔ ایسا ہی ابن الاثیر نے نقل کیا ہے(3) جسے انہوں نے اور ان کے متبعین نے برقرار رکھا ہے، صحابہ میں ایسے لوگوں کی پوری جماعت موجود ہے جنہیں شرف صحابیت حاصل ہے اور ان کے صحابی ہونے میں اختلاف ہے ہیں وہ بنی ضبہ سے۔ جن میں سے یزید بن نعامہ ہیں۔ امام بخاری رحمہ اللہ نے اس پر بھروسا ظاہر کیا ہے کہ انہیں شرف صحابیت حاصل ہے اسی کتاب میں بہت سے صحابہ کو ذکر کیا گیا ہے ان میں سے کدیر ضبی اور حنظلہ بن ضرار ہیں۔","",{"fn":"(1) اسد الغابہ (۲۱۴۸) استیعاب (۱۰۱۸) تجرید (۲۳۰/۱)\n(2) المعجم الکبیر (۳۳۴/۶)\n(3) اسد الغابہ (۲۴۷/۲)"}],[3352,"§۳۳۵۸ ۔ سلمان ابو عبداللہ الفارسی(1)\nانہیں سلمان ابن الاسلام اور سلمان الخیر بھی کہا جاتا ہے۔ بقول ابن حبان(2): کہ جس کا یہ گمان ہے سلمان الخیر اور ہیں اسے وہم ہوا ہے۔ اصلاً رامہرمز کے تھے۔ بقول بعض: اصبہان کے تھے۔ انہوں نے سن رکھا تھا کہ نبی صلی اللہ علیہ وسلم نے مبعوث ہونا ہے۔ جس کی تلاش میں گھر سے نکل کھڑے ہوئے، گرفتار ہو کر مدینہ کے بازار بیچ دیئے گئے۔ اور غلامی میں مشغول ہو گئے۔ پھر سب سے پہلے غزوہ خندق کا مشاہدہ کیا۔ اس کے بعد بقیہ معرکوں میں بھی شرکت کی۔ فتوحات عراق میں مردانہ وار لڑے اور مدائن کے والی مقرر ہوئے۔ ابن عبد البر(3) کا قول ہے: بقول بعض بدر میں شریک ہوئے۔ عالم اور دنیا سے بے رغبت انسان تھے۔ ان سے سیدنا انس، کعب بن عجرہ، ابن عباس، ابو سعید وغیرہ صحابہ کرام رضی اللہ عنہم اور تابعین میں سے ابو عثمان نہدی، طارق بن شہاب اور سعید بن المسیب روایت کرتے ہیں۔ بقول بعض: پہلا نام ماہ ابن بوذخشان تھا۔ یہ ابن مندہ کا اپنی سند سے نقل کردہ قول ہے اور انہوں نے ہی ان کا نسب لکھا ہے۔ ایک قول ہے، نام بہبوذ تھا۔ بقول بعض: انہوں نے عیسی ابن مریم علیہ السلام کا زمانہ پایا ہے۔ ایک قول ہے، نہیں بلکہ آپ نے عیسی علیہ السلام کے حواری (حواری) کا زمانہ پایا ہے۔ ان کا واقعہ کئی طرق سے مروی ہے، سب سے بہتر وہ ہے جسے امام احمد رحمہ اللہ نے خود انہی کی حدیث سے نقل کیا ہے۔ اسی واقعہ کو الحاکم نے دوسری سند کے ذریعہ بحوالہ ان کے روایت کیا ہے اور حاکم نے حدیث بریدہ سے اور امام بخاری رحمہ اللہ نے اس کا ایک ٹکڑا تعلیقاً نقل کیا ہے۔ ان کے اسلام لانے میں اتنا اختلاف ہے کہ ان تمام روایات کو یکجا کرنا مشکل ہے۔ امام بخاری رحمہ اللہ نے اپنی صحیح میں سیدنا سلمان فارسی رضی اللہ عنہ کے حوالہ سے روایت نقل کی ہے کہ انہیں دس سے زائد آقاؤں نے ہاتھ در ہاتھ بیچا۔ ذہبی(4) لکھتے ہیں: مجھے ان کی عمر کے بارے جتنے اقوال ملے ہیں ان سب سے پتہ چلتا ہے کہ وہ ڈھائی سو(۲۵۰) سال سے زائد عمر کے تھے۔ اختلاف جو ہے وہ زائد میں ہے، فرماتے ہیں: پھر میں نے اس سے رجوع کر لیا اور میرے لیے ظاہر ہو گیا کہ وہ اتنی(۸۰) سے زائد سن تک نہ پہنچے۔(5) میں کہتا ہوں: انہوں نے اس بارے میں مستند روایت کا حوالہ نہیں دیا، مجھے لگتا ہے انہوں نے یہ بات سیدنا سلمان رضی اللہ عنہ کی نبی صلی اللہ علیہ وسلم کے بعد کی فتوحات میں شرکت سے اخذ کی ہے اور یہ کہ انہوں نے کندہ کی ایک خاتون سے شادی کی تھی جس سے پتہ چلتا ہے کہ کچھ نشاط باقی رہا ہو گا۔ لیکن جو کچھ مورخین نے ذکر کیا ہے اگر وہ ثابت ہو جائے تو یہ ان کے حق میں خوارق عادت (جو عام لوگوں میں نہیں پائی جاتیں) ثابت ہوں گی۔ اور اس سے مانع کیا ہے۔ چنانچہ ابوالشیخ طبقات الاصبہانیین میں عباس بن یزید کے طریق سے لکھتے ہیں کہ علماء کا فرمان ہے: سلمان فارسی رضی اللہ عنہ تین سو پچاس سال حیات رہے، جن میں سے ڈھائی سو(۲۵۰) سال پر تو اتفاق ہے اس میں انہیں کوئی شک نہیں۔ ابو ربیعہ ایادی بواسطہ ابو بریدہ وہ بحوالہ اپنے والد نقل کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: “اللہ تعالیٰ میرے صحابہ میں چار افراد کو (خصوصی طور پر)(6) پسند کرتا ہے”۔ جن میں سلمان رضی اللہ عنہ کا بھی ذکر کیا۔ سلیمان بن مغیرہ بحوالہ حمید بن ہلال نقل کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ابو درداء اور سلمان فارسی میں بھائی چارہ قائم فرمایا۔ بخاری میں حدیث ابی جحیفہ سے ان کے واقعہ میں اس کا مفہوم منقول ہے۔ اس واقعہ میں لکھا ہے کہ نبی صلی اللہ علیہ وسلم نے سیدنا ابو درداء رضی اللہ عنہ سے فرمایا: “سلمان کو تم سے زیادہ دین کی سمجھ ہے”۔ بقول ابو عبید(7) چھتیس (۳۶ھ) اور بقول خلیفہ سینتیس (۳۷ھ) میں انتقال ہوا۔ عبد الرزاق نے سیدنا انس رضی اللہ عنہ کے حوالہ سے نقل کیا ہے کہ ابن مسعود رضی اللہ عنہ آخری وقت میں سلمان رضی اللہ عنہ کے پاس آئے۔ اس سے پتہ چلتا ہے کہ ان کا انتقال ابن مسعود رضی اللہ عنہ سے پہلے ہوا ہے۔ جبکہ ابن مسعود چونتیس (۳۴ھ) سے پہلے فوت ہوئے۔ اس لیے ان کا انتقال بتیس (۳۲ھ) یا تینتیس (۳۳ھ) میں ہوا ہو گا۔ آپ اپنا وظیفہ صدقہ کر دیتے اور خود چٹائی بن کر کھاتے تھے۔(8)","",{"fn":"(1) اسد الغابہ (۲۱۴۹) استیعاب (۱۰۱۹)\n(2) الثقات (۱۵۷/۳)\n(3) استیعاب (۱۹۴/۲)\n(4) تہذیب التہذیب (۱۳۹/۴)\n(5) جامع المسانید (۳۴۶/۵)\n(6) مسند احمد (۲۳۰۲۹) جمع الجوامع (۵۱۹۰)\n(7) الطبقات (۱۰۷/۲)\n(8) مختصر تاریخ دمشق (۴۹/۱۰)"}],[3353,"§۳۳۵۹ ۔ سلمہ بن الادرع\nیہی ابن ذکوان ہیں، تذکرہ ہوتا ہے۔"],[3354,"§۳۳۶۰ ۔ سلمہ بن الازرق\nان کے والد الازرق کے حالات میں ذکر ہوا ہے۔"],[3355,"§۳۳۶۱ ۔ سلمہ بن اسلم(1)\nبن حریس ابن عدی بن مجدعہ بن حارثہ بن حارث ابن الخزرج بن عمرو بن مالک بن الاوس انصاری حارثی ابوسعید دادا کی نسبت سے بھی لکھے جاتے ہیں۔ ابن اسحاق(2) نے شرکاء بدر میں ان کا ذکر کیا ہے۔ آپ صلی اللہ علیہ وسلم نے انہیں بنی نضیر سے جنگ کے بعد عمرو بن امیہ کے ساتھ ابوسفیان سے جنگ کے لیے بھیجا تھا۔ اسے واقدی نے نقل کیا ہے۔ بقول ابو حاتم(3): جسر ابی عبید کے روز شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۵۱) استیعاب (۱۰۲۰) تجرید (۲۳۰/۱)\n(2) السیرۃ النبویہ (۲۴۸/۲)\n(3) الجرح والتعدیل (۱۵۶/۴)"}],[3356,"§۳۳۶۲ ۔ سلمہ بن الاسود(1)\nبن شجرہ بن ربیعہ بن وہب بن ربیعہ بن معاویہ کندی۔ ابن کلبی کا بیان ہے، یہ اور ان کے بھائی عکس بن الاسود نبی صلی اللہ علیہ وسلم کے پاس آئے تھے۔ ابن شاہین، طبری اور دار قطنی وغیرہ نے ان کا اتباع کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۵۲)"}],[3357,"§۳۳۶۳ ۔ سلمہ بن الاکوع\nوہی سلمہ بن عمرو بن الاکوع ہیں، تذکرہ ہوگا۔"],[3358,"§۳۳۶۴ ۔ سلمہ بن امیہ\nبن خلف الجمحی۔ ان کے بھائی ربیعہ کے حالات میں نسب گزر چکا ہے۔ خلیفہ بن خیاط نے مکہ رہنے والے صحابہ میں ان کا ذکر کیا ہے۔ “اخبار مدینہ” میں عمر بن شبہ نے بطریق سماک بن حرب بحوالہ ایک شخص نقل کیا ہے کہ سلمہ بن امیہ نے اپنی باندی سے شادی کر لی، اور گواہ اس کی والدہ اور بہن کو بنایا۔ سیدنا عمر رضی اللہ عنہ کے پاس مقدمہ پہنچا، آپ نے فرمایا: کیا لاعلمی سے ایسا کیا ہے؟ انہوں نے کہا: ہاں۔ فرمایا: دو عادل شخص گواہ بنالو ورنہ میں ابھی تفریق کرتا ہوں۔ عمر بن شبہ کا قول ہے کہ سلمی جو حکیم بن امیہ بن ارقص اسلمی کی باندی تھیں ان سے متعہ کیا جس سے بچہ پیدا ہوا تو انہوں نے بچہ کا انکار کر دیا۔ میں کہتا ہوں: ابن کلبی نے اس کا ذکر کیا اور یہ اضافہ بھی نقل کیا ہے۔ سیدنا عمر رضی اللہ عنہ کو اس کی اطلاع ملی تو آپ نے متعہ سے روک دیا یہ بھی بتایا جاتا ہے کہ سلمہ نے ایک عورت سے متعہ کیا، سیدنا عمر رضی اللہ عنہ کو معلوم ہوا تو انہوں نے انہیں دھمکایا۔ المحلی میں ابن حزم لکھتے ہیں: نبی صلی اللہ علیہ وسلم کی وفات کے بعد صحابہ میں بعض افراد متعہ کے حلال ہونے پر قائم رہے جن میں ابن مسعود، ابن عباس، جابر، سلمہ اور مغیرہ جو دونوں صاحبزادگانِ امیہ بن خلف تھے شامل تھے۔"],[3359,"§۳۳۶۵ ۔ سلمہ بن امیہ(1)\nبن ابی عبیدہ تمیمی، یعلی بن امیہ کے بھائی یعلی ہی کے حالات میں ان کا نسب بیان ہوگا۔ ان کی حدیث نسائی(2) میں ان کے بھتیجے صفوان بن عبد اللہ بن یعلی بن امیہ کی روایت سے بحوالہ ان کے اس شخص کے واقعہ کے بارے میں نقل کی ہے جس نے دوسرے کا ہاتھ چبالیا تھا۔ علامہ ابن عبد البر(3) لکھتے ہیں: ابن اسحاق کی کتاب میں ان کی ایک حدیث کے علاوہ کوئی حدیث نہیں۔ امام بخاری(4) فرماتے ہیں: اس میں ابن اسحاق اس کے خلاف روایت کرتے ہیں کہ یہ ان کی روایت سے ہے اس کی اسناد میں بھی اختلاف ہے۔ مؤرخین کا بیان ہے کہ سلمہ کوفہ فروکش ہوئے۔","",{"fn":"(1) اسد الغابہ (۲۱۵۵) استیعاب (۱۰۲۲) تجرید (۲۳۰/۱)\n(2) نسائی کتاب القسامۃ باب ذکر الاختلاف علی عطاء فی هذا الحدیث (۱۴۷۱)\n(3) استیعاب (۲۰۰/۲)\n(4) التاریخ الکبیر (۷۲/۲)"}],[3360,"§۳۳۶۶ ۔ سلمہ بن بدیل(1)\nبن ورقاء خزاعی۔ بقول ابن ابی حاتم(2) بحوالہ اپنے والد: انہیں شرف صحابیت حاصل ہے۔ ابن مندہ نے بطریق عبد الرحمن بن بشر بن الحکم روایت کی ہے کہ انہوں نے انہیں اور ان کے بھائیوں کو صحابہ میں شمار کیا ہے۔ وہ یہ ہیں: عبد اللہ عبد الرحمن، عثمان اور سلمہ۔","",{"fn":"(1) اسد الغابہ (۲۱۵۷) استیعاب (۱۰۲۳)\n(2) الجرح والتعدیل (۱۵۷/۴)"}],[3361,"§۳۳۶۷ ۔ سلمہ بن ثابت(1)\nبن وقش بن زغبہ بن رعوراء بن عبد الاشہل انصاری اشہلی۔ ابن اسحاق(2) نے شرکاء بدر اور شہداء اُحد میں ان کا ذکر کیا ہے، ایسا ہی ابن کلبی کا بیان ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۵۸) استیعاب (۱۰۲۴)\n(2) السیرۃ النبویہ (۹۶/۳)"}],[3362,"§۳۳۶۸ ۔ سلمہ بن الحارث\nابو غلیظ کنیتوں میں تذکرہ ہوگا۔"],[3363,"§۳۳۶۹ ۔ سلمہ بن حارثہ\nسہل بن حارثہ میں تذکرہ ہوتا ہے۔"],[3364,"§۳۳۷۰ ۔ سلمہ بن حارثہ اسلمی(1)\nبھائیوں میں سے ایک ہیں ان کے بھائی حمران کا تذکرہ پہلے ہو چکا ہے۔ ان کا ذکر صاحب استیعاب نے ان کے بھائی ہند بن حارثہ کے حالات میں بھی کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۶۰)"}],[3365,"§۳۳۷۱ ۔ سلمہ بن حاطب(1)\nبن عمرو بن عتیک بن امیہ بن زید انصاری۔ مؤرخین نے شرکاء بدر و اُحد میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۶۱) استیعاب (۱۰۲۵)"}],[3366,"§۳۳۷۲ ۔ سلمہ بن حبیش\nاسدی، اسد خزیمہ۔ حضرمی بن عامر کے حالات میں ان کا ذکر ہوا ہے۔ مدائنی نے اپنی سند سے لکھا ہے کہ سلمہ بن حبیش نے فرمایا، جب وہ ضرار بن الازور کے ساتھ آئے: ط “میں اور میری اونٹنی جس کی آنکھ سفید ہے جب ہم بمقام تین کی فرودگاہ پر پہنچے تو ہماری خواہشیں مختلف تھیں”۔"],[3367,"§۳۳۷۳ ۔ سلمہ بن الخطل الکنانی ثم العرجی(1)\nبقول ابن عساکر: انہیں شرف صحابیت حاصل ہے، پھر یہ روایت نقل کی کہ امیر معاویہ رضی اللہ عنہ نے خطبہ دیا، فرمایا: اللہ کی قسم! اللہ تعالیٰ نے سیدنا عمر رضی اللہ عنہ کو حاکم بنایا اور مجھے سیدنا عمر رضی اللہ عنہ نے والی بنایا تو میں نے ان سے کوئی خیانت نہیں کی اور نہ جھوٹ بولا۔ پھر اس خطبے کا ذکر کیا۔ تو سلمہ بن خطل جو بنی عریج بن عبد مناۃ بن کنانہ کے ایک فرد تھے کہنے لگے: معاویہ! اللہ کی قسم! تم سے انصاف ہوا لیکن تم نے انصاف نہیں کیا۔ آپ نے فرمایا: بیٹھ جاؤ تمہیں بیٹھنا نصیب نہ ہو۔ پھر امیر معاویہ نے ان سے فرمایا: مجھے یاد ہے جب تم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو تم نے سلام کیا تھا اور نبی صلی اللہ علیہ وسلم نے سلام کا جواب دیا تھا، پھر تم نے ہدیہ پیش کیا تو نبی صلی اللہ علیہ وسلم نے تمہارا ہدیہ قبول کر لیا۔ اور تم مسلمان ہو گئے تھے، تم اپنی قوم کے نیک شخص تھے۔ خطابی نے امیر معاویہ کے اس خطبے کا کچھ حصہ نقل کیا۔(2) اور ابوبکر بن الانباری نے اپنے فوائد میں اس کا مفہوم نقل کیا ہے، البتہ اس کے آخر میں یہ اضافہ نقل کیا ہے: تمہارے والد اس دن بلقاء کی جانب مالدار آدمی تھے۔","",{"fn":"(1) اسد الغابہ (۲۱۶۴) تجرید (۲۳۱/۱)\n(2) اسد الغابہ (۲۹۲/۲)"}],[3368,"§۳۳۷۴ ۔ سلمہ بن الحیسمان\nبن ایاس الخزاعی۔ ان کا نسب ان کے والد حیسمان کے تذکرہ میں بیان ہو چکا ہے۔ ابن کلبی نے ان کا تذکرہ ان کے والد کے ساتھ کیا ہے۔"],[3369,"§۳۳۷۵ ۔ سلمہ بن ذکوان\nبقول بعض: ابن الادرع۔ ابن مندہ کی روایت ہے کہ سلمہ بن ذکوان نے فرمایا: ایک رات میں رسول اللہ صلی اللہ علیہ وسلم کا پہرہ دے رہا تھا، آپ صلی اللہ علیہ وسلم کسی ضرورت سے باہر نکلے مسجد میں ایک شخص بلند آواز سے نماز پڑھ رہا تھا۔۔۔ (حدیث) اور دوسری سند سے جو روایت منقول ہے وہ یوں ہے کہ ابن الادرع نے فرمایا، اور مسند سلمہ بن الاکوع کے اثناء میں ابو یعلی نے یہ روایت بطریق داؤد بن قیس بواسطہ زید بن اسلم بحوالہ سلمہ نقل کی ہے۔ ان کا نسب بیان نہیں کیا، ہشام بن سعد کی روایت سے ظاہر ہوا کہ وہ ابن ادرع ہیں ابن اکوع نہیں۔ صحیح بخاری میں سیدنا سلمہ بن اکوع کی حدیث سے مروی ہے نبی صلی اللہ علیہ وسلم نے فرمایا: “تیر اندازی کرو میں ابن ادرع کے ساتھ ہوں”۔ بعض کا قول ہے: وہ سلمہ ہیں، بعض کا قول ہے: وہ مجن ہیں، یہی اکثر کے نزدیک ہے۔"],[3370,"§۳۳۷۶ ۔ سلمہ بن ربیدہ\nاور وہ ابن حیق بدلی ہیں۔ محبق نام میں اختلاف ہے۔"],[3371,"§۳۳۷۷ ۔ سلمہ بن ربیعہ العنزی\nابن شاہین اور طبری نے روایت کیا ہے کہ انہیں نبی صلی اللہ علیہ وسلم کے پاس آنے والے وفد میں شامل ہونے کی سعادت حاصل ہے۔"],[3372,"§۳۳۷۸ ۔ سلمہ بن زہیر\nسمرہ بن زہیر میں ان کا ذکر ہے۔"],[3373,"§۳۳۷۹ ۔ سلمہ بن سحیم الاسدی\nابن قانع اور ابن شاہین نے محمد بن نضلہ کے طریق سے روایت کیا ہے: ابن سکن بن سلمہ بن حکیم کہ مجھ سے میرے والد نے، انہوں نے اپنے والد سے، انہوں نے سلمہ بن حکیم سے روایت کی ہے، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس تھا کہ آپ صلی اللہ علیہ وسلم کے پاس ایک شخص آیا اور کہا: ہمارا ایک ساتھی اونٹنی پر سوار ہوا، پھر قصہ بیان کیا، اس کی اسناد میں نامعلوم راوی ہیں۔ اس میں محمد بن اسحاق بھی ہیں جو کمزور راوی ہیں۔"],[3374,"§۳۳۸۰ ۔ سلمہ بن سعد بن ضریم العنزی\nبقول بعض ابن سعید، ابن قانع نے ان کے نسب میں مریم کے بعد یہ اضافہ کیا ہے: ابن ہمام بن کامل، ابن عبد البر کا قول ہے۔ ان کی حدیث ہے: عنزہ اچھا قبیلہ ہے، ان پر بغاوت کی جائے گی اور ان کی مدد کی جائے گی، یہ حضرت شعیب علیہ السلام کی قوم اور حضرت موسیٰ علیہ السلام کے علماء ہیں۔ (الحدیث) ان سے ان کے بیٹے سعید بن سلمہ کے علاوہ کسی نے روایت نہیں کی، طبرانی نے حفص بن سنان بن قیس کے طریق سے بحوالہ سلمہ بن سعد روایت کیا ہے کہ وہ اور ان کے اہل خانہ اور بیٹوں کی جماعت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور اجازت طلب کی، اور کہا: یہ عنزہ کا وفد ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: “واہ واہ! عنزہ اچھا قبیلہ ہے۔ ان پر بغاوت ہوگی اور ان کی مدد کی جائے گی۔ حضرت شعیب علیہ السلام کی قوم اور حضرت موسیٰ علیہ السلام کے علماء کو خوش آمدید۔ اے سلمہ! اپنی حاجت بتاؤ”۔ پھر حدیث بیان کی، اس کی اسناد میں نامعلوم راوی ہیں۔ ابن قانع نے عبد اللہ بن سویہ کی روایت سے بحوالہ حفص بن سلمہ نقل کیا ہے۔ نسب میں سے سنان کا ذکر چھوڑ دیا۔ فرمایا: بحوالہ حفص بن سلمہ بن حفص بن میتب بن قیس بن سلمہ بن سعد کہ ہم سے میرے والد نے بحوالہ حفص بن میتب، انہوں نے میتب سے، انہوں نے سلمہ سے روایت کی کہ وہ وفد میں نبی کریم صلی اللہ علیہ وسلم کے پاس گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: واہ واہ! یہ حدیث اس قول تک ہے ان کی مدد کی جائے گی، حضرت شعیب علیہ السلام کی قوم اور حضرت موسیٰ علیہ السلام کے علماء کو مرحبا۔ فرماتے ہیں: یہ طویل حدیث ہے، میں نے اسے مختصر کر دیا ہے۔"],[3375,"§۳۳۸۱ ۔ سلمہ بن سلام الاسرائیلی\nکلبی نے اپنی تفسیر میں بحوالہ ابن عباس رضی اللہ عنہما روایت کیا کہ، فرماتے ہیں، یہ آیت: “اے ایمان والو! اللہ اور اس کے رسول پر ایمان لاؤ”۔ سیدنا عبد اللہ بن سلام، اسد، اسید، کعب کے بیٹے ہیں اور ثعلبہ بن قیس سیدنا عبد اللہ بن سلام کی بہن کے بیٹے سلام، سلمہ ان کے بھتیجے، یاسین بن یامین کے بارے میں نازل ہوئی اور یہ اہل کتاب میں سے ایمان لانے والے ہیں۔"],[3376,"§۳۳۸۲ ۔ سلمہ بن سلامہ\nبن وقش بن زغبہ بن زعوراء بن عبد الاشہل انصاری اشہلی، ابو عوف، ابن اسحاق، موسیٰ بن عقبہ وغیرہ نے ان کا ذکر کیا ہے۔ ان سب کا قول ہے کہ بدر اور دوسرے غزوات میں حاضر ہوئے۔ احمد نے محمود بن لبید کے طریق سے بحوالہ سلمہ بن سلامہ بن وقش کے حوالہ سے روایت کی ہے۔ وہ اصحاب بدر میں سے تھے۔ فرماتے ہیں: بنو عبد الاشہل میں ہمارا ایک یہودی پڑوسی تھا، فرماتے ہیں: وہ ہمارے پاس آیا، پھر آپ صلی اللہ علیہ وسلم کے مبعوث ہونے کا ذکر کیا، یہ طویل حدیث(1) نبی کریم صلی اللہ علیہ وسلم کی بعثت سے پہلے نبوت کی علامتوں کے بارے میں ہے۔ طبرانی نے زید بن جبیرہ کے طریق سے بحوالہ سلمہ بن سلامہ بن وقش روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے کھانا کھایا اور وضو نہیں کیا۔ بعض کا قول ہے کہ سیدنا عمر رضی اللہ عنہ نے انہیں یمامہ کا گورنر بنایا تھا، سیدنا عوف بن سلمہ کے سوانح میں ان کا ذکر کیا ہے۔ ابن کلبی نے ذکر کیا ہے کہ غزوہ مریسیع میں سیدنا عمر رضی اللہ عنہ کو جب عبد اللہ بن ابی کی بات پہنچی تو انہوں نے نبی کریم صلی اللہ علیہ وسلم کو بتایا، آپ صلی اللہ علیہ وسلم نے فرمایا: “سلمہ بن سلامہ بن وقش کو بھیجو وہ تمہارے پاس اس کا سر لے آئے”۔ اس وقت عبد اللہ بن ابی نے کہا جو کہا، ابن ابی شیبہ نے ابو سفیان مولی ابن ابو احمد کے طریق سے روایت کیا ہے کہ وہ بنو عبد اشہل کی امامت کرتے تھے، وہ مکاتب تھے، ان لوگوں میں صحابہ میں سے محمد بن سلمہ، سلمہ بن سلامہ تھے۔ ابراہیم بن منذر کا قول ہے ۳۴ھ میں وفات پائی۔ ایک قول ہے: ۴۵ھ تک زندہ رہے۔ بعض نے کہا: انہوں نے چوہتر(۷۴) سال کی عمر میں مدینہ میں وفات پائی۔","",{"fn":"(1) مسند احمد (۴۶۷/۳)"}],[3377,"§۳۳۸۳ ۔ سلمہ بن سلام الثعلبی\nاہل کوفہ میں سے ہیں۔(1) بغوی کا قول ہے: عطا بن سائب کے طریق سے روایت کیا ہے، مجھ سے ہانی بن عبد اللہ نے حدیث بیان کی، فرماتے ہیں: میرے دادا سلمہ بن سلامہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، پھر قصہ بیان کیا۔ انہوں نے کہا: یا رسول اللہ! کیا میں ان سے جزیہ لوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں! جزیہ یہود و نصاری پر ہے، ان سے زکوۃ لو۔ اسے طبرانی نے دوسرے طریق سے، انہوں نے ابو امیہ سے جو بنو تغلب کا ایک آدمی ہے سے نقل کیا ہے۔ واللہ اعلم۔ اسے ابن قانع نے دوسرے طریق سے بحوالہ عطا نقل کیا ہے۔ فرماتے ہیں: بحوالہ حرب بن عبد اللہ، انہوں نے اپنے دادا ابو امیہ سے نقل کیا ہے، اور صحابی سلامہ بن سالم ثعلبی کا عنوان قائم کیا ہے، مسند میں ان کے نام کا ذکر کیا، لہذا بغوی کے قول پر اعتماد کیا جائے گا۔","",{"fn":"(1) اسد الغابہ (۲۱۷۳)"}],[3378,"§۳۳۸۴ ۔ سلمہ بن ابو سلمہ بن عبد الاسد(1)\nان کا نسب ان کے والد کے حالات میں بیان ہوگا۔ جن کا نام عبد اللہ بن عبد الاسد تھا۔ سلمہ نبی صلی اللہ علیہ وسلم کے پروردہ تھے۔ مغازی میں ابن اسحاق کی حدیث ام سلمہ سے روایت ہے، فرماتی ہیں: جب ابو سلمہ نے ہجرت کا عزم کیا تو میرا اونٹ تیار کر کے اس پر مجھے سوار کیا، میرے بیٹے سلمہ کو میری گود میں رکھا، پھر میرے اونٹ کی مہار پکڑ کر چل پڑے۔ ابن اسحاق(2) کی روایت ہے مجھے اس شخص نے بتایا جس پر مجھے اعتماد ہے کہ عبد اللہ بن شداد کا قول ہے کہ نبی صلی اللہ علیہ وسلم سے ام سلمہ رضی اللہ عنہا کی جس نے شادی کی وہ انہی کا بیٹا سلمہ بن ابی سلمہ تھا (جس کے صلہ میں) آپ صلی اللہ علیہ وسلم نے امامہ بنت حمزہ رضی اللہ عنہا کا نکاح ان سے کر دیا۔ اس وقت وہ دونوں کم سن تھے۔ پھر فوت ہونے تک انہیں اکٹھے ہونے کا موقعہ نہ ملا۔ ایک موقعہ پر آپ صلی اللہ علیہ وسلم نے فرمایا: “کیا میں نے سلمہ کو بدلہ دے دیا؟” بلاذری کا قول ہے کہ آپ صلی اللہ علیہ وسلم کے بیٹے عمر نے یہ نکاح کیا تھا۔ بہر کیف پہلا قول زیادہ مضبوط ہے۔ ادھر واقدی اور ان کے اتباع میں ابو حاتم(3) وغیرہ کا گمان ہے کہ مسلمہ خلافت عبد الملک بن مروان تک زندہ رہے۔ اور دونوں اکٹھے ہونے سے پہلے فوت ہو گئے سے مراد یہ ہے کہ ان کی اہلیہ رخصتی سے پہلے اور پھر کچھ ہی عرصہ بعد یہ بھی فوت ہو گئے تھے۔ لیکن ابن کلبی کا قول ہے: بقول بعض مسلمہ، امامہ کی رخصی سے پہلے فوت ہوئے ہیں۔","",{"fn":"(1) استیعاب (۱۰۲۷)\n(2) المغازی (۲۶۱)\n(3) الجرح والتعدیل (۱۶۳/۴)"}]])